(348254,38695,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün sabah aynı belge yığınını ...'::text,'damgalıyor'::text,'damgalıyor'::text,'damgalar'::text,'Bütün sabah aynı belge yığınını damgalıyor.'::text),
(348255,38695,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délelőtt ugyanazt a dokumentumkupacot ...'::text,'pecsételi'::text,'pecsételi'::text,'pecsételi'::text,'Egész délelőtt ugyanazt a dokumentumkupacot pecsételi.'::text),
(348258,38696,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Papiere flogen durch die Luft, während er das letzte Dokument ...'::text,'stempelte'::text,'stempelte'::text,'gestempelt hat'::text,'Papiere flogen durch die Luft, während er das letzte Dokument stempelte.'::text),
(348262,38696,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Папери злітали в повітря, поки він ... останній документ.'::text,'штампував'::text,'проштампував'::text,'проштампував'::text,'Папери злітали в повітря, поки він штампував останній документ.'::text),
(348261,38696,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los papeles volaban por el aire mientras ... el último documento.'::text,'estaba sellando'::text,'selló'::text,'ha sellado'::text,'Los papeles volaban por el aire mientras estaba sellando el último documento.'::text),
(348260,38696,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des papiers volaient dans les airs pendant qu''il ... le dernier document.'::text,'tamponnait'::text,'a tamponné'::text,'a tamponné'::text,'Des papiers volaient dans les airs pendant qu''il tamponnait le dernier document.'::text),
(348263,38696,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O son belgeyi ... kâğıtlar havaya uçtu.'::text,'damgalarken'::text,'damgaladığında'::text,'damgaladığında'::text,'O son belgeyi damgalarken kâğıtlar havaya uçtu.'::text),
(348264,38696,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A papírok repültek a levegőben, miközben ... az utolsó dokumentumot.'::text,'pecsételte'::text,'lepecsételte'::text,'lepecsételte'::text,'A papírok repültek a levegőben, miközben pecsételte az utolsó dokumentumot.'::text),
(348267,38697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher ... er vierzig Dokumente abgelehnt, und jedes bekommt ein rotes X. Starke Leistung.'::text,'hat'::text,'hat'::text,'hat'::text,'Bisher hat er vierzig Dokumente abgelehnt, und jedes bekommt ein rotes X. Starke Leistung.'::text),
(348271,38697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки що він ... сорок документів, і кожен отримує червоний X. Чудова робота.'::text,'відхилив'::text,'відхиляв'::text,'відхиляє'::text,'Поки що він відхилив сорок документів, і кожен отримує червоний X. Чудова робота.'::text),
(348270,38697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora ... cuarenta documentos, y cada uno recibe una X roja. Buen trabajo.'::text,'ha rechazado'::text,'lleva rechazando'::text,'está rechazando'::text,'Hasta ahora ha rechazado cuarenta documentos, y cada uno recibe una X roja. Buen trabajo.'::text),
(348269,38697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, il ... quarante documents, et chacun reçoit un X rouge. Beau travail.'::text,'a refusé'::text,'refuse'::text,'est en train de refuser'::text,'Jusqu''ici, il a refusé quarante documents, et chacun reçoit un X rouge. Beau travail.'::text),
(348272,38697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar kırk belgeyi ... ve her biri kırmızı X alıyor. Harika iş.'::text,'reddetti'::text,'reddediyor'::text,'reddediyor'::text,'Şimdiye kadar kırk belgeyi reddetti ve her biri kırmızı X alıyor. Harika iş.'::text),
(348273,38697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig negyven dokumentumot ..., és mindegyik piros X-et kap. Szép munka.'::text,'utasított el'::text,'utasít el'::text,'utasít el'::text,'Eddig negyven dokumentumot utasított el, és mindegyik piros X-et kap. Szép munka.'::text),
(348276,38698,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Telefonat endete, ... er schon jedes Dokument auf seinem Schreibtisch abgestempelt. Ruhiger Tag, klar.'::text,'hatte'::text,'hat'::text,'hatte'::text,'Als das Telefonat endete, hatte er schon jedes Dokument auf seinem Schreibtisch abgestempelt. Ruhiger Tag, klar.'::text),
(348280,38698,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли дзвінок закінчився, він уже ... кожен документ на своєму столі. Спокійний день, звісно.'::text,'проштампував'::text,'проштампував'::text,'штампує'::text,'Коли дзвінок закінчився, він уже проштампував кожен документ на своєму столі. Спокійний день, звісно.'::text),
(348279,38698,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando terminó la llamada, ... todos los documentos de su escritorio. Día tranquilo, está claro.'::text,'había sellado'::text,'ha sellado'::text,'sella'::text,'Para cuando terminó la llamada, había sellado todos los documentos de su escritorio. Día tranquilo, está claro.'::text),
(348278,38698,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''appel s''est terminé, il ... chaque document sur son bureau. Journée calme, clairement.'::text,'avait tamponné'::text,'a tamponné'::text,'tamponne'::text,'Quand l''appel s''est terminé, il avait tamponné chaque document sur son bureau. Journée calme, clairement.'::text),
(348281,38698,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görüşme bittiğinde masasındaki her belgeyi çoktan ...; sakin bir gün, belli ki.'::text,'damgalamıştı'::text,'damgaladı'::text,'damgalıyor'::text,'Görüşme bittiğinde masasındaki her belgeyi çoktan damgalamıştı; sakin bir gün, belli ki.'::text),
(348282,38698,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a hívás véget ért, ... az asztalán lévő összes dokumentumot. Nyugis nap, nyilván.'::text,'lepecsételte'::text,'lepecsételte'::text,'pecsételi'::text,'Mire a hívás véget ért, lepecsételte az asztalán lévő összes dokumentumot. Nyugis nap, nyilván.'::text),
(348285,38699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um 17 Uhr ... er wieder Dokumente, genauso friedlich. Natürlich.'::text,'stempelt'::text,'stempelt'::text,'stempelt'::text,'Morgen um 17 Uhr stempelt er wieder Dokumente, genauso friedlich. Natürlich.'::text),
(348289,38699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о 17:00 він знову ... документи, так само спокійно. Очевидно.'::text,'штампуватиме'::text,'проштампує'::text,'штампує'::text,'Завтра о 17:00 він знову штампуватиме документи, так само спокійно. Очевидно.'::text),
(348288,38699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las 17:00 ... documentos otra vez, igual de tranquilo. Obviamente.'::text,'estará sellando'::text,'sellará'::text,'sella'::text,'Mañana a las 17:00 estará sellando documentos otra vez, igual de tranquilo. Obviamente.'::text),
(348287,38699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à 17 h, il ... encore des documents, tout aussi paisiblement. Évidemment.'::text,'tamponnera'::text,'tamponnera'::text,'tamponne'::text,'Demain à 17 h, il tamponnera encore des documents, tout aussi paisiblement. Évidemment.'::text),
(348290,38699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın saat 17.00''de yine aynı huzurla belge ...; tabii ki.'::text,'damgalıyor olacak'::text,'damgalayacak'::text,'damgalıyor'::text,'Yarın saat 17.00''de yine aynı huzurla belge damgalıyor olacak; tabii ki.'::text),
(348291,38699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délután 5-kor megint ... a dokumentumokat, ugyanolyan békésen. Nyilván.'::text,'pecsételni fogja'::text,'pecsételni fogja'::text,'pecsételi'::text,'Holnap délután 5-kor megint pecsételni fogja a dokumentumokat, ugyanolyan békésen. Nyilván.'::text),
(348294,38700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist das Ende! Ich ... heute kein einziges Dokument mehr, ich schwöre!'::text,'stemple'::text,'stemple'::text,'stemple'::text,'Das ist das Ende! Ich stemple heute kein einziges Dokument mehr, ich schwöre!'::text),
(348298,38700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це кінець! Сьогодні я ... більше жодного документа, клянуся!'::text,'не проштампую'::text,'не штампуватиму'::text,'не штампую'::text,'Це кінець! Сьогодні я не проштампую більше жодного документа, клянуся!'::text),
(348297,38700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esto se acabó! Hoy ... ni un documento más, ¡lo juro!'::text,'no sellaré'::text,'no estaré sellando'::text,'no estoy sellando'::text,'¡Esto se acabó! Hoy no sellaré ni un documento más, ¡lo juro!'::text),
(348296,38700,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est la fin ! Je ... plus un seul document aujourd''hui, je le jure !'::text,'ne tamponnerai'::text,'ne tamponnerai'::text,'ne tamponne'::text,'C''est la fin ! Je ne tamponnerai plus un seul document aujourd''hui, je le jure !'::text),
(348299,38700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu son! Bugün tek bir belge daha ..., yemin ederim!'::text,'damgalamayacağım'::text,'damgalamıyor olacağım'::text,'damgalamıyorum'::text,'Bu son! Bugün tek bir belge daha damgalamayacağım, yemin ederim!'::text),
(348300,38700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a vég! Ma már egyetlen dokumentumot sem ..., esküszöm!'::text,'pecsételek le'::text,'fogok pecsételni'::text,'pecsételek'::text,'Ez a vég! Ma már egyetlen dokumentumot sem pecsételek le, esküszöm!'::text),
(348312,38702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er das Dokument noch fester stempelt, ... die Papiere vom Schreibtisch.'::text,'fliegen'::text,'fliegen'::text,'flogen'::text,'Wenn er das Dokument noch fester stempelt, fliegen die Papiere vom Schreibtisch.'::text),
(348316,38702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він штампуватиме той документ ще сильніше, папери ... зі столу.'::text,'злетять'::text,'злетіли б'::text,'злетіли'::text,'Якщо він штампуватиме той документ ще сильніше, папери злетять зі столу.'::text),
(348315,38702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sella ese documento todavía más fuerte, los papeles ... de la mesa.'::text,'saldrán volando'::text,'saldrían volando'::text,'salieron volando'::text,'Si sella ese documento todavía más fuerte, los papeles saldrán volando de la mesa.'::text),
(348314,38702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il tamponne ce document encore plus fort, les papiers ... du bureau.'::text,'s''envoleront'::text,'s''envoleraient'::text,'se sont envolés'::text,'S''il tamponne ce document encore plus fort, les papiers s''envoleront du bureau.'::text),
(348317,38702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O belgeyi biraz daha sert damgalarsa kâğıtlar masadan ...'::text,'uçacak'::text,'uçardı'::text,'uçtu'::text,'O belgeyi biraz daha sert damgalarsa kâğıtlar masadan uçacak.'::text),
(348318,38702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még erősebben pecsételi le azt a dokumentumot, a papírok ... az asztalról.'::text,'lerepülnek'::text,'lerepülnének'::text,'lerepültek'::text,'Ha még erősebben pecsételi le azt a dokumentumot, a papírok lerepülnek az asztalról.'::text),
(348321,38703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... er jedes Dokument jeden einzelnen Tag mit einem roten X.'::text,'stempelt'::text,'stempelt'::text,'stempelt'::text,'Mädel, anscheinend stempelt er jedes Dokument jeden einzelnen Tag mit einem roten X.'::text),
(348325,38703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... кожен документ червоним X щодня.'::text,'штампує'::text,'штампує'::text,'проштампував'::text,'Подруго, кажуть, він штампує кожен документ червоним X щодня.'::text),
(348324,38703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, por lo visto ... cada documento con una X roja todos los días.'::text,'sella'::text,'está sellando'::text,'ha sellado'::text,'Tía, por lo visto sella cada documento con una X roja todos los días.'::text),
(348323,38703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... chaque document d''un X rouge tous les jours.'::text,'tamponne'::text,'est en train de tamponner'::text,'a tamponné'::text,'Meuf, apparemment il tamponne chaque document d''un X rouge tous les jours.'::text),
(348326,38703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre her gün her belgeyi kırmızı bir X ile ...'::text,'damgalıyormuş'::text,'damgalıyormuş'::text,'damgalamış'::text,'Kızım, duyduğuma göre her gün her belgeyi kırmızı bir X ile damgalıyormuş.'::text),
(348327,38703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag minden egyes nap ... minden dokumentumot egy piros X-szel.'::text,'pecsételi'::text,'pecsételi'::text,'lepecsételte'::text,'Csajszi, állítólag minden egyes nap pecsételi minden dokumentumot egy piros X-szel.'::text),
(364692,40522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, während du den Teppich ..., hat das ganze Zimmer ein cooles Upgrade bekommen.'::text,'ausrolltest'::text,'ausgerollt hast'::text,'ausgerollt hast'::text,'Ehrlich, während du den Teppich ausrolltest, hat das ganze Zimmer ein cooles Upgrade bekommen.'::text),
(364696,40522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, поки ти ... той килим, уся кімната отримала крутий апгрейд.'::text,'розстеляв'::text,'розстелив'::text,'розстелив'::text,'Чесно, поки ти розстеляв той килим, уся кімната отримала крутий апгрейд.'::text),
(364695,40522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, mientras ... esa alfombra, toda la habitación recibió una mejora guay.'::text,'extendías'::text,'extendiste'::text,'has extendido'::text,'Sinceramente, mientras extendías esa alfombra, toda la habitación recibió una mejora guay.'::text),
(364694,40522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, pendant que tu ... ce tapis, toute la pièce a eu un upgrade cool.'::text,'déroulais'::text,'as déroulé'::text,'as déroulé'::text,'Franchement, pendant que tu déroulais ce tapis, toute la pièce a eu un upgrade cool.'::text),
(364697,40522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen o halıyı ..., bütün oda havalı bir değişim geçirdi.'::text,'sererken'::text,'serdiğinde'::text,'serdiğinde'::text,'Açıkçası sen o halıyı sererken, bütün oda havalı bir değişim geçirdi.'::text),
(364698,40522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, amíg ... azt a szőnyeget, az egész szoba menő upgrade-et kapott.'::text,'terítetted ki'::text,'kiterítetted'::text,'kiterítetted'::text,'Őszintén, amíg terítetted ki azt a szőnyeget, az egész szoba menő upgrade-et kapott.'::text),
(364701,40523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... den ganzen Vormittag Teppiche wie ein Profi, und das sieht man.'::text,'verlegst'::text,'verlegst'::text,'verlegst'::text,'Ehrlich gesagt, du verlegst den ganzen Vormittag Teppiche wie ein Profi, und das sieht man.'::text),
(364705,40523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти весь ранок ... килими як профі, і це видно.'::text,'розстеляєш'::text,'розстеляєш'::text,'розстеляєш'::text,'Не буду брехати, ти весь ранок розстеляєш килими як профі, і це видно.'::text),
(364704,40523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... alfombras como un pro toda la mañana, y se nota.'::text,'llevas extendiendo'::text,'estás extendiendo'::text,'extiendes'::text,'No voy a mentir, llevas extendiendo alfombras como un pro toda la mañana, y se nota.'::text),
(364703,40523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... des tapis comme un pro depuis ce matin, et ça se voit.'::text,'déroules'::text,'es en train de dérouler'::text,'déroules'::text,'Je vais pas mentir, tu déroules des tapis comme un pro depuis ce matin, et ça se voit.'::text),
(364706,40523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bütün sabah profesyonel gibi halı ... ve bu belli oluyor.'::text,'seriyorsun'::text,'seriyorsun'::text,'serersin'::text,'Yalan yok, bütün sabah profesyonel gibi halı seriyorsun ve bu belli oluyor.'::text),
(364707,40523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, egész délelőtt úgy ... a szőnyegeket, mint egy profi, és ez látszik.'::text,'teríted'::text,'teríted'::text,'teríted'::text,'Nem hazudok, egész délelőtt úgy teríted a szőnyegeket, mint egy profi, és ez látszik.'::text),
(364728,40526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, dass er den Teppich schon vor Wochen ..., weil der nackte Boden kalt war.'::text,'verlegt hätte'::text,'verlegt hat'::text,'verlegen würde'::text,'Er wünscht sich, dass er den Teppich schon vor Wochen verlegt hätte, weil der nackte Boden kalt war.'::text),
(364732,40526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб ... килим ще кілька тижнів тому, бо гола підлога була холодною.'::text,'постелив'::text,'постелив'::text,'постелив'::text,'Він хотів би, щоб постелив килим ще кілька тижнів тому, бо гола підлога була холодною.'::text),
(364731,40526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía ... la alfombra hace semanas, porque el suelo desnudo estaba frío.'::text,'haber puesto'::text,'haber puesto'::text,'poner'::text,'Desearía haber puesto la alfombra hace semanas, porque el suelo desnudo estaba frío.'::text),
(364730,40526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... le tapis il y a des semaines, parce que le sol nu était froid.'::text,'avoir posé'::text,'avoir posé'::text,'poser'::text,'Il aimerait avoir posé le tapis il y a des semaines, parce que le sol nu était froid.'::text),
(364733,40526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke halıyı haftalar önce ... diye düşünüyor, çünkü çıplak zemin soğuktu.'::text,'sermiş olsaydı'::text,'serdi'::text,'serse'::text,'Keşke halıyı haftalar önce sermiş olsaydı diye düşünüyor, çünkü çıplak zemin soğuktu.'::text),
(364734,40526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak már hetekkel ezelőtt ... a szőnyeget, mert a csupasz padló hideg volt.'::text,'leterítette volna'::text,'leterítette'::text,'leterítené'::text,'Azt kívánja, bárcsak már hetekkel ezelőtt leterítette volna a szőnyeget, mert a csupasz padló hideg volt.'::text),
(364737,40527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Teppich, ... er über den Holzboden gelegt hat, ist rot und blau.'::text,'den'::text,'den'::text,'wer'::text,'Der Teppich, den er über den Holzboden gelegt hat, ist rot und blau.'::text),
(364741,40527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Килим, ... він розстелив на дерев''яній підлозі, червоно-синій.'::text,'який'::text,'який'::text,'хто'::text,'Килим, який він розстелив на дерев''яній підлозі, червоно-синій.'::text),
(364740,40527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La alfombra, ... extendió sobre el suelo de madera, es roja y azul.'::text,'que'::text,'que'::text,'quien'::text,'La alfombra, que extendió sobre el suelo de madera, es roja y azul.'::text),
(364739,40527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tapis, ... il a étendu sur le parquet, est rouge et bleu.'::text,'qu'''::text,'qu'''::text,'qui'::text,'Le tapis, qu'' il a étendu sur le parquet, est rouge et bleu.'::text),
(364742,40527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap zemine ... serdiği halı kırmızı ve mavi.'::text,''::text,NULL::text,NULL::text,'Ahşap zemine serdiği halı kırmızı ve mavi.'::text),
(364743,40527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szőnyeg, ... a fapadlóra terített, piros-kék.'::text,'amelyet'::text,'amelyet'::text,'aki'::text,'A szőnyeg, amelyet a fapadlóra terített, piros-kék.'::text),
(364746,40528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... er den Teppich glatt ausgelegt hatte, legte er sich mit ausgestreckten Armen darauf.'::text,'Sobald'::text,'Trotz'::text,'Für den Fall, dass'::text,'Sobald er den Teppich glatt ausgelegt hatte, legte er sich mit ausgestreckten Armen darauf.'::text),
(364750,40528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він рівно розстелив килим, то ліг на нього, розкинувши руки.'::text,'Щойно'::text,'Попри'::text,'На випадок, якщо'::text,'Щойно він рівно розстелив килим, то ліг на нього, розкинувши руки.'::text),
(364749,40528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... extendió la alfombra, se tumbó en ella con los brazos abiertos.'::text,'En cuanto'::text,'A pesar de'::text,'Por si'::text,'En cuanto extendió la alfombra, se tumbó en ella con los brazos abiertos.'::text),
(364748,40528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... il avait étalé le tapis, il s''est allongé dessus, les bras écartés.'::text,'Dès qu'''::text,'Malgré'::text,'Au cas où'::text,'Dès qu'' il avait étalé le tapis, il s''est allongé dessus, les bras écartés.'::text),
(364751,40528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Halıyı düz ... kollarını açarak üzerine uzandı.'::text,'serer sermez'::text,'sermesine rağmen'::text,'serdiği takdirde'::text,'Halıyı düz serer sermez kollarını açarak üzerine uzandı.'::text),
(364752,40528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... simára terítette a szőnyeget, kitárt karokkal lefeküdt rá.'::text,'Amint'::text,'Annak ellenére, hogy'::text,'Arra az esetre, ha'::text,'Amint simára terítette a szőnyeget, kitárt karokkal lefeküdt rá.'::text),
(364755,40529,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wusste, dass er den Teppich vor der Deadline um 10 Uhr ...'::text,'verlegen würde'::text,'verlegen wird'::text,'verlegt'::text,'Er wusste, dass er den Teppich vor der Deadline um 10 Uhr verlegen würde.'::text),
(364759,40529,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він знав, що ... килим до дедлайну о 10:00.'::text,'постелить'::text,'постелить'::text,'стелить'::text,'Він знав, що постелить килим до дедлайну о 10:00.'::text),
(364758,40529,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que ... la alfombra antes del deadline de las 10:00.'::text,'pondría'::text,'pondrá'::text,'está poniendo'::text,'Sabía que pondría la alfombra antes del deadline de las 10:00.'::text),
(364757,40529,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il savait qu''il ... le tapis avant la deadline de 10 h.'::text,'poserait'::text,'posera'::text,'pose'::text,'Il savait qu''il poserait le tapis avant la deadline de 10 h.'::text),
(364760,40529,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Halıyı saat 10.00 deadline''ından önce ... biliyordu.'::text,'sereceğini'::text,'sereceğini'::text,'serdiğini'::text,'Halıyı saat 10.00 deadline''ından önce sereceğini biliyordu.'::text),
(364761,40529,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy a délelőtt 10-es határidő előtt ... a szőnyeget.'::text,'leteríti'::text,'le fogja teríteni'::text,'teríti'::text,'Tudta, hogy a délelőtt 10-es határidő előtt leteríti a szőnyeget.'::text),
(364764,40530,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Moment ... er den zusammengerollten Teppich über den Holzboden.'::text,'entrollt'::text,'entrollt'::text,'ist ausgelegt worden'::text,'Im Moment entrollt er den zusammengerollten Teppich über den Holzboden.'::text),
(364768,40530,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз він ... згорнутий килим по дерев''яній підлозі.'::text,'розстеляє'::text,'розстеляє'::text,'був розстелений'::text,'Зараз він розстеляє згорнутий килим по дерев''яній підлозі.'::text),
(364767,40530,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento ... la alfombra enrollada sobre el suelo de madera.'::text,'está extendiendo'::text,'extiende'::text,'ha sido extendida'::text,'En este momento está extendiendo la alfombra enrollada sobre el suelo de madera.'::text),
(364766,40530,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... le tapis roulé sur le parquet.'::text,'est en train de dérouler'::text,'déroule'::text,'a été déroulé'::text,'En ce moment, il est en train de dérouler le tapis roulé sur le parquet.'::text),
(364769,40530,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda rulo halıyı ahşap zemine ...'::text,'seriyor'::text,'serer'::text,'serilmiş'::text,'Şu anda rulo halıyı ahşap zemine seriyor.'::text),
(364770,40530,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a feltekert szőnyeget a fapadlón.'::text,'teríti ki'::text,'teríti ki'::text,'ki lett terítve'::text,'Épp most teríti ki a feltekert szőnyeget a fapadlón.'::text),
(364773,40531,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise ... er den Teppich, als er sich hinlegte, schon vollkommen flach ausgelegt.'::text,'hatte'::text,'hat'::text,'hatte'::text,'Bemerkenswerterweise hatte er den Teppich, als er sich hinlegte, schon vollkommen flach ausgelegt.'::text),
(364777,40531,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що коли він ліг, він уже ... килим зовсім рівно.'::text,'розстелив'::text,'розстелив'::text,'розстеляє'::text,'Примітно, що коли він ліг, він уже розстелив килим зовсім рівно.'::text),
(364776,40531,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Curiosamente, para cuando se tumbó, ya ... la alfombra completamente plana.'::text,'había extendido'::text,'ha extendido'::text,'extiende'::text,'Curiosamente, para cuando se tumbó, ya había extendido la alfombra completamente plana.'::text),
(364775,40531,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, au moment où il s''est allongé, il ... le tapis parfaitement à plat.'::text,'avait posé'::text,'a posé'::text,'pose'::text,'Fait remarquable, au moment où il s''est allongé, il avait posé le tapis parfaitement à plat.'::text),
(364778,40531,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde, uzandığında halıyı tamamen düz ...'::text,'sermişti'::text,'serdi'::text,'seriyor'::text,'Dikkat çekici biçimde, uzandığında halıyı tamamen düz sermişti.'::text),
(364779,40531,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó módon, mire lefeküdt, már teljesen simára ... a szőnyeget.'::text,'terítette'::text,'terítette'::text,'teríti'::text,'Figyelemre méltó módon, mire lefeküdt, már teljesen simára terítette a szőnyeget.'::text),
(364782,40532,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend ... du in jedem Zimmer Teppiche, und ehrlich, Respekt.'::text,'verlegst'::text,'verlegst'::text,'verlegst'::text,'Bis heute Abend verlegst du in jedem Zimmer Teppiche, und ehrlich, Respekt.'::text),
(364786,40532,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора ти ... килими в кожній кімнаті, і чесно, респект.'::text,'розстелиш'::text,'розстелиш'::text,'розстеляєш'::text,'До вечора ти розстелиш килими в кожній кімнаті, і чесно, респект.'::text),
(364785,40532,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche ... alfombras en todas las habitaciones, y sinceramente, respeto.'::text,'habrás puesto'::text,'pondrás'::text,'pones'::text,'Para esta noche habrás puesto alfombras en todas las habitaciones, y sinceramente, respeto.'::text),
(364784,40532,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, tu ... des tapis dans chaque pièce, et franchement, respect.'::text,'auras posé'::text,'poseras'::text,'poses'::text,'D''ici ce soir, tu auras posé des tapis dans chaque pièce, et franchement, respect.'::text),
(364787,40532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar her odaya halı ... ve açıkçası, saygılar.'::text,'sermiş olacaksın'::text,'sereceksin'::text,'serersin'::text,'Bu akşama kadar her odaya halı sermiş olacaksın ve açıkçası, saygılar.'::text),
(364788,40532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére minden szobában ... szőnyeget, és őszintén, respekt.'::text,'leterítesz'::text,'leterítesz'::text,'terítesz'::text,'Estére minden szobában leterítesz szőnyeget, és őszintén, respekt.'::text),
(387066,43008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Freunde einen Gips ..., wird er eindeutig zum Kunstwerk.'::text,'signieren'::text,'signierten'::text,'signieren werden'::text,'Wenn Freunde einen Gips signieren, wird er eindeutig zum Kunstwerk.'::text),
(387070,43008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо друзі ... гіпс, він, очевидно, перетворюється на витвір мистецтва.'::text,'підписують'::text,'підписали'::text,'підпишуть'::text,'Якщо друзі підписують гіпс, він, очевидно, перетворюється на витвір мистецтва.'::text),
(387069,43008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los amigos ... una escayola, está claro que se convierte en una obra de arte.'::text,'firman'::text,'firmaron'::text,'firmarán'::text,'Si los amigos firman una escayola, está claro que se convierte en una obra de arte.'::text),
(387068,43008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si des amis ... un plâtre, il devient clairement une œuvre d''art.'::text,'signent'::text,'signaient'::text,'signeront'::text,'Si des amis signent un plâtre, il devient clairement une œuvre d''art.'::text),
(387071,43008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar alçıyı ..., belli ki bir sanat eserine dönüşüyor.'::text,'imzalarsa'::text,'imzaladıysa'::text,'imzalayacaksa'::text,'Arkadaşlar alçıyı imzalarsa, belli ki bir sanat eserine dönüşüyor.'::text),
(387072,43008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a barátok ... egy gipszet, az nyilvánvalóan műalkotássá válik.'::text,'aláírnak'::text,'aláírtak'::text,'alá fognak írni'::text,'Ha a barátok aláírnak egy gipszet, az nyilvánvalóan műalkotássá válik.'::text),
(387075,43009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du mir den grünen Stift gibst, ... ich neben der gelben Sonne.'::text,'unterschreibe'::text,'unterschreibe'::text,'unterschrieb'::text,'Wenn du mir den grünen Stift gibst, unterschreibe ich neben der gelben Sonne.'::text),
(387079,43009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо даси мені зелений фломастер, я ... біля жовтого сонечка.'::text,'розпишуся'::text,'розписався б'::text,'розписався'::text,'Якщо даси мені зелений фломастер, я розпишуся біля жовтого сонечка.'::text),
(387078,43009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si me pasas el rotulador verde, ... mi nombre al lado del sol amarillo.'::text,'pondré'::text,'pondría'::text,'puse'::text,'Si me pasas el rotulador verde, pondré mi nombre al lado del sol amarillo.'::text),
(387077,43009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu me passes le feutre vert, je ... à côté du soleil jaune.'::text,'signerai'::text,'signerais'::text,'ai signé'::text,'Si tu me passes le feutre vert, je signerai à côté du soleil jaune.'::text),
(387080,43009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bana yeşil kalemi verirsen sarı güneşin yanına ...'::text,'imza atarım'::text,'imza atardım'::text,'imza attım'::text,'Bana yeşil kalemi verirsen sarı güneşin yanına imza atarım.'::text),
(387081,43009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ideadod a zöld filcet, ... a nevem a sárga nap mellé.'::text,'odaírom'::text,'odaírnám'::text,'odaírtam'::text,'Ha ideadod a zöld filcet, odaírom a nevem a sárga nap mellé.'::text),
(387084,43010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Junge an beiden Armen einen Gips hätte, ... seine Freunde beide.'::text,'signierten'::text,'signieren'::text,'signierten'::text,'Wenn der Junge an beiden Armen einen Gips hätte, signierten seine Freunde beide.'::text),
(387088,43010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби хлопець мав гіпс на обох руках, його друзі ... обидва.'::text,'підписали б'::text,'підпишуть'::text,'підписали'::text,'Якби хлопець мав гіпс на обох руках, його друзі підписали б обидва.'::text),
(387087,43010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el chico tuviera escayola en los dos brazos, sus amigos ... las dos.'::text,'firmarían'::text,'firmarán'::text,'firmaron'::text,'Si el chico tuviera escayola en los dos brazos, sus amigos firmarían las dos.'::text),
(387086,43010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le garçon avait un plâtre aux deux bras, ses amis ... les deux.'::text,'signeraient'::text,'signeront'::text,'ont signé'::text,'Si le garçon avait un plâtre aux deux bras, ses amis signeraient les deux.'::text),
(387089,43010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuğun iki kolu da alçıda olsaydı arkadaşları ikisini de ...'::text,'imzalardı'::text,'imzalayacak'::text,'imzaladı'::text,'Çocuğun iki kolu da alçıda olsaydı arkadaşları ikisini de imzalardı.'::text),
(387090,43010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a srácnak mindkét karján gipsz lenne, a barátai mindkettőt ...'::text,'aláírnák'::text,'aláírják'::text,'aláírták'::text,'Ha a srácnak mindkét karján gipsz lenne, a barátai mindkettőt aláírnák.'::text),
(387093,43011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... der Gips des Jungen von all seinen Freunden im Aufenthaltsraum signiert.'::text,'wurde'::text,'wird'::text,'wurde'::text,'Gestern wurde der Gips des Jungen von all seinen Freunden im Aufenthaltsraum signiert.'::text),
(387097,43011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора гіпс хлопця ... всіма його друзями в загальній кімнаті.'::text,'був підписаний'::text,'підписаний'::text,'підписав'::text,'Учора гіпс хлопця був підписаний всіма його друзями в загальній кімнаті.'::text),
(387096,43011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer la escayola del chico ... por todos sus amigos en la sala común.'::text,'fue firmada'::text,'es firmada'::text,'firmó'::text,'Ayer la escayola del chico fue firmada por todos sus amigos en la sala común.'::text),
(387095,43011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, le plâtre du garçon ... par tous ses amis dans la salle commune.'::text,'a été signé'::text,'est signé'::text,'a signé'::text,'Hier, le plâtre du garçon a été signé par tous ses amis dans la salle commune.'::text),
(387098,43011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün çocuğun alçısı ortak salonda bütün arkadaşları tarafından ...'::text,'imzalandı'::text,'imzalanıyor'::text,'imzaladı'::text,'Dün çocuğun alçısı ortak salonda bütün arkadaşları tarafından imzalandı.'::text),
(387099,43011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a srác gipsze ... az összes barátja által a közös helyiségben.'::text,'alá lett írva'::text,'alá van írva'::text,'aláírta'::text,'Tegnap a srác gipsze alá lett írva az összes barátja által a közös helyiségben.'::text),
(387102,43012,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schrie, niemand ... seinen Gips bisher unterschrieben. Eine totale Katastrophe!'::text,'hatte'::text,'hat'::text,'hat'::text,'Er schrie, niemand hatte seinen Gips bisher unterschrieben. Eine totale Katastrophe!'::text),
(387106,43012,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кричав, що ніхто ще не ... його гіпс. Повна катастрофа!'::text,'підписав'::text,'підписав'::text,'підписує'::text,'Він кричав, що ніхто ще не підписав його гіпс. Повна катастрофа!'::text),
(387105,43012,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gritó que nadie ... su escayola todavía. ¡Un desastre total!'::text,'había firmado'::text,'ha firmado'::text,'firma'::text,'Gritó que nadie había firmado su escayola todavía. ¡Un desastre total!'::text),
(387104,43012,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a hurlé que personne ... son plâtre. Une catastrophe totale !'::text,'n''avait encore signé'::text,'n''a encore signé'::text,'ne signe'::text,'Il a hurlé que personne n''avait encore signé son plâtre. Une catastrophe totale !'::text),
(387107,43012,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Henüz kimsenin alçısını ... bağırdı. Tam bir felaket!'::text,'imzalamadığını'::text,'imzalamadığını'::text,'imzalamadığını'::text,'Henüz kimsenin alçısını imzalamadığını bağırdı. Tam bir felaket!'::text),
(387108,43012,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt üvöltötte, hogy még senki sem ... alá a gipszét. Totális katasztrófa!'::text,'írta'::text,'írta'::text,'írja'::text,'Azt üvöltötte, hogy még senki sem írta alá a gipszét. Totális katasztrófa!'::text),
(387120,43014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wird nie jemandem verzeihen, der es vermeidet, seinen Gips zu ...!'::text,'unterschreiben'::text,'unterschreiben'::text,'unterschreiben'::text,'Er wird nie jemandem verzeihen, der es vermeidet, seinen Gips zu unterschreiben!'::text),
(387124,43014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ніколи не пробачить тому, хто уникає ... його гіпс!'::text,'підписувати'::text,'підписувати'::text,'підписувати'::text,'Він ніколи не пробачить тому, хто уникає підписувати його гіпс!'::text),
(387123,43014,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca perdonará a nadie que evite ... su escayola!'::text,'firmar'::text,'firmar'::text,'firmar'::text,'¡Nunca perdonará a nadie que evite firmar su escayola!'::text),
(387122,43014,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne pardonnera jamais à ceux qui évitent de ... son plâtre !'::text,'signer'::text,'signer'::text,'signer'::text,'Il ne pardonnera jamais à ceux qui évitent de signer son plâtre !'::text),
(387125,43014,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alçısını ... kaçınan hiç kimseyi asla affetmeyecek!'::text,'imzalamaktan'::text,'imzalamaktan'::text,'imzalamaktan'::text,'Alçısını imzalamaktan kaçınan hiç kimseyi asla affetmeyecek!'::text),
(387126,43014,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha nem bocsát meg senkinek, aki kerüli, hogy ... a gipszét!'::text,'aláírja'::text,'aláírja'::text,'aláírja'::text,'Soha nem bocsát meg senkinek, aki kerüli, hogy aláírja a gipszét!'::text),
(387129,43015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend haben alle seinen Gips unterschrieben, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Bestie, anscheinend haben alle seinen Gips unterschrieben, oder?'::text),
(387133,43015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, кажуть, усі підписали йому гіпс, ...'::text,'так?'::text,'так?'::text,'так?'::text,'Бесті, кажуть, усі підписали йому гіпс, так?'::text),
(387132,43015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, por lo visto todos le firmaron la escayola, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Bestie, por lo visto todos le firmaron la escayola, ¿verdad?'::text),
(387131,43015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment tout le monde a signé son plâtre, ...'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Bestie, apparemment tout le monde a signé son plâtre, non ?'::text),
(387134,43015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre herkes alçısını imzalamış, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Kanka, duyduğuma göre herkes alçısını imzalamış, değil mi?'::text),
(387135,43015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, állítólag mindenki aláírta a gipszét, ...'::text,'nem?'::text,'nem?'::text,'nem?'::text,'Bestie, állítólag mindenki aláírta a gipszét, nem?'::text),
(387138,43016,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, dass Maya den Gips in Grün unterschrieben hat, und ...'::text,'Leo auch.'::text,'Leo auch.'::text,'Leo auch.'::text,'Hör zu, er hat mir erzählt, dass Maya den Gips in Grün unterschrieben hat, und Leo auch.'::text),
(387142,43016,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що Мая підписала гіпс зеленим, і ...'::text,'Лео теж.'::text,'Лео теж.'::text,'Лео теж.'::text,'Слухай, він сказав мені, що Мая підписала гіпс зеленим, і Лео теж.'::text),
(387141,43016,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que Maya firmó la escayola en verde, y ...'::text,'Leo también.'::text,'Leo también.'::text,'Leo también.'::text,'Escucha, me dijo que Maya firmó la escayola en verde, y Leo también.'::text),
(387140,43016,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que Maya a signé le plâtre en vert, et ...'::text,'Leo aussi.'::text,'Leo aussi.'::text,'Leo aussi.'::text,'Écoute, il m''a dit que Maya a signé le plâtre en vert, et Leo aussi.'::text),
(387143,43016,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana Maya''nın alçıyı yeşille imzaladığını söyledi, ...'::text,'Leo da öyle.'::text,'Leo da öyle.'::text,'Leo da öyle.'::text,'Dinle, bana Maya''nın alçıyı yeşille imzaladığını söyledi, Leo da öyle.'::text),
(387144,43016,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy Maya zölddel írta alá a gipszet, és ...'::text,'Leo is.'::text,'Leo is.'::text,'Leo is.'::text,'Figyelj, azt mondta, hogy Maya zölddel írta alá a gipszet, és Leo is.'::text),
(387156,43018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Freitag ... die ganze Schule seinen Gips. Eine sehr private Verletzung, natürlich.'::text,'unterschreibt'::text,'unterschreibt'::text,'unterschreibt'::text,'Bis Freitag unterschreibt die ganze Schule seinen Gips. Eine sehr private Verletzung, natürlich.'::text),
(387160,43018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці вся школа ... йому гіпс. Дуже приватна травма, очевидно.'::text,'підпише'::text,'підпише'::text,'підписуватиме'::text,'До п''ятниці вся школа підпише йому гіпс. Дуже приватна травма, очевидно.'::text),
(387159,43018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el viernes, todo el instituto ... su escayola. Una lesión muy privada, obviamente.'::text,'habrá firmado'::text,'firmará'::text,'estará firmando'::text,'Para el viernes, todo el instituto habrá firmado su escayola. Una lesión muy privada, obviamente.'::text),
(387158,43018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici vendredi, toute l''école ... son plâtre. Une blessure très privée, évidemment.'::text,'aura signé'::text,'signera'::text,'sera en train de signer'::text,'D''ici vendredi, toute l''école aura signé son plâtre. Une blessure très privée, évidemment.'::text),
(387161,43018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumaya kadar bütün okul alçısını ...; çok özel bir sakatlık, belli ki.'::text,'imzalamış olacak'::text,'imzalayacak'::text,'imzalıyor olacak'::text,'Cumaya kadar bütün okul alçısını imzalamış olacak; çok özel bir sakatlık, belli ki.'::text),
(387162,43018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Péntekre az egész suli ... a gipszét. Nagyon privát sérülés, nyilván.'::text,'aláírja'::text,'alá fogja írni'::text,'írogatni fogja'::text,'Péntekre az egész suli aláírja a gipszét. Nagyon privát sérülés, nyilván.'::text),
(338916,37658,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Decke auf mich ..., wäre das das Ende von allem!'::text,'fallen würde'::text,'fällt'::text,'fallen würde'::text,'Wenn diese Decke auf mich fallen würde, wäre das das Ende von allem!'::text),
(338920,37658,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ця стеля ... на мене, це був би кінець усьому!'::text,'впала'::text,'падає'::text,'впала б'::text,'Якби ця стеля впала на мене, це був би кінець усьому!'::text),
(338919,37658,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si este techo ... encima de mí, sería el fin de todo!'::text,'cayera'::text,'cae'::text,'caería'::text,'¡Si este techo cayera encima de mí, sería el fin de todo!'::text),
(338918,37658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ce plafond me ..., ce serait la fin de tout !'::text,'tombait dessus'::text,'tombe dessus'::text,'tomberait dessus'::text,'Si ce plafond me tombait dessus, ce serait la fin de tout !'::text),
(338921,37658,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu tavan üstüme ..., her şeyin sonu olurdu!'::text,'düşse'::text,'düşüyor'::text,'düşerdi'::text,'Bu tavan üstüme düşse, her şeyin sonu olurdu!'::text),
(338922,37658,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ez a plafon rám ..., az lenne mindennek a vége!'::text,'esne'::text,'esik'::text,'esne'::text,'Ha ez a plafon rám esne, az lenne mindennek a vége!'::text),
(338925,37659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, angeblich ... diese Kuppeldecke vor Hunderten von Jahren bemalt.'::text,'wurde'::text,'hat'::text,'wird'::text,'Warte, angeblich wurde diese Kuppeldecke vor Hunderten von Jahren bemalt.'::text),
(338929,37659,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чекай, кажуть, та купольна стеля ... сотні років тому.'::text,'була розписана'::text,'розписала'::text,'розписана'::text,'Чекай, кажуть, та купольна стеля була розписана сотні років тому.'::text),
(338928,37659,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, se supone que ese techo abovedado ... hace cientos de años.'::text,'fue pintado'::text,'pintó'::text,'es pintado'::text,'Espera, se supone que ese techo abovedado fue pintado hace cientos de años.'::text),
(338927,37659,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment ce plafond en coupole ... il y a des centaines d''années.'::text,'a été peint'::text,'a peint'::text,'est peint'::text,'Attends, apparemment ce plafond en coupole a été peint il y a des centaines d''années.'::text),
(338930,37659,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, güya o kubbe tavan yüzlerce yıl önce ...'::text,'boyanmış'::text,'boyamış'::text,'boyanıyor'::text,'Dur, güya o kubbe tavan yüzlerce yıl önce boyanmış.'::text),
(338931,37659,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag az a kupolás mennyezet több száz éve ...'::text,'lett kifestve'::text,'kifestett'::text,'ki van festve'::text,'Várj, állítólag az a kupolás mennyezet több száz éve lett kifestve.'::text),
(338934,37660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, dass er drei Stunden lang die Decke seines Schlafzimmers ...'::text,'angestarrt hat'::text,'angestarrt wurde'::text,'anstarrend'::text,'Hör zu, er hat mir erzählt, dass er drei Stunden lang die Decke seines Schlafzimmers angestarrt hat.'::text),
(338938,37660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що ... на стелю в спальні три години.'::text,'витріщався'::text,'був витріщений'::text,'витріщаючись'::text,'Слухай, він сказав мені, що витріщався на стелю в спальні три години.'::text),
(338937,37660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que ... el techo de su habitación durante tres horas.'::text,'miró fijamente'::text,'fue mirado'::text,'mirando'::text,'Escucha, me dijo que miró fijamente el techo de su habitación durante tres horas.'::text),
(338936,37660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il ... le plafond de sa chambre pendant trois heures.'::text,'a fixé'::text,'a été fixé'::text,'fixant'::text,'Écoute, il m''a dit qu''il a fixé le plafond de sa chambre pendant trois heures.'::text),
(338939,37660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana yatak odasının tavanına üç saat boyunca ... söyledi.'::text,'baktığını'::text,'bakıldığını'::text,'bakarak'::text,'Dinle, bana yatak odasının tavanına üç saat boyunca baktığını söyledi.'::text),
(338940,37660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy három órán át ... a hálószobája plafonját.'::text,'bámulta'::text,'bámulva volt'::text,'bámulva'::text,'Figyelj, azt mondta, hogy három órán át bámulta a hálószobája plafonját.'::text),
(338943,37661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, ich hab gehört, die Deckenbalken ... richtig alt sein, aber keiner ist sich sicher.'::text,'könnten'::text,'müssen'::text,'sollten'::text,'Also, ich hab gehört, die Deckenbalken könnten richtig alt sein, aber keiner ist sich sicher.'::text),
(338947,37661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, я чула, що стельові балки ... бути дуже старими, але ніхто не впевнений.'::text,'можуть'::text,'мусять'::text,'мали б'::text,'Отже, я чула, що стельові балки можуть бути дуже старими, але ніхто не впевнений.'::text),
(338946,37661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, he oído que las vigas del techo ... ser muy antiguas, pero nadie está seguro.'::text,'podrían'::text,'deben de'::text,'deberían'::text,'Vale, he oído que las vigas del techo podrían ser muy antiguas, pero nadie está seguro.'::text),
(338945,37661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu dire que les poutres du plafond ... être très vieilles, mais personne n''est sûr.'::text,'pourraient'::text,'doivent'::text,'devraient'::text,'Bon, j''ai entendu dire que les poutres du plafond pourraient être très vieilles, mais personne n''est sûr.'::text),
(338948,37661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şöyle ki, tavan kirişlerinin çok eski ... duydum ama kimse emin değil.'::text,'olabileceğini'::text,'olması gerektiğini'::text,'olması gerektiğini'::text,'Şöyle ki, tavan kirişlerinin çok eski olabileceğini duydum ama kimse emin değil.'::text),
(338949,37661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval úgy hallottam, a mennyezeti gerendák nagyon régiek ..., de senki sem biztos benne.'::text,'lehetnek'::text,'kell legyenek'::text,'kellene legyenek'::text,'Szóval úgy hallottam, a mennyezeti gerendák nagyon régiek lehetnek, de senki sem biztos benne.'::text),
(338952,37662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, die Decke, auf ... du schaust, verdient deine Aufmerksamkeit.'::text,'die'::text,'wen'::text,'wo'::text,'Ehrlich gesagt, die Decke, auf die du schaust, verdient deine Aufmerksamkeit.'::text),
(338956,37662,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, стеля, на ... ти дивишся, заслуговує на твою увагу.'::text,'яку'::text,'кого'::text,'де'::text,'Не буду брехати, стеля, на яку ти дивишся, заслуговує на твою увагу.'::text),
(338955,37662,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, el techo ... estás mirando merece tu atención.'::text,'que'::text,'quien'::text,'donde'::text,'No voy a mentir, el techo que estás mirando merece tu atención.'::text),
(338954,37662,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, le plafond ... tu regardes mérite ton attention.'::text,'que'::text,'qui'::text,'où'::text,'Je vais pas mentir, le plafond que tu regardes mérite ton attention.'::text),
(338957,37662,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ... baktığın tavan ilgini hak ediyor.'::text,''::text,NULL::text,NULL::text,'Yalan yok, baktığın tavan ilgini hak ediyor.'::text),
(338958,37662,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, a plafon, ... nézel, megérdemli a figyelmedet.'::text,'amit'::text,'akit'::text,'ahol'::text,'Nem hazudok, a plafon, amit nézel, megérdemli a figyelmedet.'::text),
(338961,37663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast uns erzählt, du ... vorher noch nie auf eine Decke geachtet. Ehrlich, beeindruckender Geschmack.'::text,'hättest'::text,'hast'::text,'hat'::text,'Du hast uns erzählt, du hättest vorher noch nie auf eine Decke geachtet. Ehrlich, beeindruckender Geschmack.'::text),
(338965,37663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти казав нам, що ... жодної стелі раніше. Чесно, вражаючий смак.'::text,'ніколи не помічав'::text,'ніколи не помічав'::text,'ніколи не помічав'::text,'Ти казав нам, що ніколи не помічав жодної стелі раніше. Чесно, вражаючий смак.'::text),
(338964,37663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nos dijiste que nunca ... fijado en un techo. Sinceramente, qué buen gusto.'::text,'te habías'::text,'te has'::text,'se ha'::text,'Nos dijiste que nunca te habías fijado en un techo. Sinceramente, qué buen gusto.'::text),
(338963,37663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu nous as dit que tu ... jamais remarqué de plafond avant. Franchement, goût impressionnant.'::text,'n''avais'::text,'n''as'::text,'n''a'::text,'Tu nous as dit que tu n''avais jamais remarqué de plafond avant. Franchement, goût impressionnant.'::text),
(338966,37663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bize daha önce hiç bir tavanı ... söyledin. Açıkçası, etkileyici bir zevk.'::text,'fark etmediğini'::text,'fark etmediğini'::text,'fark etmediğini'::text,'Bize daha önce hiç bir tavanı fark etmediğini söyledin. Açıkçası, etkileyici bir zevk.'::text),
(338967,37663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad nekünk, hogy korábban soha nem ... a plafonra. Őszintén, lenyűgöző ízlés.'::text,'figyeltél'::text,'figyelsz'::text,'figyel'::text,'Azt mondtad nekünk, hogy korábban soha nem figyeltél a plafonra. Őszintén, lenyűgöző ízlés.'::text),
(338979,37665,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Abende verbringt sie mit ... auf hölzerne Deckenbalken. Spannend.'::text,'Starren'::text,'starren'::text,'starren'::text,'Ihre Abende verbringt sie mit Starren auf hölzerne Deckenbalken. Spannend.'::text),
(338983,37665,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона проводить вечори, ... на дерев''яні стельові балки. Захопливо.'::text,'витріщаючись'::text,'витріщатися'::text,'витріщатися'::text,'Вона проводить вечори, витріщаючись на дерев''яні стельові балки. Захопливо.'::text),
(338982,37665,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pasa las tardes ... las vigas de madera del techo. Emocionante.'::text,'mirando fijamente'::text,'mirar fijamente'::text,'mirar fijamente'::text,'Pasa las tardes mirando fijamente las vigas de madera del techo. Emocionante.'::text),
(338981,37665,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle passe ses soirées à ... les poutres en bois du plafond. Passionnant.'::text,'fixer'::text,'fixer'::text,'fixer'::text,'Elle passe ses soirées à fixer les poutres en bois du plafond. Passionnant.'::text),
(338984,37665,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşamlarını ahşap tavan kirişlerine ... geçiriyor. Heyecan verici.'::text,'bakarak'::text,'bakmak'::text,'bakmak'::text,'Akşamlarını ahşap tavan kirişlerine bakarak geçiriyor. Heyecan verici.'::text),
(338985,37665,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az estéit azzal tölti, hogy ... a fa mennyezeti gerendákat. Izgalmas.'::text,'bámulja'::text,'bámulja'::text,'bámulja'::text,'Az estéit azzal tölti, hogy bámulja a fa mennyezeti gerendákat. Izgalmas.'::text),
(338988,37666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon eine Stunde an die Decke, bevor er endlich die Augen schloss.'::text,'starrte'::text,'starrte'::text,'starrte'::text,'Er starrte schon eine Stunde an die Decke, bevor er endlich die Augen schloss.'::text),
(338992,37666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на стелю цілу годину, перш ніж нарешті заплющив очі.'::text,'дивився'::text,'дивиться'::text,'дивився'::text,'Він дивився на стелю цілу годину, перш ніж нарешті заплющив очі.'::text),
(338991,37666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el techo durante una hora antes de cerrar por fin los ojos.'::text,'Había estado mirando'::text,'Ha estado mirando'::text,'Estaba mirando'::text,'Había estado mirando el techo durante una hora antes de cerrar por fin los ojos.'::text),
(338990,37666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le plafond pendant une heure avant de finalement fermer les yeux.'::text,'avait fixé'::text,'a fixé'::text,'fixait'::text,'Il avait fixé le plafond pendant une heure avant de finalement fermer les yeux.'::text),
(338993,37666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonunda gözlerini kapamadan önce bir saat boyunca tavana ...'::text,'bakıp durmuştu'::text,'bakıp duruyor'::text,'bakıyordu'::text,'Sonunda gözlerini kapamadan önce bir saat boyunca tavana bakıp durmuştu.'::text),
(338994,37666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órán át ... a plafont, mielőtt végre lehunyta a szemét.'::text,'bámulta'::text,'bámulta'::text,'bámulta'::text,'Egy órán át bámulta a plafont, mielőtt végre lehunyta a szemét.'::text),
(339006,37668,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um Mitternacht ... er seit drei Stunden an die Schlafzimmerdecke.'::text,'starrt'::text,'starrt'::text,'starrt'::text,'Um Mitternacht starrt er seit drei Stunden an die Schlafzimmerdecke.'::text),
(339010,37668,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Опівночі він уже три години ... на стелю в спальні.'::text,'дивитиметься'::text,'дивитиметься'::text,'дивитиметься'::text,'Опівночі він уже три години дивитиметься на стелю в спальні.'::text),
(339009,37668,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A medianoche, ... el techo del dormitorio durante tres horas.'::text,'llevará mirando'::text,'estará mirando'::text,'habrá mirado'::text,'A medianoche, llevará mirando el techo del dormitorio durante tres horas.'::text),
(339008,37668,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À minuit, il ... le plafond de sa chambre depuis trois heures.'::text,'fixera'::text,'fixera'::text,'fixera'::text,'À minuit, il fixera le plafond de sa chambre depuis trois heures.'::text),
(339011,37668,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar üç saattir yatak odasının tavanına ...'::text,'bakıyor olacak'::text,'bakıyor olacak'::text,'bakmış olacak'::text,'Gece yarısına kadar üç saattir yatak odasının tavanına bakıyor olacak.'::text),
(339012,37668,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélre már három órája ... a hálószoba plafonját.'::text,'bámulja'::text,'bámulni fogja'::text,'bámulja'::text,'Éjfélre már három órája bámulja a hálószoba plafonját.'::text),
(341013,37891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, hätte er den Sessel genommen, ... der Typ jetzt total gemütlich.'::text,'säße'::text,'säße'::text,'sitzt'::text,'Ehrlich, hätte er den Sessel genommen, säße der Typ jetzt total gemütlich.'::text),
(341017,37891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби він обрав крісло, цей чувак ... зараз у повному комфорті.'::text,'сидів би'::text,'сидів би'::text,'сидітиме'::text,'Чесно, якби він обрав крісло, цей чувак сидів би зараз у повному комфорті.'::text),
(341016,37891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sin mentir, si hubiera elegido el sillón, ese tío ... ahora mismo con total comodidad.'::text,'estaría sentado'::text,'habría estado sentado'::text,'estará sentado'::text,'Sin mentir, si hubiera elegido el sillón, ese tío estaría sentado ahora mismo con total comodidad.'::text),
(341015,37891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, s''il avait choisi le fauteuil, ce mec ... dans un confort total en ce moment.'::text,'serait assis'::text,'aurait été assis'::text,'sera assis'::text,'Franchement, s''il avait choisi le fauteuil, ce mec serait assis dans un confort total en ce moment.'::text),
(341018,37891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, koltuğu seçseydi o adam şu an tam bir konfor içinde ...'::text,'oturuyor olurdu'::text,'oturmuş olurdu'::text,'oturacak'::text,'Yalan yok, koltuğu seçseydi o adam şu an tam bir konfor içinde oturuyor olurdu.'::text),
(341019,37891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, ha a fotelt választotta volna, az a csávó most totál kényelemben ...'::text,'ülne'::text,'ült volna'::text,'fog ülni'::text,'Nem kamu, ha a fotelt választotta volna, az a csávó most totál kényelemben ülne.'::text),
(341022,37892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der grüne Sessel soll die Komfortwerte um 70 Prozent ..., ein neuer KPI-Rekord.'::text,'gesteigert haben'::text,'steigern'::text,'steigernd'::text,'Der grüne Sessel soll die Komfortwerte um 70 Prozent gesteigert haben, ein neuer KPI-Rekord.'::text),
(341026,37892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що зелене крісло ... показники комфорту на 70 відсотків, новий рекорд KPI.'::text,'підвищило'::text,'підвищує'::text,'підвищуючи'::text,'Кажуть, що зелене крісло підвищило показники комфорту на 70 відсотків, новий рекорд KPI.'::text),
(341025,37892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según los informes, el sillón verde ... la puntuación de comodidad un 70 por ciento, un nuevo récord de KPI.'::text,'ha subido'::text,'sube'::text,'subiendo'::text,'Según los informes, el sillón verde ha subido la puntuación de comodidad un 70 por ciento, un nuevo récord de KPI.'::text),
(341024,37892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fauteuil vert ... les scores de confort de 70 %, un nouveau record de KPI.'::text,'aurait augmenté'::text,'augmenterait'::text,'augmentant'::text,'Le fauteuil vert aurait augmenté les scores de confort de 70 %, un nouveau record de KPI.'::text),
(341027,37892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeşil koltuğun konfor puanlarını yüzde 70 ... bildiriliyor; yeni bir KPI rekoru.'::text,'artırdığı'::text,'artıracağı'::text,'artırarak'::text,'Yeşil koltuğun konfor puanlarını yüzde 70 artırdığı bildiriliyor; yeni bir KPI rekoru.'::text),
(341028,37892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelentések szerint a zöld fotel 70 százalékkal ... a kényelmi pontszámokat, ami új KPI-rekord.'::text,'emelte'::text,'emeli'::text,'emelve'::text,'A jelentések szerint a zöld fotel 70 százalékkal emelte a kényelmi pontszámokat, ami új KPI-rekord.'::text),
(341031,37893,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann beschwerte sich darüber, dass er auf dem harten Küchenstuhl überhaupt keinen Komfort ...'::text,'hat'::text,'zu haben'::text,'hatte'::text,'Der junge Mann beschwerte sich darüber, dass er auf dem harten Küchenstuhl überhaupt keinen Komfort hat.'::text),
(341035,37893,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік скаржився, що не ... жодного комфорту на твердому кухонному стільці.'::text,'має'::text,'мати'::text,'мав'::text,'Молодий чоловік скаржився, що не має жодного комфорту на твердому кухонному стільці.'::text),
(341034,37893,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven se quejó de no ... ninguna comodidad en la dura silla de la cocina.'::text,'tener'::text,'tener'::text,'tenía'::text,'El joven se quejó de no tener ninguna comodidad en la dura silla de la cocina.'::text),
(341033,37893,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme s''est plaint de ... aucun confort sur la dure chaise de cuisine.'::text,'n''avoir'::text,'n''avoir'::text,'n''avait'::text,'Le jeune homme s''est plaint de n''avoir aucun confort sur la dure chaise de cuisine.'::text),
(341036,37893,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam sert mutfak sandalyesinde hiç konfor ... şikâyet etti.'::text,'olmamasından'::text,'olmamasından'::text,'olmadı'::text,'Genç adam sert mutfak sandalyesinde hiç konfor olmamasından şikâyet etti.'::text),
(341037,37893,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal férfi panaszkodott, hogy a kemény konyhaszéken semmi kényelme ...'::text,'nincs'::text,'nincs'::text,'nem volt'::text,'A fiatal férfi panaszkodott, hogy a kemény konyhaszéken semmi kényelme nincs.'::text),
(341040,37894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er seufzte so laut, dass der Sessel nach einem langen Tag eine echte Wohltat ...'::text,'gewesen sein muss'::text,'gewesen sein sollte'::text,'nicht gewesen sein kann'::text,'Er seufzte so laut, dass der Sessel nach einem langen Tag eine echte Wohltat gewesen sein muss.'::text),
(341044,37894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зітхнув так голосно, що крісло після довгого дня ... справжнім комфортом.'::text,'напевно було'::text,'мало бути'::text,'не могло бути'::text,'Він зітхнув так голосно, що крісло після довгого дня напевно було справжнім комфортом.'::text),
(341043,37894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Suspiró tan fuerte que el sillón ... una auténtica comodidad después de un día largo.'::text,'debió de ser'::text,'debería haber sido'::text,'no pudo ser'::text,'Suspiró tan fuerte que el sillón debió de ser una auténtica comodidad después de un día largo.'::text),
(341042,37894,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a soupiré si fort que le fauteuil ... un vrai réconfort après une longue journée.'::text,'a dû être'::text,'aurait dû être'::text,'ne peut pas avoir été'::text,'Il a soupiré si fort que le fauteuil a dû être un vrai réconfort après une longue journée.'::text),
(341045,37894,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar yüksek sesle iç çekti ki koltuk uzun bir günün ardından gerçek bir konfor ...'::text,'olmuş olmalı'::text,'olmalıydı'::text,'olmuş olamaz'::text,'O kadar yüksek sesle iç çekti ki koltuk uzun bir günün ardından gerçek bir konfor olmuş olmalı.'::text),
(341046,37894,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan hangosan sóhajtott, hogy a fotel egy hosszú nap után igazi kényelem ...'::text,'lehetett'::text,'kellett volna legyen'::text,'nem lehetett'::text,'Olyan hangosan sóhajtott, hogy a fotel egy hosszú nap után igazi kényelem lehetett.'::text),
(341049,37895,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst als er in den Sessel sank, ... echten Komfort.'::text,'spürte er'::text,'spürte er'::text,'spürte er'::text,'Erst als er in den Sessel sank, spürte er echten Komfort.'::text),
(341053,37895,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише коли він опустився в крісло, ... справжній комфорт.'::text,'він відчув'::text,'він відчув'::text,'він відчув'::text,'Лише коли він опустився в крісло, він відчув справжній комфорт.'::text),
(341052,37895,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo cuando se hundió en el sillón ... una comodidad de verdad.'::text,'sintió'::text,'sintió'::text,'sintió'::text,'Solo cuando se hundió en el sillón sintió una comodidad de verdad.'::text),
(341051,37895,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seulement quand il s''est enfoncé dans le fauteuil, ... un vrai confort.'::text,'il a ressenti'::text,'il a ressenti'::text,'il a ressenti'::text,'Seulement quand il s''est enfoncé dans le fauteuil, il a ressenti un vrai confort.'::text),
(341054,37895,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ancak koltuğa gömüldüğünde gerçek bir konfor ...'::text,'hissetti'::text,'hissetti'::text,'hissetti'::text,'Ancak koltuğa gömüldüğünde gerçek bir konfor hissetti.'::text),
(341055,37895,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak amikor belesüppedt a fotelbe, akkor ... igazi kényelmet.'::text,'érzett'::text,'érzett'::text,'érzett'::text,'Csak amikor belesüppedt a fotelbe, akkor érzett igazi kényelmet.'::text),
(341058,37896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ließ sich für mehr Komfort ein dünnes Kissen auf den Stuhl ...'::text,'legen'::text,'zu legen'::text,'legend'::text,'Sie ließ sich für mehr Komfort ein dünnes Kissen auf den Stuhl legen.'::text),
(341062,37896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона попросила ... тонку подушку на свій стілець для комфорту.'::text,'покласти'::text,'покласти'::text,'кладучи'::text,'Вона попросила покласти тонку подушку на свій стілець для комфорту.'::text),
(341061,37896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hizo que le ... un cojín fino en la silla por comodidad.'::text,'pusieran'::text,'poner'::text,'poniendo'::text,'Hizo que le pusieran un cojín fino en la silla por comodidad.'::text),
(341060,37896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fait ... un coussin fin sur sa chaise pour le confort.'::text,'mettre'::text,'mettre'::text,'mettant'::text,'Elle a fait mettre un coussin fin sur sa chaise pour le confort.'::text),
(341063,37896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahat etmek için sandalyesine ince bir minder ...'::text,'koydurdu'::text,'koydurdu'::text,'koyarak'::text,'Rahat etmek için sandalyesine ince bir minder koydurdu.'::text),
(341064,37896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kényelem kedvéért ... egy vékony párnát a székére.'::text,'tetetett'::text,'tetetett'::text,'téve'::text,'A kényelem kedvéért tetetett egy vékony párnát a székére.'::text),
(341067,37897,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ich wünschte, ich ... dein Talent, es mir in jedem Sessel gemütlich zu machen.'::text,'hätte'::text,'habe'::text,'hätte'::text,'Ehrlich, ich wünschte, ich hätte dein Talent, es mir in jedem Sessel gemütlich zu machen.'::text),
(341071,37897,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, от би мені ... твій талант влаштуватися зручно в будь-якому кріслі.'::text,'мати'::text,'мати'::text,'мати'::text,'Чесно, от би мені мати твій талант влаштуватися зручно в будь-якому кріслі.'::text),
(341070,37897,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ojalá ... tu talento para estar cómodo en cualquier sillón.'::text,'tuviera'::text,'tengo'::text,'tendría'::text,'Sinceramente, ojalá tuviera tu talento para estar cómodo en cualquier sillón.'::text),
(341069,37897,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, j''aimerais bien ... ton talent pour être à l''aise dans n''importe quel fauteuil.'::text,'avoir'::text,'avoir'::text,'avoir'::text,'Franchement, j''aimerais bien avoir ton talent pour être à l''aise dans n''importe quel fauteuil.'::text),
(341072,37897,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası keşke her koltukta rahat etme yeteneğin bende de ...'::text,'olsa'::text,'var'::text,'olurdu'::text,'Açıkçası keşke her koltukta rahat etme yeteneğin bende de olsa.'::text),
(341073,37897,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, bárcsak nekem is ... olyan tehetségem a kényelemhez bármelyik fotelben, mint neked.'::text,'lenne'::text,'van'::text,'lenne'::text,'Őszintén, bárcsak nekem is lenne olyan tehetségem a kényelemhez bármelyik fotelben, mint neked.'::text),
(341076,37898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du, ... Vorstellung von Komfort ein riesiger grüner Sessel ist, hast einen legendären Geschmack.'::text,'deren'::text,'wer'::text,'welche'::text,'Du, deren Vorstellung von Komfort ein riesiger grüner Sessel ist, hast einen legendären Geschmack.'::text),
(341080,37898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти, ... уявлення про комфорт — величезне зелене крісло, маєш культовий смак.'::text,'чиє'::text,'хто'::text,'яке'::text,'Ти, чиє уявлення про комфорт — величезне зелене крісло, маєш культовий смак.'::text),
(341079,37898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú, ... idea de comodidad es un sillón verde enorme, tienes un gusto icónico.'::text,'cuya'::text,'quien'::text,'que'::text,'Tú, cuya idea de comodidad es un sillón verde enorme, tienes un gusto icónico.'::text),
(341078,37898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toi, ... l''idée du confort est un énorme fauteuil vert, tu as un goût iconique.'::text,'dont'::text,'qui'::text,'lequel'::text,'Toi, dont l''idée du confort est un énorme fauteuil vert, tu as un goût iconique.'::text),
(341081,37898,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Konfor anlayışı ... kocaman yeşil bir koltuk olan sen, ikonik bir zevke sahipsin.'::text,''::text,NULL::text,NULL::text,'Konfor anlayışı kocaman yeşil bir koltuk olan sen, ikonik bir zevke sahipsin.'::text),
(341082,37898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te, ... a kényelem egy óriási zöld fotelt jelent, ikonikus ízlésed van.'::text,'akinek'::text,'aki'::text,'ami'::text,'Te, akinek a kényelem egy óriási zöld fotelt jelent, ikonikus ízlésed van.'::text),
(341085,37899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich ist ein harter Küchenstuhl ... des Komforts. Makellose Wahl.'::text,'der Gipfel'::text,'ein Gipfel'::text,'Gipfel'::text,'Natürlich ist ein harter Küchenstuhl der Gipfel des Komforts. Makellose Wahl.'::text),
(341089,37899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, твердий кухонний стілець — це ... комфорту. Бездоганний вибір.'::text,'вершина'::text,'вершина'::text,'вершина'::text,'Звісно, твердий кухонний стілець — це вершина комфорту. Бездоганний вибір.'::text),
(341088,37899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claro, una silla de cocina dura es ... de la comodidad. Elección impecable.'::text,'el colmo'::text,'un colmo'::text,'colmo'::text,'Claro, una silla de cocina dura es el colmo de la comodidad. Elección impecable.'::text),
(341087,37899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien sûr, une chaise de cuisine dure, c''est ... du confort. Choix impeccable.'::text,'le summum'::text,'un summum'::text,'summum'::text,'Bien sûr, une chaise de cuisine dure, c''est le summum du confort. Choix impeccable.'::text),
(341090,37899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki sert bir mutfak sandalyesi konforun ...; kusursuz bir seçim.'::text,'zirvesi'::text,'bir zirvesi'::text,'zirvesi'::text,'Tabii ki sert bir mutfak sandalyesi konforun zirvesi; kusursuz bir seçim.'::text),
(341091,37899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hát persze, a kényelem ... egy kemény konyhaszék. Hibátlan választás.'::text,'csúcsa'::text,'egy csúcsa'::text,'csúcsa'::text,'Hát persze, a kényelem csúcsa egy kemény konyhaszék. Hibátlan választás.'::text),
(341094,37900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des dünnen Kissens bietet ihr Stuhl wenig Komfort. Eindeutig Luxus.'::text,'Trotz'::text,'Aufgrund'::text,'Vorausgesetzt'::text,'Trotz des dünnen Kissens bietet ihr Stuhl wenig Komfort. Eindeutig Luxus.'::text),
(341098,37900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... тонку подушку, її стілець дає мало комфорту. Явно розкіш.'::text,'Попри'::text,'Завдяки'::text,'За умови'::text,'Попри тонку подушку, її стілець дає мало комфорту. Явно розкіш.'::text),
(341097,37900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el cojín fino, su silla ofrece poca comodidad. Todo un lujo, claro.'::text,'A pesar de'::text,'Debido a'::text,'Siempre que'::text,'A pesar de el cojín fino, su silla ofrece poca comodidad. Todo un lujo, claro.'::text),
(341096,37900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le coussin fin, sa chaise offre peu de confort. Clairement le luxe.'::text,'Malgré'::text,'En raison de'::text,'Pourvu que'::text,'Malgré le coussin fin, sa chaise offre peu de confort. Clairement le luxe.'::text),
(341099,37900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnce mindere ..., sandalyesi pek konfor sunmuyor. Kesinlikle lüks.'::text,'rağmen'::text,'nedeniyle'::text,'şartıyla'::text,'İnce mindere rağmen, sandalyesi pek konfor sunmuyor. Kesinlikle lüks.'::text),
(341100,37900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vékony párna ... a széke kevés kényelmet nyújt. Egyértelműen luxus.'::text,'ellenére'::text,'miatt'::text,'feltéve'::text,'A vékony párna ellenére a széke kevés kényelmet nyújt. Egyértelműen luxus.'::text),
(365916,40658,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher hat der Reisende jeden Koffer ohne Hilfe aufs Band ..., bemerkenswerterweise.'::text,'geladen'::text,'geladen'::text,'geladen'::text,'Bisher hat der Reisende jeden Koffer ohne Hilfe aufs Band geladen, bemerkenswerterweise.'::text),
(365920,40658,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досі мандрівник ... кожну валізу на стрічку без сторонньої допомоги, що примітно.'::text,'завантажив'::text,'завантажує'::text,'завантажив'::text,'Досі мандрівник завантажив кожну валізу на стрічку без сторонньої допомоги, що примітно.'::text),
(365919,40658,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora, el viajero ... todas las maletas en la cinta sin ayuda, de forma notable.'::text,'ha cargado'::text,'ha estado cargando'::text,'cargó'::text,'Hasta ahora, el viajero ha cargado todas las maletas en la cinta sin ayuda, de forma notable.'::text),
(365918,40658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, le voyageur ... chaque valise sur le tapis sans aide, ce qui est remarquable.'::text,'a chargé'::text,'charge'::text,'a chargé'::text,'Jusqu''ici, le voyageur a chargé chaque valise sur le tapis sans aide, ce qui est remarquable.'::text),
(365921,40658,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar yolcu her bavulu yardım almadan banda ..., dikkat çekici biçimde.'::text,'yükledi'::text,'yüklüyor'::text,'yükledi'::text,'Şimdiye kadar yolcu her bavulu yardım almadan banda yükledi, dikkat çekici biçimde.'::text),
(365922,40658,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig az utas minden bőröndöt segítség nélkül ... a szalagra, figyelemre méltó módon.'::text,'feltette'::text,'rakja fel'::text,'feltette'::text,'Eddig az utas minden bőröndöt segítség nélkül feltette a szalagra, figyelemre méltó módon.'::text),
(365925,40659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Mitarbeiterin aufsah, ... er schon den ganzen Wagen aufs Band geladen. Totale Katastrophe!'::text,'hatte'::text,'hat'::text,'hatte'::text,'Als die Mitarbeiterin aufsah, hatte er schon den ganzen Wagen aufs Band geladen. Totale Katastrophe!'::text),
(365929,40659,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли працівниця підвела погляд, він уже ... на стрічку весь візок. Повна катастрофа!'::text,'завантажив'::text,'завантажив'::text,'завантажує'::text,'Коли працівниця підвела погляд, він уже завантажив на стрічку весь візок. Повна катастрофа!'::text),
(365928,40659,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando la empleada levantó la vista, ya ... todo el carro en la cinta. ¡Un desastre total!'::text,'había cargado'::text,'ha cargado'::text,'carga'::text,'Para cuando la empleada levantó la vista, ya había cargado todo el carro en la cinta. ¡Un desastre total!'::text),
(365927,40659,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''agente a levé les yeux, il ... tout le chariot sur le tapis. Désastre total !'::text,'avait chargé'::text,'a chargé'::text,'charge'::text,'Quand l''agente a levé les yeux, il avait chargé tout le chariot sur le tapis. Désastre total !'::text),
(365930,40659,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli başını kaldırdığında tüm arabayı çoktan banda ...; tam bir felaket!'::text,'yüklemişti'::text,'yükledi'::text,'yüklüyor'::text,'Görevli başını kaldırdığında tüm arabayı çoktan banda yüklemişti; tam bir felaket!'::text),
(365931,40659,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az ügyintéző felnézett, már az egész kocsit ... a szalagra. Totális katasztrófa!'::text,'felrakta'::text,'felrakta'::text,'rakja fel'::text,'Mire az ügyintéző felnézett, már az egész kocsit felrakta a szalagra. Totális katasztrófa!'::text),
(365934,40660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor die Mitarbeiterin seinen Pass prüfte, ... die schwarze Reisetasche aufs Band geladen.'::text,'wurde'::text,'hat'::text,'wird'::text,'Bevor die Mitarbeiterin seinen Pass prüfte, wurde die schwarze Reisetasche aufs Band geladen.'::text),
(365938,40660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще до того, як працівниця перевірила його паспорт, чорна сумка ... на стрічку.'::text,'була завантажена'::text,'завантажила'::text,'завантажена'::text,'Ще до того, як працівниця перевірила його паспорт, чорна сумка була завантажена на стрічку.'::text),
(365937,40660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que la empleada revisara su pasaporte, la bolsa negra ... en la cinta.'::text,'fue cargada'::text,'cargó'::text,'es cargada'::text,'Antes de que la empleada revisara su pasaporte, la bolsa negra fue cargada en la cinta.'::text),
(365936,40660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que l''agente vérifie son passeport, le sac noir ... sur le tapis.'::text,'a été chargé'::text,'a chargé'::text,'est chargé'::text,'Avant que l''agente vérifie son passeport, le sac noir a été chargé sur le tapis.'::text),
(365939,40660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli pasaportunu kontrol etmeden önce siyah çanta banda ...'::text,'yüklendi'::text,'yükledi'::text,'yükleniyor'::text,'Görevli pasaportunu kontrol etmeden önce siyah çanta banda yüklendi.'::text),
(365940,40660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt az ügyintéző ellenőrizte az útlevelét, a fekete táska ... a szalagra.'::text,'fel lett rakva'::text,'felrakott'::text,'fel van rakva'::text,'Mielőtt az ügyintéző ellenőrizte az útlevelét, a fekete táska fel lett rakva a szalagra.'::text),
(365952,40662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat so viele Taschen aufs Band geladen, er ... ins Ausland ziehen, aber keiner weiß es.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Er hat so viele Taschen aufs Band geladen, er könnte ins Ausland ziehen, aber keiner weiß es.'::text),
(365956,40662,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він завантажив стільки сумок, що ... переїжджає за кордон, але ніхто не знає.'::text,'можливо'::text,'напевно'::text,'мав би'::text,'Він завантажив стільки сумок, що можливо переїжджає за кордон, але ніхто не знає.'::text),
(365955,40662,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cargó tantas bolsas que ... estar mudándose al extranjero, pero nadie lo sabe.'::text,'podría'::text,'debe de'::text,'debería'::text,'Cargó tantas bolsas que podría estar mudándose al extranjero, pero nadie lo sabe.'::text),
(365954,40662,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a chargé tellement de sacs qu''il ... être en train de déménager à l''étranger, mais personne ne sait.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Il a chargé tellement de sacs qu''il pourrait être en train de déménager à l''étranger, mais personne ne sait.'::text),
(365957,40662,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar çok çanta yükledi ki yurt dışına taşınıyor ..., ama kimse bilmiyor.'::text,'olabilir'::text,'olmalı'::text,'olmalı'::text,'O kadar çok çanta yükledi ki yurt dışına taşınıyor olabilir, ama kimse bilmiyor.'::text),
(365958,40662,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annyi táskát pakolt fel, hogy ... külföldre költözni, de senki sem tudja.'::text,'talán készül'::text,'biztos készül'::text,'készülnie kellene'::text,'Annyi táskát pakolt fel, hogy talán készül külföldre költözni, de senki sem tudja.'::text),
(365961,40663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Band, ... er mit jedem Koffer beladen hat, hat es locker geschafft. Leichtes Gepäck, natürlich.'::text,'das'::text,'wer'::text,'dessen'::text,'Das Band, das er mit jedem Koffer beladen hat, hat es locker geschafft. Leichtes Gepäck, natürlich.'::text),
(365965,40663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стрічка, ... він завантажив усіма валізами, впоралася чудово. Подорож налегке, очевидно.'::text,'яку'::text,'хто'::text,'чию'::text,'Стрічка, яку він завантажив усіма валізами, впоралася чудово. Подорож налегке, очевидно.'::text),
(365964,40663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cinta ... cargó con todas las maletas aguantó sin problema. Viajar ligero, obviamente.'::text,'que'::text,'quien'::text,'cuya'::text,'La cinta que cargó con todas las maletas aguantó sin problema. Viajar ligero, obviamente.'::text),
(365963,40663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tapis ... il a chargé de toutes ses valises s''en est très bien sorti. Voyager léger, évidemment.'::text,'qu'''::text,'qui'::text,'dont'::text,'Le tapis qu'' il a chargé de toutes ses valises s''en est très bien sorti. Voyager léger, évidemment.'::text),
(365966,40663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her bavulu ... yüklediği bant gayet iyi dayandı. Hafif seyahat, belli ki.'::text,''::text,NULL::text,NULL::text,'Her bavulu yüklediği bant gayet iyi dayandı. Hafif seyahat, belli ki.'::text),
(365967,40663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szalag, ... minden bőrönddel megpakolt, simán bírta. Könnyű utazás, nyilván.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'A szalag, amelyet minden bőrönddel megpakolt, simán bírta. Könnyű utazás, nyilván.'::text),
(365970,40664,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte der Mitarbeiterin, er ... nur ein paar kleine Taschen aufs Band gelegt. Packt eben leicht, klar.'::text,'habe'::text,'hat'::text,'habe'::text,'Er sagte der Mitarbeiterin, er habe nur ein paar kleine Taschen aufs Band gelegt. Packt eben leicht, klar.'::text),
(365974,40664,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав працівниці, що ... лише кілька маленьких сумок. Пакується налегке, звісно.'::text,'завантажив'::text,'завантажив'::text,'завантажує'::text,'Він сказав працівниці, що завантажив лише кілька маленьких сумок. Пакується налегке, звісно.'::text),
(365973,40664,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dijo a la empleada que solo ... unas pocas bolsas pequeñas. Viaja ligero, está claro.'::text,'había cargado'::text,'ha cargado'::text,'carga'::text,'Le dijo a la empleada que solo había cargado unas pocas bolsas pequeñas. Viaja ligero, está claro.'::text),
(365972,40664,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit à l''agente qu''il ... seulement quelques petits sacs. Il voyage léger, clairement.'::text,'avait chargé'::text,'a chargé'::text,'charge'::text,'Il a dit à l''agente qu''il avait chargé seulement quelques petits sacs. Il voyage léger, clairement.'::text),
(365975,40664,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevliye sadece birkaç küçük çanta ... söyledi. Hafif yolculuk yapan biri, belli ki.'::text,'yüklediğini'::text,'yüklediğini'::text,'yüklediğini'::text,'Görevliye sadece birkaç küçük çanta yüklediğini söyledi. Hafif yolculuk yapan biri, belli ki.'::text),
(365976,40664,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta az ügyintézőnek, hogy csak pár kis táskát ... fel. Könnyen pakol, nyilván.'::text,'rakott'::text,'rakott'::text,'rak'::text,'Azt mondta az ügyintézőnek, hogy csak pár kis táskát rakott fel. Könnyen pakol, nyilván.'::text),
(365979,40665,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... Taschen einzuladen, aber jetzt feiert er das irgendwie.'::text,'hasste es früher'::text,'hasste es früher'::text,'war es gewohnt zu hassen'::text,'Bro, er hasste es früher Taschen einzuladen, aber jetzt feiert er das irgendwie.'::text),
(365983,40665,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, раніше він ... вантажити сумки, а тепер йому це навіть заходить.'::text,'ненавидів'::text,'ненавидів'::text,'звик ненавидіти'::text,'Бро, раніше він ненавидів вантажити сумки, а тепер йому це навіть заходить.'::text),
(365982,40665,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, antes ... cargar maletas, pero ahora le mola bastante.'::text,'odiaba'::text,'odiaba'::text,'estaba acostumbrado a odiar'::text,'Bro, antes odiaba cargar maletas, pero ahora le mola bastante.'::text),
(365981,40665,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, avant il ... charger les sacs, mais maintenant il kiffe un peu.'::text,'détestait'::text,'détestait'::text,'avait l''habitude de détester'::text,'Frérot, avant il détestait charger les sacs, mais maintenant il kiffe un peu.'::text),
(365984,40665,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eskiden çanta yüklemekten ..., ama şimdi biraz sarıyor.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Kanka, eskiden çanta yüklemekten nefret ederdi, ama şimdi biraz sarıyor.'::text),
(365985,40665,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, régen ... táskákat pakolni, de most valahogy bejön neki.'::text,'utált'::text,'utált'::text,'megszokta utálni'::text,'Tesó, régen utált táskákat pakolni, de most valahogy bejön neki.'::text),
(365988,40666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er kommt nicht drum herum, jede Tasche selbst zu ..., weil keiner hilft, echt.'::text,'verladen'::text,'verladen'::text,'verladen'::text,'Alter, er kommt nicht drum herum, jede Tasche selbst zu verladen, weil keiner hilft, echt.'::text),
(365992,40666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він не може уникнути того, щоб ... кожну сумку сам, бо ніхто не допомагає, реально.'::text,'вантажити'::text,'вантажити'::text,'вантажити'::text,'Чувак, він не може уникнути того, щоб вантажити кожну сумку сам, бо ніхто не допомагає, реально.'::text),
(365991,40666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, no puede evitar ... cada bolsa él solo porque nadie le ayuda, en serio.'::text,'cargar'::text,'cargar'::text,'cargar'::text,'Tío, no puede evitar cargar cada bolsa él solo porque nadie le ayuda, en serio.'::text),
(365990,40666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il peut pas éviter de ... chaque sac lui-même parce que personne l''aide, sérieux.'::text,'charger'::text,'charger'::text,'charger'::text,'Mec, il peut pas éviter de charger chaque sac lui-même parce que personne l''aide, sérieux.'::text),
(365993,40666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her çantayı kendisi ... kaçamıyor çünkü kimse yardım etmiyor, cidden.'::text,'yüklemekten'::text,'yüklemekten'::text,'yüklemekten'::text,'Kanka, her çantayı kendisi yüklemekten kaçamıyor çünkü kimse yardım etmiyor, cidden.'::text),
(365994,40666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nem tudja elkerülni, hogy minden táskát maga ..., mert senki sem segít, komolyan.'::text,'pakoljon fel'::text,'pakoljon fel'::text,'pakoljon fel'::text,'Tesó, nem tudja elkerülni, hogy minden táskát maga pakoljon fel, mert senki sem segít, komolyan.'::text),
(366006,40668,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon seit zehn Minuten Koffer, als die Mitarbeiterin endlich seinen Pass prüfte.'::text,'lud'::text,'lud'::text,'lud'::text,'Er lud schon seit zehn Minuten Koffer, als die Mitarbeiterin endlich seinen Pass prüfte.'::text),
(366010,40668,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже десять хвилин ... валізи, коли працівниця нарешті перевірила його паспорт.'::text,'вантажив'::text,'вантажив'::text,'завантажив'::text,'Він уже десять хвилин вантажив валізи, коли працівниця нарешті перевірила його паспорт.'::text),
(366009,40668,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... maletas durante diez minutos cuando la empleada por fin revisó su pasaporte.'::text,'Había estado cargando'::text,'Estaba cargando'::text,'Ha cargado'::text,'Había estado cargando maletas durante diez minutos cuando la empleada por fin revisó su pasaporte.'::text),
(366008,40668,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des valises depuis dix minutes quand l''agente a enfin vérifié son passeport.'::text,'chargeait'::text,'chargeait'::text,'a chargé'::text,'Il chargeait des valises depuis dix minutes quand l''agente a enfin vérifié son passeport.'::text),
(366011,40668,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli sonunda pasaportunu kontrol ettiğinde on dakikadır bavul ...'::text,'yüklüyordu'::text,'yüklüyordu'::text,'yükledi'::text,'Görevli sonunda pasaportunu kontrol ettiğinde on dakikadır bavul yüklüyordu.'::text),
(366012,40668,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már tíz perce ... a bőröndöket, amikor az ügyintéző végre ellenőrizte az útlevelét.'::text,'pakolta'::text,'pakolta'::text,'felpakolta'::text,'Már tíz perce pakolta a bőröndöket, amikor az ügyintéző végre ellenőrizte az útlevelét.'::text),
(384933,42771,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächsten Juni ... sie seit zehn Jahren an diesem Serviceschalter der Airline.'::text,'arbeitet'::text,'arbeitet'::text,'arbeitet'::text,'Nächsten Juni arbeitet sie seit zehn Jahren an diesem Serviceschalter der Airline.'::text),
(384937,42771,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного червня вона вже десять років ... за цією стійкою обслуговування авіакомпанії.'::text,'працюватиме'::text,'працюватиме'::text,'працюватиме'::text,'Наступного червня вона вже десять років працюватиме за цією стійкою обслуговування авіакомпанії.'::text),
(384936,42771,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el próximo junio, ... en este mostrador de atención de la aerolínea durante diez años.'::text,'habrá estado trabajando'::text,'estará trabajando'::text,'trabajará'::text,'Para el próximo junio, habrá estado trabajando en este mostrador de atención de la aerolínea durante diez años.'::text),
(384935,42771,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En juin prochain, elle ... à ce comptoir de service de la compagnie depuis dix ans.'::text,'travaillera'::text,'travaillera'::text,'travaillera'::text,'En juin prochain, elle travaillera à ce comptoir de service de la compagnie depuis dix ans.'::text),
(384938,42771,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek hazirana kadar bu havayolu hizmet masasında on yıldır ...'::text,'çalışıyor olacak'::text,'çalışıyor olacak'::text,'çalışacak'::text,'Gelecek hazirana kadar bu havayolu hizmet masasında on yıldır çalışıyor olacak.'::text),
(384939,42771,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő júniusra már tíz éve ... ennél a légitársasági ügyfélszolgálati pultnál.'::text,'dolgozik'::text,'dolgozik'::text,'dolgozni fog'::text,'Jövő júniusra már tíz éve dolgozik ennél a légitársasági ügyfélszolgálati pultnál.'::text),
(384942,42772,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre die Mitarbeiterin unhöflich gewesen, ... er dem Service keine fünf Sterne gegeben.'::text,'hätte'::text,'hat'::text,'hat'::text,'Wäre die Mitarbeiterin unhöflich gewesen, hätte er dem Service keine fünf Sterne gegeben.'::text),
(384946,42772,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби працівниця була грубою, він ... сервісу п''ять зірок.'::text,'не поставив би'::text,'не поставить'::text,'не поставив'::text,'Якби працівниця була грубою, він не поставив би сервісу п''ять зірок.'::text),
(384945,42772,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la empleada hubiera sido maleducada, ... cinco estrellas al servicio.'::text,'no habría dado'::text,'no dará'::text,'no dio'::text,'Si la empleada hubiera sido maleducada, no habría dado cinco estrellas al servicio.'::text),
(384944,42772,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''agente avait été impolie, il ... cinq étoiles au service.'::text,'n''aurait pas donné'::text,'ne donnera pas'::text,'n''a pas donné'::text,'Si l''agente avait été impolie, il n''aurait pas donné cinq étoiles au service.'::text),
(384947,42772,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli kaba olsaydı hizmete beş yıldız ...'::text,'vermezdi'::text,'vermeyecek'::text,'vermedi'::text,'Görevli kaba olsaydı hizmete beş yıldız vermezdi.'::text),
(384948,42772,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az ügyintéző bunkó lett volna, nem ... öt csillagot a kiszolgálásra.'::text,'adott volna'::text,'fog adni'::text,'adott'::text,'Ha az ügyintéző bunkó lett volna, nem adott volna öt csillagot a kiszolgálásra.'::text),
(384951,42773,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wäre der Service mies gewesen, ... er jetzt noch am Schalter.'::text,'stünde'::text,'stünde'::text,'steht'::text,'Bro, wäre der Service mies gewesen, stünde er jetzt noch am Schalter.'::text),
(384955,42773,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби сервіс був так собі, він і зараз ... біля стійки.'::text,'стояв би'::text,'стояв би'::text,'стоятиме'::text,'Бро, якби сервіс був так собі, він і зараз стояв би біля стійки.'::text),
(384954,42773,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si el servicio hubiera sido mediocre, ahora ... todavía en el mostrador.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Bro, si el servicio hubiera sido mediocre, ahora estaría todavía en el mostrador.'::text),
(384953,42773,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si le service avait été nul, il ... encore au comptoir maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Frérot, si le service avait été nul, il serait encore au comptoir maintenant.'::text),
(384956,42773,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hizmet vasat olsaydı şu an hâlâ masada ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Kanka, hizmet vasat olsaydı şu an hâlâ masada olurdu.'::text),
(384957,42773,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha gagyi lett volna a kiszolgálás, még most is ott ... a pultnál.'::text,'állna'::text,'állt volna'::text,'fog állni'::text,'Tesó, ha gagyi lett volna a kiszolgálás, még most is ott állna a pultnál.'::text),
(384960,42774,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Service am Schalter soll sein 98-%-Zufriedenheitsziel bereits ...'::text,'erreicht haben'::text,'erreichen'::text,'erreichend'::text,'Der Service am Schalter soll sein 98-%-Zufriedenheitsziel bereits erreicht haben.'::text),
(384964,42774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повідомляють, що обслуговування на стійці вже ... свою ціль у 98 % задоволеності.'::text,'досягло'::text,'досягає'::text,'досягаючи'::text,'Повідомляють, що обслуговування на стійці вже досягло свою ціль у 98 % задоволеності.'::text),
(384963,42774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según los informes, el servicio del mostrador ya ... su objetivo del 98 % de satisfacción.'::text,'ha alcanzado'::text,'alcanza'::text,'alcanzando'::text,'Según los informes, el servicio del mostrador ya ha alcanzado su objetivo del 98 % de satisfacción.'::text),
(384962,42774,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le service du comptoir ... déjà son objectif de 98 % de satisfaction.'::text,'aurait atteint'::text,'atteindrait'::text,'atteignant'::text,'Le service du comptoir aurait atteint déjà son objectif de 98 % de satisfaction.'::text),
(384965,42774,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Masanın hizmetinin %98 memnuniyet hedefine şimdiden ... bildiriliyor.'::text,'ulaştığı'::text,'ulaşacağı'::text,'ulaşarak'::text,'Masanın hizmetinin %98 memnuniyet hedefine şimdiden ulaştığı bildiriliyor.'::text),
(384966,42774,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelentések szerint a pult kiszolgálása már ... a 98%-os elégedettségi célját.'::text,'elérte'::text,'eléri'::text,'elérve'::text,'A jelentések szerint a pult kiszolgálása már elérte a 98%-os elégedettségi célját.'::text),
(384969,42775,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Teil des Service bot die Mitarbeiterin an, seine Tasche aufs Band zu ...'::text,'heben'::text,'heben'::text,'heben'::text,'Als Teil des Service bot die Mitarbeiterin an, seine Tasche aufs Band zu heben.'::text),
(384973,42775,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У межах сервісу працівниця запропонувала ... його сумку на стрічку.'::text,'підняти'::text,'підняти'::text,'піднявши'::text,'У межах сервісу працівниця запропонувала підняти його сумку на стрічку.'::text),
(384972,42775,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Como parte del servicio, la empleada se ofreció a ... su bolsa a la cinta.'::text,'subir'::text,'subir'::text,'haber subido'::text,'Como parte del servicio, la empleada se ofreció a subir su bolsa a la cinta.'::text),
(384971,42775,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans le cadre du service, l''agente a proposé de ... son sac sur le tapis.'::text,'soulever'::text,'soulever'::text,'avoir soulevé'::text,'Dans le cadre du service, l''agente a proposé de soulever son sac sur le tapis.'::text),
(384974,42775,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hizmetin bir parçası olarak görevli çantasını banda ... teklif etti.'::text,'kaldırmayı'::text,'kaldırmayı'::text,'kaldırmış olmayı'::text,'Hizmetin bir parçası olarak görevli çantasını banda kaldırmayı teklif etti.'::text),
(384975,42775,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiszolgálás részeként az ügyintéző felajánlotta, hogy ... a táskáját a szalagra.'::text,'felteszi'::text,'felteszi'::text,'feltette'::text,'A kiszolgálás részeként az ügyintéző felajánlotta, hogy felteszi a táskáját a szalagra.'::text),
(384978,42776,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach diesem Verhalten zu urteilen, ... der Passagier den Service hervorragend gefunden haben.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Nach diesem Verhalten zu urteilen, muss der Passagier den Service hervorragend gefunden haben.'::text),
(384982,42776,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Судячи з цієї поведінки, пасажир ... обслуговування чудовим.'::text,'мабуть, вважав'::text,'мав би вважати'::text,'не міг вважати'::text,'Судячи з цієї поведінки, пасажир мабуть, вважав обслуговування чудовим.'::text),
(384981,42776,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A juzgar por este comportamiento, al pasajero el servicio ... excelente.'::text,'debió de parecerle'::text,'debería haberle parecido'::text,'no pudo parecerle'::text,'A juzgar por este comportamiento, al pasajero el servicio debió de parecerle excelente.'::text),
(384980,42776,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À en juger par ce comportement, le passager ... le service excellent.'::text,'a dû trouver'::text,'aurait dû trouver'::text,'ne peut pas avoir trouvé'::text,'À en juger par ce comportement, le passager a dû trouver le service excellent.'::text),
(384983,42776,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu davranışa bakılırsa yolcu hizmeti mükemmel ...'::text,'bulmuş olmalı'::text,'bulmalıydı'::text,'bulmuş olamaz'::text,'Bu davranışa bakılırsa yolcu hizmeti mükemmel bulmuş olmalı.'::text),
(384984,42776,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'E viselkedés alapján az utas ... a kiszolgálást kiválónak.'::text,'biztosan találta'::text,'kellett volna találnia'::text,'nem találhatta'::text,'E viselkedés alapján az utas biztosan találta a kiszolgálást kiválónak.'::text),
(384987,42777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... so einen perfekten Service an einem Flughafen bekommen. Das ist absolut unfassbar!'::text,'hat er'::text,'er hat'::text,'hat er'::text,'Nie hat er so einen perfekten Service an einem Flughafen bekommen. Das ist absolut unfassbar!'::text),
(384991,42777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ще ... такого ідеального обслуговування в аеропорту. Це просто нереально!'::text,'він не отримував'::text,'він не отримував'::text,'він не отримував'::text,'Ніколи ще він не отримував такого ідеального обслуговування в аеропорту. Це просто нереально!'::text),
(384990,42777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... un servicio tan perfecto en un aeropuerto. ¡Esto es totalmente irreal!'::text,'ha recibido'::text,'ha recibido'::text,'ha recibido'::text,'Nunca ha recibido un servicio tan perfecto en un aeropuerto. ¡Esto es totalmente irreal!'::text),
(384989,42777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... un service aussi parfait dans un aéroport. C''est complètement irréel !'::text,'n''a-t-il reçu'::text,'il n''a reçu'::text,'n''a-t-il reçu'::text,'Jamais n''a-t-il reçu un service aussi parfait dans un aéroport. C''est complètement irréel !'::text),
(384992,42777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir havalimanında hiç bu kadar mükemmel bir hizmet ...; bu tamamen inanılmaz!'::text,'almamıştı'::text,'almamıştı'::text,'almamıştı'::text,'Bir havalimanında hiç bu kadar mükemmel bir hizmet almamıştı; bu tamamen inanılmaz!'::text),
(384993,42777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... még ilyen tökéletes kiszolgálást reptéren. Ez teljesen hihetetlen!'::text,'nem kapott'::text,'nem kapott'::text,'nem kapott'::text,'Soha nem kapott még ilyen tökéletes kiszolgálást reptéren. Ez teljesen hihetetlen!'::text),
(385005,42779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der nächste Mann wünscht sich, dass er denselben Service ..., aber ihre Schicht ist vorbei. Totale Katastrophe!'::text,'bekommen hätte'::text,'bekommen würde'::text,'bekommt'::text,'Der nächste Mann wünscht sich, dass er denselben Service bekommen hätte, aber ihre Schicht ist vorbei. Totale Katastrophe!'::text),
(385009,42779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступний чоловік хотів би, щоб він ... таке саме обслуговування, але її зміна закінчилася. Повна катастрофа!'::text,'отримав'::text,'отримав'::text,'отримує'::text,'Наступний чоловік хотів би, щоб він отримав таке саме обслуговування, але її зміна закінчилася. Повна катастрофа!'::text),
(385008,42779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El siguiente hombre desearía ... el mismo servicio, pero su turno ha terminado. ¡Un desastre total!'::text,'haber recibido'::text,'recibir'::text,'recibe'::text,'El siguiente hombre desearía haber recibido el mismo servicio, pero su turno ha terminado. ¡Un desastre total!'::text),
(385007,42779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme suivant aimerait ... le même service, mais sa journée à elle est finie. Désastre total !'::text,'avoir eu'::text,'avoir'::text,'a'::text,'L''homme suivant aimerait avoir eu le même service, mais sa journée à elle est finie. Désastre total !'::text),
(385010,42779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıradaki adam keşke aynı hizmeti ... diyor, ama kadının mesaisi bitti. Tam bir felaket!'::text,'alsaydı'::text,'alsa'::text,'alıyor'::text,'Sıradaki adam keşke aynı hizmeti alsaydı diyor, ama kadının mesaisi bitti. Tam bir felaket!'::text),
(385011,42779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A következő férfi azt kívánja, bárcsak ő is ugyanilyen kiszolgálást ..., de a nő műszakja véget ért. Totális katasztrófa!'::text,'kapott volna'::text,'kapna'::text,'kap'::text,'A következő férfi azt kívánja, bárcsak ő is ugyanilyen kiszolgálást kapott volna, de a nő műszakja véget ért. Totális katasztrófa!'::text),
(385014,42780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, die Mitarbeiterin, ... Service makellos war, wurde befördert.'::text,'deren'::text,'die'::text,'welche'::text,'Mädel, ich hab gehört, die Mitarbeiterin, deren Service makellos war, wurde befördert.'::text),
(385018,42780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що працівницю, ... обслуговування було бездоганним, підвищили.'::text,'чиє'::text,'хто'::text,'яке'::text,'Подруго, я чула, що працівницю, чиє обслуговування було бездоганним, підвищили.'::text),
(385017,42780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que a la empleada, ... servicio fue impecable, la han ascendido.'::text,'cuyo'::text,'quien'::text,'que'::text,'Tía, he oído que a la empleada, cuyo servicio fue impecable, la han ascendido.'::text),
(385016,42780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu dire que l''agente, ... le service était impeccable, a eu une promotion.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Meuf, j''ai entendu dire que l''agente, dont le service était impeccable, a eu une promotion.'::text),
(385019,42780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, ... hizmeti kusursuz olan görevlinin terfi aldığını duydum.'::text,''::text,NULL::text,NULL::text,'Kızım, hizmeti kusursuz olan görevlinin terfi aldığını duydum.'::text),
(385020,42780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy az ügyintéző, ... kiszolgálása hibátlan volt, előléptetést kapott.'::text,'akinek'::text,'aki'::text,'ami'::text,'Csajszi, azt hallottam, hogy az ügyintéző, akinek kiszolgálása hibátlan volt, előléptetést kapott.'::text),
(385023,42781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er geht zufrieden weg, weil ... am Schalter der Airline schnell und freundlich war.'::text,'der Service'::text,'ein Service'::text,'Services'::text,'Er geht zufrieden weg, weil der Service am Schalter der Airline schnell und freundlich war.'::text),
(385027,42781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він іде задоволений, бо ... біля стійки авіакомпанії було швидким і привітним.'::text,'обслуговування'::text,'обслуговування'::text,'послуги'::text,'Він іде задоволений, бо обслуговування біля стійки авіакомпанії було швидким і привітним.'::text),
(385026,42781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se va contento porque ... en el mostrador de la aerolínea fue rápido y amable.'::text,'el servicio'::text,'un servicio'::text,'servicios'::text,'Se va contento porque el servicio en el mostrador de la aerolínea fue rápido y amable.'::text),
(385025,42781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il repart content parce que ... au comptoir de la compagnie a été rapide et sympa.'::text,'le service'::text,'un service'::text,'des services'::text,'Il repart content parce que le service au comptoir de la compagnie a été rapide et sympa.'::text),
(385028,42781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havayolu masasındaki ... hızlı ve güler yüzlü olduğu için mutlu ayrılıyor.'::text,'hizmet'::text,'bir hizmet'::text,'hizmetler'::text,'Havayolu masasındaki hizmet hızlı ve güler yüzlü olduğu için mutlu ayrılıyor.'::text),
(385029,42781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elégedetten távozik, mert ... a légitársaság pultjánál gyors és kedves volt.'::text,'a kiszolgálás'::text,'egy kiszolgálás'::text,'szolgáltatások'::text,'Elégedetten távozik, mert a kiszolgálás a légitársaság pultjánál gyors és kedves volt.'::text),
(331689,36855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... gerade Holzscheite auf die Asche, als das Feuer einfach so anging.'::text,'stapelte'::text,'stapelte'::text,'stapelte'::text,'Bro, er stapelte gerade Holzscheite auf die Asche, als das Feuer einfach so anging.'::text),
(331693,36855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... поліна на попіл, коли вогонь непомітно розгорівся.'::text,'складав'::text,'склав'::text,'склав'::text,'Бро, він складав поліна на попіл, коли вогонь непомітно розгорівся.'::text),
(331692,36855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... troncos sobre la ceniza cuando el fuego prendió sin más.'::text,'estaba apilando'::text,'apiló'::text,'ha apilado'::text,'Bro, estaba apilando troncos sobre la ceniza cuando el fuego prendió sin más.'::text),
(331691,36855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... des bûches sur la cendre quand le feu a pris, tranquille.'::text,'empilait'::text,'a empilé'::text,'a empilé'::text,'Frérot, il empilait des bûches sur la cendre quand le feu a pris, tranquille.'::text),
(331694,36855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ateş sessiz sedasız tuttuğunda o külün üstüne odun ...'::text,'diziyordu'::text,'dizdi'::text,'dizdi'::text,'Kanka, ateş sessiz sedasız tuttuğunda o külün üstüne odun diziyordu.'::text),
(331695,36855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp fahasábokat ... a hamura, amikor a tűz csak úgy begyulladt.'::text,'rakott'::text,'rakott'::text,'rakott'::text,'Tesó, épp fahasábokat rakott a hamura, amikor a tűz csak úgy begyulladt.'::text),
(331698,36856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, dieser Kamin ... seit Jahren Asche, kein Witz.'::text,'sammelt'::text,'sammelt'::text,'sammelt'::text,'Alter, dieser Kamin sammelt seit Jahren Asche, kein Witz.'::text),
(331702,36856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, цей камін ... попіл уже, типу, роками, без жартів.'::text,'збирає'::text,'збирає'::text,'збирає'::text,'Чувак, цей камін збирає попіл уже, типу, роками, без жартів.'::text),
(331701,36856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esta chimenea ... ceniza desde hace años, en serio.'::text,'acumula'::text,'está acumulando'::text,'acumula'::text,'Tío, esta chimenea acumula ceniza desde hace años, en serio.'::text),
(331700,36856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, cette cheminée ... de la cendre depuis genre des années, sans mentir.'::text,'accumule'::text,'accumule'::text,'accumule'::text,'Mec, cette cheminée accumule de la cendre depuis genre des années, sans mentir.'::text),
(331703,36856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu şömine yıllardır kül ..., yemin ederim.'::text,'biriktiriyor'::text,'biriktiriyor'::text,'biriktirir'::text,'Kanka, bu şömine yıllardır kül biriktiriyor, yemin ederim.'::text),
(331704,36856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a kandalló már vagy évek óta ... a hamut, komolyan.'::text,'gyűjti'::text,'gyűjti'::text,'gyűjti'::text,'Tesó, ez a kandalló már vagy évek óta gyűjti a hamut, komolyan.'::text),
(331707,36857,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade die Scheite auf die Asche, als die ersten Flammen auftauchten.'::text,'legte'::text,'legte'::text,'legte'::text,'Er legte gerade die Scheite auf die Asche, als die ersten Flammen auftauchten.'::text),
(331711,36857,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... поліна на попіл, коли з''явилися перші язики полум''я.'::text,'клав'::text,'поклав'::text,'поклав'::text,'Він клав поліна на попіл, коли з''явилися перші язики полум''я.'::text),
(331710,36857,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los troncos sobre la ceniza cuando aparecieron las primeras llamas.'::text,'Estaba colocando'::text,'Colocó'::text,'Ha colocado'::text,'Estaba colocando los troncos sobre la ceniza cuando aparecieron las primeras llamas.'::text),
(331709,36857,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les bûches sur la cendre quand les premières flammes sont apparues.'::text,'posait'::text,'a posé'::text,'a posé'::text,'Il posait les bûches sur la cendre quand les premières flammes sont apparues.'::text),
(331712,36857,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk alevler göründüğünde odunları külün üstüne ...'::text,'yerleştiriyordu'::text,'yerleştirdi'::text,'yerleştirdi'::text,'İlk alevler göründüğünde odunları külün üstüne yerleştiriyordu.'::text),
(331713,36857,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a hamura ... a fahasábokat, amikor megjelentek az első lángok.'::text,'rakta'::text,'rakta'::text,'rakta'::text,'Épp a hamura rakta a fahasábokat, amikor megjelentek az első lángok.'::text),
(331716,36858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher hat er drei Scheite auf die dicke graue Asche ...'::text,'gelegt'::text,'gelegt'::text,'gelegt'::text,'Bisher hat er drei Scheite auf die dicke graue Asche gelegt.'::text),
(331720,36858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки що він ... три поліна на товстий сірий попіл.'::text,'поклав'::text,'клав'::text,'кладе'::text,'Поки що він поклав три поліна на товстий сірий попіл.'::text),
(331719,36858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora ... tres troncos sobre la gruesa capa de ceniza gris.'::text,'ha colocado'::text,'ha estado colocando'::text,'está colocando'::text,'Hasta ahora ha colocado tres troncos sobre la gruesa capa de ceniza gris.'::text),
(331718,36858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, il ... trois bûches sur l''épaisse cendre grise.'::text,'a posé'::text,'pose'::text,'est en train de poser'::text,'Jusqu''ici, il a posé trois bûches sur l''épaisse cendre grise.'::text),
(331721,36858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar kalın gri külün üstüne üç odun ...'::text,'yerleştirdi'::text,'yerleştiriyor'::text,'yerleştiriyor'::text,'Şimdiye kadar kalın gri külün üstüne üç odun yerleştirdi.'::text),
(331722,36858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig három fahasábot ... a vastag szürke hamura.'::text,'tett'::text,'rakosgat'::text,'tesz'::text,'Eddig három fahasábot tett a vastag szürke hamura.'::text),
(331725,36859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor er das Feuer anzündete, ... niemand die alte Asche vom Boden entfernt.'::text,'hatte'::text,'hat'::text,'hatte'::text,'Bevor er das Feuer anzündete, hatte niemand die alte Asche vom Boden entfernt.'::text),
(331729,36859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж він розпалив вогонь, ніхто не ... старий попіл з дна.'::text,'прибрав'::text,'прибрав'::text,'прибирає'::text,'Перш ніж він розпалив вогонь, ніхто не прибрав старий попіл з дна.'::text),
(331728,36859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que encendiera el fuego, nadie ... la ceniza vieja del suelo.'::text,'había quitado'::text,'ha quitado'::text,'quita'::text,'Antes de que encendiera el fuego, nadie había quitado la ceniza vieja del suelo.'::text),
(331727,36859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''il allume le feu, personne ... la vieille cendre du sol.'::text,'n''avait enlevé'::text,'n''a enlevé'::text,'n''enlève'::text,'Avant qu''il allume le feu, personne n''avait enlevé la vieille cendre du sol.'::text),
(331730,36859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ateşi yakmadan önce kimse eski külü zeminden ...'::text,'temizlememişti'::text,'temizlemedi'::text,'temizlemiyor'::text,'O ateşi yakmadan önce kimse eski külü zeminden temizlememişti.'::text),
(331731,36859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt meggyújtotta a tüzet, senki sem ... el a régi hamut az aljáról.'::text,'távolította'::text,'távolította'::text,'távolítja'::text,'Mielőtt meggyújtotta a tüzet, senki sem távolította el a régi hamut az aljáról.'::text),
(331743,36861,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er die Asche ..., würde der Kamin wie neu aussehen. Echt eine Priorität.'::text,'ausräumte'::text,'ausräumt'::text,'ausräumen würde'::text,'Wenn er die Asche ausräumte, würde der Kamin wie neu aussehen. Echt eine Priorität.'::text),
(331747,36861,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він ... попіл, камін виглядав би як новий. Справді пріоритет.'::text,'вигріб'::text,'вигрібає'::text,'вигріб би'::text,'Якби він вигріб попіл, камін виглядав би як новий. Справді пріоритет.'::text),
(331746,36861,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... la ceniza, la chimenea parecería nueva. Toda una prioridad, de verdad.'::text,'quitara'::text,'quita'::text,'quitaría'::text,'Si quitara la ceniza, la chimenea parecería nueva. Toda una prioridad, de verdad.'::text),
(331745,36861,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ... la cendre, la cheminée aurait l''air neuve. Vraiment une priorité.'::text,'enlevait'::text,'enlève'::text,'enlèverait'::text,'S''il enlevait la cendre, la cheminée aurait l''air neuve. Vraiment une priorité.'::text),
(331748,36861,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Külü ..., şömine yepyeni görünürdü. Gerçekten bir öncelik.'::text,'temizlese'::text,'temizliyor'::text,'temizlerdi'::text,'Külü temizlese, şömine yepyeni görünürdü. Gerçekten bir öncelik.'::text),
(331749,36861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ... a hamut, a kandalló vadonatújnak tűnne. Tényleg prioritás.'::text,'kitakarítaná'::text,'kitakarítja'::text,'kitakarítaná'::text,'Ha kitakarítaná a hamut, a kandalló vadonatújnak tűnne. Tényleg prioritás.'::text),
(331752,36862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ahnte nicht, dass aus seinem Feuer bis zum Morgen kalte graue Asche ... – das Ende von allem!'::text,'werden würde'::text,'wird'::text,'wird'::text,'Er ahnte nicht, dass aus seinem Feuer bis zum Morgen kalte graue Asche werden würde – das Ende von allem!'::text),
(331756,36862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він і гадки не мав, що до ранку його вогонь ... на холодний сірий попіл. Кінець усьому!'::text,'перетвориться'::text,'перетвориться'::text,'перетворюється'::text,'Він і гадки не мав, що до ранку його вогонь перетвориться на холодний сірий попіл. Кінець усьому!'::text),
(331755,36862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No tenía ni idea de que su fuego ... en ceniza gris y fría por la mañana. ¡El fin de todo!'::text,'se convertiría'::text,'se convertirá'::text,'se convierte'::text,'No tenía ni idea de que su fuego se convertiría en ceniza gris y fría por la mañana. ¡El fin de todo!'::text),
(331754,36862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''avait aucune idée que son feu ... en cendre grise et froide au matin. La fin de tout !'::text,'se transformerait'::text,'se transformera'::text,'se transforme'::text,'Il n''avait aucune idée que son feu se transformerait en cendre grise et froide au matin. La fin de tout !'::text),
(331757,36862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ateşinin sabaha kadar soğuk gri küle ... hiç bilmiyordu. Her şeyin sonu!'::text,'döneceğini'::text,'döneceğini'::text,'döndüğünü'::text,'Ateşinin sabaha kadar soğuk gri küle döneceğini hiç bilmiyordu. Her şeyin sonu!'::text),
(331758,36862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fogalma sem volt, hogy a tüze reggelre ... hideg szürke hamuvá. Mindennek vége!'::text,'válik'::text,'fog válni'::text,'válik'::text,'Fogalma sem volt, hogy a tüze reggelre válik hideg szürke hamuvá. Mindennek vége!'::text),
(331761,36863,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes Feuer in dieser Hütte ... am Ende zu Asche. Nichts hält ewig!'::text,'wird'::text,'wird'::text,'wird'::text,'Jedes Feuer in dieser Hütte wird am Ende zu Asche. Nichts hält ewig!'::text),
(331765,36863,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожен вогонь у цьому шале зрештою ... на попіл. Ніщо не вічне!'::text,'перетворюється'::text,'перетворюється'::text,'перетворився'::text,'Кожен вогонь у цьому шале зрештою перетворюється на попіл. Ніщо не вічне!'::text),
(331764,36863,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo fuego en este chalé ... en ceniza al final. ¡Nada dura para siempre!'::text,'se convierte'::text,'se está convirtiendo'::text,'se ha convertido'::text,'Todo fuego en este chalé se convierte en ceniza al final. ¡Nada dura para siempre!'::text),
(331763,36863,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque feu de ce chalet ... en cendre à la fin. Rien ne dure éternellement !'::text,'se transforme'::text,'est en train de se transformer'::text,'s''est transformé'::text,'Chaque feu de ce chalet se transforme en cendre à la fin. Rien ne dure éternellement !'::text),
(331766,36863,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu dağ evindeki her ateş sonunda küle ...; hiçbir şey sonsuza dek sürmez!'::text,'döner'::text,'dönüyor'::text,'döndü'::text,'Bu dağ evindeki her ateş sonunda küle döner; hiçbir şey sonsuza dek sürmez!'::text),
(331767,36863,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a faházban minden tűz ... végül hamuvá. Semmi sem tart örökké!'::text,'válik'::text,'válik'::text,'vált'::text,'Ebben a faházban minden tűz válik végül hamuvá. Semmi sem tart örökké!'::text),
(331770,36864,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor, anscheinend ... niemand jahrelang die Asche aus dem Kamin geholt, bevor er kam.'::text,'hatte'::text,'hat'::text,'hatte'::text,'Stell dir vor, anscheinend hatte niemand jahrelang die Asche aus dem Kamin geholt, bevor er kam.'::text),
(331774,36864,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, ніхто роками не ... попіл із того каміна, поки він не приїхав.'::text,'вигрібав'::text,'вигріб'::text,'вигрібав'::text,'Уяви, кажуть, ніхто роками не вигрібав попіл із того каміна, поки він не приїхав.'::text),
(331773,36864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Flipa, por lo visto nadie ... la ceniza de esa chimenea en años antes de que él llegara.'::text,'había quitado'::text,'ha quitado'::text,'estaba quitando'::text,'Flipa, por lo visto nadie había quitado la ceniza de esa chimenea en años antes de que él llegara.'::text),
(331772,36864,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça, apparemment personne ... la cendre de cette cheminée depuis des années avant qu''il arrive.'::text,'n''avait enlevé'::text,'n''a enlevé'::text,'n''enlevait'::text,'Écoute ça, apparemment personne n''avait enlevé la cendre de cette cheminée depuis des années avant qu''il arrive.'::text),
(331775,36864,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak, güya o gelmeden önce yıllarca kimse o şömineden külü ...'::text,'temizlememiş'::text,'temizlemedi'::text,'temizlemiyordu'::text,'Şuna bak, güya o gelmeden önce yıllarca kimse o şömineden külü temizlememiş.'::text),
(331776,36864,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag évekig senki sem ... ki a hamut abból a kandallóból, mielőtt megérkezett.'::text,'takarította'::text,'takarította'::text,'takarította'::text,'Figyelj, állítólag évekig senki sem takarította ki a hamut abból a kandallóból, mielőtt megérkezett.'::text),
(355296,39478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder Dumplings, und das Tablett nimmt nie ein Ende!'::text,'faltet'::text,'faltet'::text,'faltet'::text,'Morgen um diese Zeit faltet sie wieder Dumplings, und das Tablett nimmt nie ein Ende!'::text),
