from (values
(355299,39478,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... dumplings otra vez, y la bandeja no se acabará nunca!'::text,'estará doblando'::text,'doblará'::text,'dobla'::text,'¡Mañana a esta hora estará doblando dumplings otra vez, y la bandeja no se acabará nunca!'::text),
(355298,39478,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... encore des dumplings, et le plateau ne finira jamais !'::text,'pliera'::text,'pliera'::text,'plie'::text,'Demain à la même heure, elle pliera encore des dumplings, et le plateau ne finira jamais !'::text),
(355301,39478,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine dumpling ... ve o tepsi asla bitmeyecek!'::text,'katlıyor olacak'::text,'katlayacak'::text,'katlıyor'::text,'Yarın bu saatlerde yine dumpling katlıyor olacak ve o tepsi asla bitmeyecek!'::text),
(355302,39478,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint dumplingokat ..., és a tálcának soha nem lesz vége!'::text,'fog hajtogatni'::text,'hajtogat majd'::text,'hajtogat'::text,'Holnap ilyenkor megint dumplingokat fog hajtogatni, és a tálcának soha nem lesz vége!'::text),
(355305,39479,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich schwöre, ich ... jeden einzelnen Dumpling perfekt, sonst ist es eine totale Katastrophe!'::text,'falte'::text,'falte'::text,'falte'::text,'Ich schwöre, ich falte jeden einzelnen Dumpling perfekt, sonst ist es eine totale Katastrophe!'::text),
(355309,39479,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клянуся, я ... кожен дамплінг ідеально, інакше це повна катастрофа!'::text,'загорну'::text,'загортатиму'::text,'загортаю'::text,'Клянуся, я загорну кожен дамплінг ідеально, інакше це повна катастрофа!'::text),
(355308,39479,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Te juro que ... cada dumpling a la perfección, o será un desastre total!'::text,'doblaré'::text,'estaré doblando'::text,'estoy doblando'::text,'¡Te juro que doblaré cada dumpling a la perfección, o será un desastre total!'::text),
(355307,39479,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je jure que je ... chaque dumpling parfaitement, sinon c''est la catastrophe totale !'::text,'plierai'::text,'serai en train de plier'::text,'plie'::text,'Je jure que je plierai chaque dumpling parfaitement, sinon c''est la catastrophe totale !'::text),
(355310,39479,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemin ederim her bir dumpling''i kusursuz ..., yoksa tam bir felaket olur!'::text,'katlayacağım'::text,'katlıyor olacağım'::text,'katlıyorum'::text,'Yemin ederim her bir dumpling''i kusursuz katlayacağım, yoksa tam bir felaket olur!'::text),
(355311,39479,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esküszöm, minden egyes dumplingot tökéletesen ..., különben totális katasztrófa!'::text,'meghajtogatom'::text,'hajtogatni fogom'::text,'hajtogatom'::text,'Esküszöm, minden egyes dumplingot tökéletesen meghajtogatom, különben totális katasztrófa!'::text),
(355323,39481,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, anscheinend können die Kids nicht so Dumplings falten wie Oma, und ...'::text,'der Mann auch nicht.'::text,'der Mann auch.'::text,'der Mann auch nicht.'::text,'Rate mal, anscheinend können die Kids nicht so Dumplings falten wie Oma, und der Mann auch nicht.'::text),
(355327,39481,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, кажуть, діти не вміють загортати дамплінги, як бабуся, і ...'::text,'той чоловік теж ні.'::text,'той чоловік теж.'::text,'той чоловік теж ні.'::text,'Вгадай що, кажуть, діти не вміють загортати дамплінги, як бабуся, і той чоловік теж ні.'::text),
(355326,39481,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, por lo visto los niños no saben doblar dumplings como la abuela, y ...'::text,'el hombre tampoco.'::text,'el hombre también.'::text,'el hombre tampoco.'::text,'Adivina qué, por lo visto los niños no saben doblar dumplings como la abuela, y el hombre tampoco.'::text),
(355325,39481,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment les enfants ne savent pas plier les dumplings comme mamie, et ...'::text,'l''homme non plus.'::text,'l''homme aussi.'::text,'l''homme non plus.'::text,'Devine quoi, apparemment les enfants ne savent pas plier les dumplings comme mamie, et l''homme non plus.'::text),
(355328,39481,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, güya çocuklar dumpling''leri büyükanne gibi katlayamıyor, ...'::text,'adam da katlayamıyor.'::text,'adam da katlayabiliyor.'::text,'adam da katlayamıyor.'::text,'Bil bakalım, güya çocuklar dumpling''leri büyükanne gibi katlayamıyor, adam da katlayamıyor.'::text),
(355329,39481,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag a gyerekek nem tudnak úgy dumplingot hajtogatni, mint a nagyi, és ...'::text,'a férfi sem.'::text,'a férfi is.'::text,'a férfi sem.'::text,'Képzeld, állítólag a gyerekek nem tudnak úgy dumplingot hajtogatni, mint a nagyi, és a férfi sem.'::text),
(355332,39482,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, ich hab gehört, dass Oma bis zum Abendessen heute hundert Dumplings ...'::text,'gefaltet haben wird'::text,'falten wird'::text,'faltet'::text,'Also, ich hab gehört, dass Oma bis zum Abendessen heute hundert Dumplings gefaltet haben wird.'::text),
(355336,39482,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, я чула, що бабуся до сьогоднішньої вечері ... сто дамплінгів.'::text,'загорне'::text,'загорне'::text,'загортає'::text,'Отже, я чула, що бабуся до сьогоднішньої вечері загорне сто дамплінгів.'::text),
(355335,39482,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, he oído que la abuela ... cien dumplings para la cena de esta noche.'::text,'habrá doblado'::text,'doblará'::text,'está doblando'::text,'Vale, he oído que la abuela habrá doblado cien dumplings para la cena de esta noche.'::text),
(355334,39482,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu dire que mamie ... cent dumplings d''ici le dîner de ce soir.'::text,'aura plié'::text,'pliera'::text,'est en train de plier'::text,'Bon, j''ai entendu dire que mamie aura plié cent dumplings d''ici le dîner de ce soir.'::text),
(355337,39482,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şöyle ki, büyükannenin bu akşam yemeğine kadar yüz dumpling ... duydum.'::text,'katlamış olacağını'::text,'katlayacağını'::text,'katladığını'::text,'Şöyle ki, büyükannenin bu akşam yemeğine kadar yüz dumpling katlamış olacağını duydum.'::text),
(355338,39482,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval úgy hallottam, a nagyi a mai vacsoráig száz dumplingot ...'::text,'meghajtogat'::text,'fog hajtogatni'::text,'hajtogat'::text,'Szóval úgy hallottam, a nagyi a mai vacsoráig száz dumplingot meghajtogat.'::text),
(355341,39483,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten die Kinder ihre Handbewegungen nicht nachgemacht, ... sie ihre Dumplings nicht so ordentlich gefaltet.'::text,'hätten'::text,'hätten'::text,'haben'::text,'Hätten die Kinder ihre Handbewegungen nicht nachgemacht, hätten sie ihre Dumplings nicht so ordentlich gefaltet.'::text),
(355345,39483,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби діти не повторювали рухи її рук, вони не ... свої дамплінги так акуратно.'::text,'загорнули б'::text,'загорнуть'::text,'загорнули'::text,'Якби діти не повторювали рухи її рук, вони не загорнули б свої дамплінги так акуратно.'::text),
(355344,39483,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los niños no hubieran copiado sus manos, no ... sus dumplings tan bien.'::text,'habrían doblado'::text,'doblarán'::text,'doblaron'::text,'Si los niños no hubieran copiado sus manos, no habrían doblado sus dumplings tan bien.'::text),
(355343,39483,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les enfants n''avaient pas copié ses gestes, ils ... leurs dumplings aussi proprement.'::text,'n''auraient pas plié'::text,'ne plieront pas'::text,'n''ont pas plié'::text,'Si les enfants n''avaient pas copié ses gestes, ils n''auraient pas plié leurs dumplings aussi proprement.'::text),
(355346,39483,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuklar onun ellerini taklit etmeseydi dumpling''lerini bu kadar düzgün ...'::text,'katlamazlardı'::text,'katlamayacaklar'::text,'katlamadılar'::text,'Çocuklar onun ellerini taklit etmeseydi dumpling''lerini bu kadar düzgün katlamazlardı.'::text),
(355347,39483,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a gyerekek nem utánozták volna a kezét, nem ... ilyen szépen a dumplingjaikat.'::text,'hajtogatták volna meg'::text,'fogják meghajtogatni'::text,'hajtogatták meg'::text,'Ha a gyerekek nem utánozták volna a kezét, nem hajtogatták volna meg ilyen szépen a dumplingjaikat.'::text),
(355350,39484,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oma fragte die Kinder, ob sie die Ränder ordentlich ...; makellose Falten, natürlich.'::text,'gefaltet hätten'::text,'gefaltet haben'::text,'falteten'::text,'Oma fragte die Kinder, ob sie die Ränder ordentlich gefaltet hätten; makellose Falten, natürlich.'::text),
(355354,39484,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бабуся спитала дітей, чи вони як слід ... краї. Бездоганні складки, звісно.'::text,'загнули'::text,'загнули'::text,'загнули'::text,'Бабуся спитала дітей, чи вони як слід загнули краї. Бездоганні складки, звісно.'::text),
(355353,39484,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La abuela preguntó a los niños si ... bien los bordes. Pliegues impecables, obviamente.'::text,'habían doblado'::text,'han doblado'::text,'doblaron'::text,'La abuela preguntó a los niños si habían doblado bien los bordes. Pliegues impecables, obviamente.'::text),
(355352,39484,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mamie a demandé aux enfants s''ils ... correctement les bords. Des plis impeccables, évidemment.'::text,'avaient plié'::text,'ont plié'::text,'ont plié'::text,'Mamie a demandé aux enfants s''ils avaient plié correctement les bords. Des plis impeccables, évidemment.'::text),
(355355,39484,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükanne çocuklara kenarları düzgünce ... sordu. Kusursuz kıvrımlar, belli ki.'::text,'katlayıp katlamadıklarını'::text,'katlayıp katlamadıklarını'::text,'katlayıp katlamadıklarını'::text,'Büyükanne çocuklara kenarları düzgünce katlayıp katlamadıklarını sordu. Kusursuz kıvrımlar, belli ki.'::text),
(355356,39484,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagyi megkérdezte a gyerekeket, hogy vajon rendesen ... a széleket. Hibátlan redők, nyilván.'::text,'behajtották'::text,'behajtották'::text,'behajtották'::text,'A nagyi megkérdezte a gyerekeket, hogy vajon rendesen behajtották a széleket. Hibátlan redők, nyilván.'::text),
(355359,39485,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... ihr beim Falten helfen sollen, bevor er den Deckel hob. Ein echter Teamplayer, klar.'::text,'hätte'::text,'hätte nicht'::text,'sollte'::text,'Der Mann hätte ihr beim Falten helfen sollen, bevor er den Deckel hob. Ein echter Teamplayer, klar.'::text),
(355363,39485,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... допомогти їх загортати, перш ніж підняти кришку. Справжній командний гравець, звісно.'::text,'мав би'::text,'не мав права'::text,'має'::text,'Чоловік мав би допомогти їх загортати, перш ніж підняти кришку. Справжній командний гравець, звісно.'::text),
(355362,39485,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... ayudado a doblarlos antes de levantar la tapa. Todo un jugador de equipo, obviamente.'::text,'debería haber'::text,'no debe de haber'::text,'debería'::text,'El hombre debería haber ayudado a doblarlos antes de levantar la tapa. Todo un jugador de equipo, obviamente.'::text),
(355361,39485,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... aidé à les plier avant de soulever le couvercle. Un vrai joueur d''équipe, évidemment.'::text,'aurait dû'::text,'ne doit pas avoir'::text,'devrait'::text,'L''homme aurait dû aidé à les plier avant de soulever le couvercle. Un vrai joueur d''équipe, évidemment.'::text),
(355364,39485,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam kapağı kaldırmadan önce onları katlamaya yardım ...; gerçek bir takım oyuncusu, belli ki.'::text,'etmeliydi'::text,'etmemiş olmalı'::text,'etmeli'::text,'Adam kapağı kaldırmadan önce onları katlamaya yardım etmeliydi; gerçek bir takım oyuncusu, belli ki.'::text),
(355365,39485,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfinak ... segítenie hajtogatni, mielőtt felemelte a fedőt. Igazi csapatjátékos, nyilván.'::text,'kellett volna'::text,'nem kellett'::text,'kellene'::text,'A férfinak kellett volna segítenie hajtogatni, mielőtt felemelte a fedőt. Igazi csapatjátékos, nyilván.'::text),
(355368,39486,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächstes Jahr lässt Oma die Kinder alle Dumplings selbst ...'::text,'falten'::text,'falten'::text,'faltend'::text,'Nächstes Jahr lässt Oma die Kinder alle Dumplings selbst falten.'::text),
(355372,39486,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного року бабуся змусить дітей ... всі дамплінги самостійно.'::text,'загортати'::text,'загортати'::text,'загортаючи'::text,'Наступного року бабуся змусить дітей загортати всі дамплінги самостійно.'::text),
(355371,39486,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El año que viene, la abuela hará que los niños ... todos los dumplings ellos solos.'::text,'doblen'::text,'doblen'::text,'doblando'::text,'El año que viene, la abuela hará que los niños doblen todos los dumplings ellos solos.'::text),
(355370,39486,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''année prochaine, mamie demandera aux enfants de ... tous les dumplings eux-mêmes.'::text,'plier'::text,'plier'::text,'pliant'::text,'L''année prochaine, mamie demandera aux enfants de plier tous les dumplings eux-mêmes.'::text),
(355373,39486,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seneye büyükanne bütün dumpling''leri çocuklara kendi başlarına ...'::text,'katlatacak'::text,'katlatacak'::text,'katlayarak'::text,'Seneye büyükanne bütün dumpling''leri çocuklara kendi başlarına katlatacak.'::text),
(355374,39486,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövőre a nagyi rábírja a gyerekeket, hogy maguk ... az összes dumplingot.'::text,'hajtogassák meg'::text,'hajtogassák meg'::text,'hajtogatva'::text,'Jövőre a nagyi rábírja a gyerekeket, hogy maguk hajtogassák meg az összes dumplingot.'::text),
(355377,39487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beim Blick auf ihre Hände wünscht sich der Mann, er ... Dumplings so schnell falten wie sie.'::text,'könnte'::text,'kann'::text,'wird'::text,'Beim Blick auf ihre Hände wünscht sich der Mann, er könnte Dumplings so schnell falten wie sie.'::text),
(355381,39487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивлячись на її руки, чоловік хотів би ... дамплінги так само швидко, як вона.'::text,'вміти загортати'::text,'вміє загортати'::text,'загортатиме'::text,'Дивлячись на її руки, чоловік хотів би вміти загортати дамплінги так само швидко, як вона.'::text),
(355380,39487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mirando sus manos, el hombre desearía ... dumplings tan rápido como ella.'::text,'poder doblar'::text,'puede doblar'::text,'doblará'::text,'Mirando sus manos, el hombre desearía poder doblar dumplings tan rápido como ella.'::text),
(355379,39487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En regardant ses mains, l''homme aimerait ... des dumplings aussi vite qu''elle.'::text,'pouvoir plier'::text,'peut plier'::text,'pliera'::text,'En regardant ses mains, l''homme aimerait pouvoir plier des dumplings aussi vite qu''elle.'::text),
(355382,39487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun ellerini izleyen adam, keşke onun kadar hızlı dumpling ... diye düşünüyor.'::text,'katlayabilse'::text,'katlayabiliyor'::text,'katlayacak'::text,'Onun ellerini izleyen adam, keşke onun kadar hızlı dumpling katlayabilse diye düşünüyor.'::text),
(355383,39487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kezét nézve a férfi azt kívánja, bárcsak olyan gyorsan ... dumplingot hajtogatni, mint ő.'::text,'tudna'::text,'tud'::text,'fog tudni'::text,'A kezét nézve a férfi azt kívánja, bárcsak olyan gyorsan tudna dumplingot hajtogatni, mint ő.'::text),
(349788,38866,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um zwölf ... sie bei der Wahl, weil sie da eben wählt.'::text,'wählt'::text,'wählt'::text,'wählt'::text,'Morgen um zwölf wählt sie bei der Wahl, weil sie da eben wählt.'::text),
(349792,38866,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні вона ... на виборах, бо саме тоді вона голосує.'::text,'голосуватиме'::text,'проголосує'::text,'голосує'::text,'Завтра опівдні вона голосуватиме на виборах, бо саме тоді вона голосує.'::text),
(349791,38866,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a mediodía ... en las elecciones, porque es cuando vota.'::text,'estará votando'::text,'votará'::text,'vota'::text,'Mañana a mediodía estará votando en las elecciones, porque es cuando vota.'::text),
(349790,38866,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, elle ... à l''élection, parce que c''est à ce moment-là qu''elle vote.'::text,'votera'::text,'votera'::text,'vote'::text,'Demain à midi, elle votera à l''élection, parce que c''est à ce moment-là qu''elle vote.'::text),
(349793,38866,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen seçimde oy ..., çünkü o saatte oy veriyor.'::text,'veriyor olacak'::text,'verecek'::text,'veriyor'::text,'Yarın öğlen seçimde oy veriyor olacak, çünkü o saatte oy veriyor.'::text),
(349794,38866,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben ... a választáson, mert akkor szavaz.'::text,'szavazni fog'::text,'szavaz majd'::text,'szavaz'::text,'Holnap délben szavazni fog a választáson, mert akkor szavaz.'::text),
(349797,38867,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sobald die Wahllokale schließen, ... die Stimmen der Wahl ausgezählt, wie es typischerweise vorgeschrieben ist.'::text,'werden'::text,'werden'::text,'werden gerade'::text,'Sobald die Wahllokale schließen, werden die Stimmen der Wahl ausgezählt, wie es typischerweise vorgeschrieben ist.'::text),
(349801,38867,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно дільниці закриються, голоси на виборах ..., як це зазвичай вимагається.'::text,'будуть підраховані'::text,'будуть підраховуватися'::text,'підраховуються'::text,'Щойно дільниці закриються, голоси на виборах будуть підраховані, як це зазвичай вимагається.'::text),
(349800,38867,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando cierren los colegios electorales, los votos de las elecciones ... contados, como se exige habitualmente.'::text,'serán'::text,'estarán siendo'::text,'están siendo'::text,'Cuando cierren los colegios electorales, los votos de las elecciones serán contados, como se exige habitualmente.'::text),
(349799,38867,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fois les bureaux de vote fermés, les voix de l''élection ... comptées, comme c''est généralement requis.'::text,'seront'::text,'seront'::text,'sont en train d''être'::text,'Une fois les bureaux de vote fermés, les voix de l''élection seront comptées, comme c''est généralement requis.'::text),
(349802,38867,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandıklar kapanır kapanmaz seçimdeki oylar, genellikle gerektiği gibi ...'::text,'sayılacak'::text,'sayılıyor olacak'::text,'sayılıyor'::text,'Sandıklar kapanır kapanmaz seçimdeki oylar, genellikle gerektiği gibi sayılacak.'::text),
(349803,38867,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amint bezárnak a szavazóhelyiségek, a választás szavazatait ..., ahogy az általában előírás.'::text,'megszámolják'::text,'számolni fogják'::text,'számolják'::text,'Amint bezárnak a szavazóhelyiségek, a választás szavazatait megszámolják, ahogy az általában előírás.'::text),
(349806,38868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Stimme bei der Wahl ... mit Bleistift markiert.'::text,'wurde'::text,'hat'::text,'wird'::text,'Ihre Stimme bei der Wahl wurde mit Bleistift markiert.'::text),
(349810,38868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її голос на виборах ... олівцем.'::text,'був позначений'::text,'позначив'::text,'позначає'::text,'Її голос на виборах був позначений олівцем.'::text),
(349809,38868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su voto en las elecciones ... a lápiz.'::text,'fue marcado'::text,'marcó'::text,'está marcando'::text,'Su voto en las elecciones fue marcado a lápiz.'::text),
(349808,38868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son vote à l''élection ... au crayon.'::text,'a été marqué'::text,'a marqué'::text,'est en train de marquer'::text,'Son vote à l''élection a été marqué au crayon.'::text),
(349811,38868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seçimdeki oyu kurşun kalemle ...'::text,'işaretlendi'::text,'işaretledi'::text,'işaretliyor'::text,'Seçimdeki oyu kurşun kalemle işaretlendi.'::text),
(349812,38868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szavazatát a választáson ceruzával ...'::text,'jelölték be'::text,'bejelölte'::text,'jelöli be'::text,'A szavazatát a választáson ceruzával jelölték be.'::text),
(349815,38869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... mit ihrem gelben Bleistift ein Kästchen auf dem Wahlzettel.'::text,'markierte'::text,'wurde markiert'::text,'markierend'::text,'Sie markierte mit ihrem gelben Bleistift ein Kästchen auf dem Wahlzettel.'::text),
(349819,38869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... одну клітинку в бюлетені своїм жовтим олівцем.'::text,'позначила'::text,'була позначена'::text,'позначаючи'::text,'Вона позначила одну клітинку в бюлетені своїм жовтим олівцем.'::text),
(349818,38869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una casilla de la papeleta con su lápiz amarillo.'::text,'Marcó'::text,'Fue marcada'::text,'Marcando'::text,'Marcó una casilla de la papeleta con su lápiz amarillo.'::text),
(349817,38869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... une case sur le bulletin avec son crayon jaune.'::text,'a coché'::text,'a été cochée'::text,'cochant'::text,'Elle a coché une case sur le bulletin avec son crayon jaune.'::text),
(349820,38869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarı kalemiyle oy pusulasındaki bir kutuyu ...'::text,'işaretledi'::text,'işaretlendi'::text,'işaretleyerek'::text,'Sarı kalemiyle oy pusulasındaki bir kutuyu işaretledi.'::text),
(349821,38869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sárga ceruzájával ... egy négyzetet a szavazólapon.'::text,'bejelölt'::text,'be lett jelölve'::text,'bejelölve'::text,'A sárga ceruzájával bejelölt egy négyzetet a szavazólapon.'::text),
(349824,38870,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... die sorgfältigste Wählerin bei dieser ganzen Wahl sein.'::text,'musst'::text,'kannst nicht'::text,'solltest'::text,'Ehrlich, du musst die sorgfältigste Wählerin bei dieser ganzen Wahl sein.'::text),
(349828,38870,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... бути найуважнішою виборницею на всіх цих виборах.'::text,'мусиш'::text,'не можеш'::text,'мала б'::text,'Чесно, ти мусиш бути найуважнішою виборницею на всіх цих виборах.'::text),
(349827,38870,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... ser la votante más cuidadosa de todas estas elecciones.'::text,'debes de'::text,'no puedes'::text,'deberías'::text,'Sinceramente, debes de ser la votante más cuidadosa de todas estas elecciones.'::text),
(349826,38870,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... être l''électrice la plus minutieuse de toute cette élection.'::text,'dois'::text,'ne peux pas'::text,'devrais'::text,'Franchement, tu dois être l''électrice la plus minutieuse de toute cette élection.'::text),
(349829,38870,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bu seçimin en dikkatli seçmeni sen ...'::text,'olmalısın'::text,'olamazsın'::text,'olmalısın'::text,'Açıkçası bu seçimin en dikkatli seçmeni sen olmalısın.'::text),
(349830,38870,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ezen az egész választáson te ... a legalaposabb szavazó.'::text,'biztosan vagy'::text,'nem lehetsz'::text,'kellene lenned'::text,'Őszintén, ezen az egész választáson te biztosan vagy a legalaposabb szavazó.'::text),
(349833,38871,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kandidat, ... sie angekreuzt hat, wird die Wahl eindeutig gewinnen.'::text,'den'::text,'welcher'::text,'wo'::text,'Der Kandidat, den sie angekreuzt hat, wird die Wahl eindeutig gewinnen.'::text),
(349837,38871,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кандидат, ... вона позначила, явно виграє вибори.'::text,'якого'::text,'який'::text,'де'::text,'Кандидат, якого вона позначила, явно виграє вибори.'::text),
(349836,38871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El candidato ... marcó ganará las elecciones, está clarísimo.'::text,'al que'::text,'que'::text,'donde'::text,'El candidato al que marcó ganará las elecciones, está clarísimo.'::text),
(349835,38871,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le candidat ... elle a coché va clairement gagner l''élection.'::text,'qu'''::text,'lequel'::text,'où'::text,'Le candidat qu'' elle a coché va clairement gagner l''élection.'::text),
(349838,38871,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... işaretlediği aday seçimi açıkça kazanacak.'::text,''::text,NULL::text,NULL::text,'İşaretlediği aday seçimi açıkça kazanacak.'::text),
(349839,38871,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelölt, ... bejelölt, egyértelműen megnyeri a választást.'::text,'akit'::text,'amelyik'::text,'ahol'::text,'A jelölt, akit bejelölt, egyértelműen megnyeri a választást.'::text),
(349851,38873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... vor jeder Wahl nervös, aber jetzt lächelt sie.'::text,'war früher'::text,'war früher'::text,'war es gewohnt'::text,'Sie war früher vor jeder Wahl nervös, aber jetzt lächelt sie.'::text),
(349855,38873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше вона ... перед кожними виборами, а тепер усміхається.'::text,'нервувала'::text,'нервувала'::text,'звикла нервувати'::text,'Раніше вона нервувала перед кожними виборами, а тепер усміхається.'::text),
(349854,38873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes ... estar nerviosa antes de cada elección, pero ahora sonríe.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Antes solía estar nerviosa antes de cada elección, pero ahora sonríe.'::text),
(349853,38873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant chaque élection, elle ... nerveuse, mais maintenant elle sourit.'::text,'était toujours'::text,'était toujours'::text,'avait l''habitude d''être'::text,'Avant chaque élection, elle était toujours nerveuse, mais maintenant elle sourit.'::text),
(349856,38873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden her seçimden önce gergin ..., ama şimdi gülümsüyor.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Eskiden her seçimden önce gergin olurdu, ama şimdi gülümsüyor.'::text),
(349857,38873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen minden választás előtt ideges ..., de most mosolyog.'::text,'szokott lenni'::text,'szokott lenni'::text,'hozzá volt szokva'::text,'Régen minden választás előtt ideges szokott lenni, de most mosolyog.'::text),
(349860,38874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie beendete das ... der Namensliste und kreuzte bei der Wahl ein Kästchen an.'::text,'Lesen'::text,'Lesen'::text,'Lesen'::text,'Sie beendete das Lesen der Namensliste und kreuzte bei der Wahl ein Kästchen an.'::text),
(349864,38874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона закінчила ... список імен і позначила одну клітинку на виборах.'::text,'читати'::text,'читати'::text,'читати'::text,'Вона закінчила читати список імен і позначила одну клітинку на виборах.'::text),
(349863,38874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Terminó de ... la lista de nombres y marcó una casilla en las elecciones.'::text,'leer'::text,'leer'::text,'leer'::text,'Terminó de leer la lista de nombres y marcó una casilla en las elecciones.'::text),
(349862,38874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fini de ... la liste des noms et a coché une case pour l''élection.'::text,'lire'::text,'lire'::text,'lire'::text,'Elle a fini de lire la liste des noms et a coché une case pour l''élection.'::text),
(349865,38874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İsim listesini ... bitirdi ve seçimde bir kutuyu işaretledi.'::text,'okumayı'::text,'okumayı'::text,'okumayı'::text,'İsim listesini okumayı bitirdi ve seçimde bir kutuyu işaretledi.'::text),
(349866,38874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Befejezte a nevek listájának ..., és bejelölt egy négyzetet a választáson.'::text,'olvasását'::text,'olvasását'::text,'olvasását'::text,'Befejezte a nevek listájának olvasását, és bejelölt egy négyzetet a választáson.'::text),
(349869,38875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... so krass über diese Wahl nach, irgendwie legendär.'::text,'denkt'::text,'denkt'::text,'dachte'::text,'Bro, sie denkt so krass über diese Wahl nach, irgendwie legendär.'::text),
(349873,38875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона так напружено ... про ці вибори, трохи культово.'::text,'думає'::text,'думає'::text,'подумала'::text,'Бро, вона так напружено думає про ці вибори, трохи культово.'::text),
(349872,38875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... tanto en estas elecciones, en plan icónico.'::text,'está pensando'::text,'piensa'::text,'ha pensado'::text,'Bro, está pensando tanto en estas elecciones, en plan icónico.'::text),
(349871,38875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... tellement à cette élection, un peu iconique.'::text,'est en train de réfléchir'::text,'réfléchit'::text,'a réfléchi'::text,'Frérot, elle est en train de réfléchir tellement à cette élection, un peu iconique.'::text),
(349874,38875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu seçimi öyle bir ..., biraz efsane.'::text,'düşünüyor'::text,'düşünür'::text,'düşündü'::text,'Kanka, bu seçimi öyle bir düşünüyor, biraz efsane.'::text),
(349875,38875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annyira ... ezen a választáson, kicsit ikonikus.'::text,'gondolkodik'::text,'gondolkodik'::text,'gondolkodott'::text,'Tesó, annyira gondolkodik ezen a választáson, kicsit ikonikus.'::text),
(398397,44267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die drei Frauen ... seit acht Uhr Müll in diesem Park.'::text,'sammeln'::text,'sammeln'::text,'sammeln'::text,'Die drei Frauen sammeln seit acht Uhr Müll in diesem Park.'::text),
(398401,44267,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Три жінки ... сміття в цьому парку з восьмої години.'::text,'збирають'::text,'збирають'::text,'збирають'::text,'Три жінки збирають сміття в цьому парку з восьмої години.'::text),
(398400,44267,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las tres mujeres ... basura en este parque desde las ocho.'::text,'llevan recogiendo'::text,'están recogiendo'::text,'recogen'::text,'Las tres mujeres llevan recogiendo basura en este parque desde las ocho.'::text),
(398399,44267,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les trois femmes ... des déchets dans ce parc depuis huit heures.'::text,'ramassent'::text,'sont en train de ramasser'::text,'ramassent'::text,'Les trois femmes ramassent des déchets dans ce parc depuis huit heures.'::text),
(398402,44267,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç kadın saat sekizden beri bu parkta çöp ...'::text,'topluyor'::text,'topluyor'::text,'toplar'::text,'Üç kadın saat sekizden beri bu parkta çöp topluyor.'::text),
(398403,44267,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A három nő nyolc óra óta ... a szemetet ebben a parkban.'::text,'szedi'::text,'szedi'::text,'szedi'::text,'A három nő nyolc óra óta szedi a szemetet ebben a parkban.'::text),
(398406,44268,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern um zehn ... sie gerade Müll im Park, deshalb hat sie meinen Anruf verpasst.'::text,'sammelte'::text,'sammelte'::text,'sammelte'::text,'Gestern um zehn sammelte sie gerade Müll im Park, deshalb hat sie meinen Anruf verpasst.'::text),
(398410,44268,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора о десятій вона ... сміття в парку, тож пропустила мій дзвінок.'::text,'збирала'::text,'зібрала'::text,'зібрала'::text,'Учора о десятій вона збирала сміття в парку, тож пропустила мій дзвінок.'::text),
(398409,44268,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer a las diez ... basura en el parque, así que no vio mi llamada.'::text,'estaba recogiendo'::text,'recogió'::text,'ha recogido'::text,'Ayer a las diez estaba recogiendo basura en el parque, así que no vio mi llamada.'::text),
(398408,44268,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier à dix heures, elle ... des déchets dans le parc, alors elle a raté mon appel.'::text,'ramassait'::text,'a ramassé'::text,'a ramassé'::text,'Hier à dix heures, elle ramassait des déchets dans le parc, alors elle a raté mon appel.'::text),
(398411,44268,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün saat onda parkta çöp ..., o yüzden aramamı kaçırdı.'::text,'topluyordu'::text,'topladı'::text,'topladı'::text,'Dün saat onda parkta çöp topluyordu, o yüzden aramamı kaçırdı.'::text),
(398412,44268,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap tízkor épp szemetet ... a parkban, ezért nem vette fel a hívásomat.'::text,'szedett'::text,'szedett'::text,'szedett'::text,'Tegnap tízkor épp szemetet szedett a parkban, ezért nem vette fel a hívásomat.'::text),
(398415,44269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben schon drei Säcke mit Müll ..., und der Park ist immer noch eine komplette Katastrophe!'::text,'gefüllt'::text,'gefüllt'::text,'gefüllt'::text,'Sie haben schon drei Säcke mit Müll gefüllt, und der Park ist immer noch eine komplette Katastrophe!'::text),
(398419,44269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони вже ... три мішки сміттям, а парк досі повна катастрофа!'::text,'наповнили'::text,'наповнювали'::text,'наповнюють'::text,'Вони вже наповнили три мішки сміттям, а парк досі повна катастрофа!'::text),
(398418,44269,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ya ... tres bolsas de basura y el parque sigue siendo un desastre total!'::text,'han llenado'::text,'llevan llenando'::text,'están llenando'::text,'¡Ya han llenado tres bolsas de basura y el parque sigue siendo un desastre total!'::text),
(398417,44269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ... déjà trois sacs de déchets, et le parc est toujours une catastrophe complète !'::text,'ont rempli'::text,'remplissent'::text,'sont en train de remplir'::text,'Elles ont rempli déjà trois sacs de déchets, et le parc est toujours une catastrophe complète !'::text),
(398420,44269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiden üç torbayı çöple ... ve park hâlâ tam bir felaket!'::text,'doldurdular'::text,'dolduruyorlar'::text,'dolduruyorlar'::text,'Şimdiden üç torbayı çöple doldurdular ve park hâlâ tam bir felaket!'::text),
(398421,44269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már három zsákot ... meg szeméttel, és a park még mindig totális katasztrófa!'::text,'töltöttek'::text,'töltenek'::text,'töltenek'::text,'Már három zsákot töltöttek meg szeméttel, és a park még mindig totális katasztrófa!'::text),
(398424,44270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir erzählt, dass die Leute schon Müll im ganzen Park ..., bevor sie ankam.'::text,'hinterlassen hatten'::text,'hinterlassen haben'::text,'hinterlassen'::text,'Hör zu, sie hat mir erzählt, dass die Leute schon Müll im ganzen Park hinterlassen hatten, bevor sie ankam.'::text),
(398428,44270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що люди ... сміття по всьому парку ще до її приходу.'::text,'залишили'::text,'залишили'::text,'залишають'::text,'Слухай, вона сказала мені, що люди залишили сміття по всьому парку ще до її приходу.'::text),
(398427,44270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que la gente ... basura por todo el parque antes de que ella llegara.'::text,'había dejado'::text,'ha dejado'::text,'deja'::text,'Escucha, me dijo que la gente había dejado basura por todo el parque antes de que ella llegara.'::text),
(398426,44270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit que les gens ... des déchets partout dans le parc avant qu''elle arrive.'::text,'avaient laissé'::text,'ont laissé'::text,'laissent'::text,'Écoute, elle m''a dit que les gens avaient laissé des déchets partout dans le parc avant qu''elle arrive.'::text),
(398429,44270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o gelmeden önce insanların parkın her yerine çöp ... söyledi.'::text,'bırakmış olduğunu'::text,'bıraktığını'::text,'bıraktığını'::text,'Dinle, o gelmeden önce insanların parkın her yerine çöp bırakmış olduğunu söyledi.'::text),
(398430,44270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy az emberek már az érkezése előtt ... a szemetet az egész parkban.'::text,'otthagyták'::text,'otthagyták'::text,'otthagyják'::text,'Figyelj, azt mondta, hogy az emberek már az érkezése előtt otthagyták a szemetet az egész parkban.'::text),
(398433,44271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend hat ..., den sie aufgesammelt hat, drei ganze Säcke gefüllt.'::text,'der Müll'::text,'Müll'::text,'ein Müll'::text,'Mädel, anscheinend hat der Müll, den sie aufgesammelt hat, drei ganze Säcke gefüllt.'::text),
(398437,44271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, ..., яке вона зібрала, заповнило три цілі мішки.'::text,'сміття'::text,'сміття'::text,'сміття'::text,'Подруго, кажуть, сміття, яке вона зібрала, заповнило три цілі мішки.'::text),
(398436,44271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, por lo visto ... que recogió llenó tres bolsas enteras.'::text,'la basura'::text,'basura'::text,'una basura'::text,'Tía, por lo visto la basura que recogió llenó tres bolsas enteras.'::text),
(398435,44271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ... qu''elle a ramassés ont rempli trois sacs entiers.'::text,'les déchets'::text,'des déchets'::text,'un déchet'::text,'Meuf, apparemment les déchets qu''elle a ramassés ont rempli trois sacs entiers.'::text),
(398438,44271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya topladığı ... tam üç torbayı doldurmuş.'::text,'çöp'::text,'çöp'::text,'bir çöp'::text,'Kızım, güya topladığı çöp tam üç torbayı doldurmuş.'::text),
(398439,44271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ..., amit összeszedett, három teli zsákot töltött meg.'::text,'a szemét'::text,'szemét'::text,'egy szemét'::text,'Csajszi, állítólag a szemét, amit összeszedett, három teli zsákot töltött meg.'::text),
(398451,44273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du wusstest, dass du bis Mittag den ganzen Müll von diesem Rasen ..., und ehrlich, du hast es geschafft.'::text,'räumen würdest'::text,'räumen wirst'::text,'räumst'::text,'Du wusstest, dass du bis Mittag den ganzen Müll von diesem Rasen räumen würdest, und ehrlich, du hast es geschafft.'::text),
(398455,44273,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти знала, що до обіду ... все сміття з цієї трави, і чесно, ти це зробила.'::text,'прибереш'::text,'прибереш'::text,'прибираєш'::text,'Ти знала, що до обіду прибереш все сміття з цієї трави, і чесно, ти це зробила.'::text),
(398454,44273,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabías que ... toda la basura de este césped antes del mediodía, y sinceramente, lo hiciste.'::text,'quitarías'::text,'quitarás'::text,'estás quitando'::text,'Sabías que quitarías toda la basura de este césped antes del mediodía, y sinceramente, lo hiciste.'::text),
(398453,44273,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu savais que tu ... tous les déchets de cette pelouse avant midi, et franchement, tu l''as fait.'::text,'enlèverais'::text,'enlèveras'::text,'enlèves'::text,'Tu savais que tu enlèverais tous les déchets de cette pelouse avant midi, et franchement, tu l''as fait.'::text),
(398456,44273,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar bu çimdeki bütün çöpleri ... biliyordun ve açıkçası temizledin de.'::text,'temizleyeceğini'::text,'temizleyeceğini'::text,'temizlediğini'::text,'Öğlene kadar bu çimdeki bütün çöpleri temizleyeceğini biliyordun ve açıkçası temizledin de.'::text),
(398457,44273,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudtad, hogy délre ... az összes szemetet erről a fűről, és őszintén, sikerült.'::text,'eltakarítod'::text,'el fogod takarítani'::text,'takarítod'::text,'Tudtad, hogy délre eltakarítod az összes szemetet erről a fűről, és őszintén, sikerült.'::text),
(398460,44274,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... gerade Müll von diesem Rasen wie ein echter Profi.'::text,'sammelst'::text,'sammelst'::text,'sammelst'::text,'Ehrlich gesagt, du sammelst gerade Müll von diesem Rasen wie ein echter Profi.'::text),
(398464,44274,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти зараз ... сміття з цієї трави, як справжня профі.'::text,'збираєш'::text,'збираєш'::text,'зібрала'::text,'Не буду брехати, ти зараз збираєш сміття з цієї трави, як справжня профі.'::text),
(398463,44274,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ahora mismo ... basura de este césped como toda una pro.'::text,'estás recogiendo'::text,'recoges'::text,'has recogido'::text,'No voy a mentir, ahora mismo estás recogiendo basura de este césped como toda una pro.'::text),
(398462,44274,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, là tu ... les déchets sur cette pelouse comme une vraie pro.'::text,'ramasses'::text,'ramasses'::text,'as ramassé'::text,'Je vais pas mentir, là tu ramasses les déchets sur cette pelouse comme une vraie pro.'::text),
(398465,44274,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, şu an bu çimden tam bir profesyonel gibi çöp ...'::text,'topluyorsun'::text,'toplarsın'::text,'topladın'::text,'Yalan yok, şu an bu çimden tam bir profesyonel gibi çöp topluyorsun.'::text),
(398466,44274,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, most úgy ... a szemetet erről a fűről, mint egy igazi profi.'::text,'szeded'::text,'szeded'::text,'szedted'::text,'Nem hazudok, most úgy szeded a szemetet erről a fűről, mint egy igazi profi.'::text),
(398469,44275,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... stundenlang Müll, bevor der Rasen sauber war. Ein entspannter Tag, natürlich.'::text,'sammelten'::text,'sammeln'::text,'sammeln'::text,'Sie sammelten stundenlang Müll, bevor der Rasen sauber war. Ein entspannter Tag, natürlich.'::text),
(398473,44275,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... сміття годинами, поки трава не стала чистою. Розслаблений день, звісно.'::text,'збирали'::text,'збирають'::text,'збирають'::text,'Вони збирали сміття годинами, поки трава не стала чистою. Розслаблений день, звісно.'::text),
(398472,44275,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... basura durante horas antes de que el césped quedara limpio. Un día relajante, obviamente.'::text,'Habían estado recogiendo'::text,'Han estado recogiendo'::text,'Están recogiendo'::text,'Habían estado recogiendo basura durante horas antes de que el césped quedara limpio. Un día relajante, obviamente.'::text),
(398471,44275,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ... des déchets pendant des heures avant que la pelouse soit propre. Une journée reposante, évidemment.'::text,'avaient ramassé'::text,'ont ramassé'::text,'ramassent'::text,'Elles avaient ramassé des déchets pendant des heures avant que la pelouse soit propre. Une journée reposante, évidemment.'::text),
(398474,44275,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çimler temizlenene kadar saatlerce çöp ...; rahatlatıcı bir gün, belli ki.'::text,'toplamışlardı'::text,'topluyorlar'::text,'topluyorlar'::text,'Çimler temizlenene kadar saatlerce çöp toplamışlardı; rahatlatıcı bir gün, belli ki.'::text),
(398475,44275,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órákig ... a szemetet, mire tiszta lett a fű. Pihentető nap, nyilván.'::text,'szedték'::text,'szedik'::text,'szedik'::text,'Órákig szedték a szemetet, mire tiszta lett a fű. Pihentető nap, nyilván.'::text),
(398478,44276,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... sie jedes Stück Müll im Park. Eine kleine Aufgabe, klar.'::text,'beseitigen'::text,'beseitigen'::text,'beseitigen'::text,'Bis Sonnenuntergang beseitigen sie jedes Stück Müll im Park. Eine kleine Aufgabe, klar.'::text),
(398482,44276,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця вони ... кожен шматочок сміття в парку. Невелике завдання, звісно.'::text,'зберуть'::text,'зберуть'::text,'збирають'::text,'До заходу сонця вони зберуть кожен шматочок сміття в парку. Невелике завдання, звісно.'::text),
(398481,44276,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, ... cada trozo de basura del parque. Una tarea pequeña, está claro.'::text,'habrán recogido'::text,'recogerán'::text,'están recogiendo'::text,'Para el atardecer, habrán recogido cada trozo de basura del parque. Una tarea pequeña, está claro.'::text),
(398480,44276,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, elles ... chaque déchet du parc. Une petite tâche, clairement.'::text,'auront ramassé'::text,'ramasseront'::text,'ramassent'::text,'D''ici le coucher du soleil, elles auront ramassé chaque déchet du parc. Une petite tâche, clairement.'::text),
(398483,44276,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar parktaki her bir çöpü ...; küçük bir iş, belli ki.'::text,'toplamış olacaklar'::text,'toplayacaklar'::text,'topluyorlar'::text,'Gün batımına kadar parktaki her bir çöpü toplamış olacaklar; küçük bir iş, belli ki.'::text),
(398484,44276,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére ... a park minden egyes szemetét. Apró feladat, nyilván.'::text,'összeszedik'::text,'össze fogják szedni'::text,'szedik'::text,'Naplementére összeszedik a park minden egyes szemetét. Apró feladat, nyilván.'::text),
(371469,41275,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte ... gerade Urkunden entlang der Reihe, als eine Frau zu weinen begann.'::text,'verteilte'::text,'verteilte'::text,'verteilte'::text,'Der Beamte verteilte gerade Urkunden entlang der Reihe, als eine Frau zu weinen begann.'::text),
(371473,41275,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Посадовець ... посвідчення вздовж ряду, коли одна жінка розплакалася.'::text,'роздавав'::text,'роздав'::text,'роздав'::text,'Посадовець роздавав посвідчення вздовж ряду, коли одна жінка розплакалася.'::text),
(371472,41275,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El funcionario ... certificados a lo largo de la fila cuando una mujer se echó a llorar.'::text,'estaba repartiendo'::text,'repartió'::text,'ha repartido'::text,'El funcionario estaba repartiendo certificados a lo largo de la fila cuando una mujer se echó a llorar.'::text),
(371471,41275,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fonctionnaire ... des certificats le long de la rangée quand une femme s''est mise à pleurer.'::text,'distribuait'::text,'a distribué'::text,'a distribué'::text,'Le fonctionnaire distribuait des certificats le long de la rangée quand une femme s''est mise à pleurer.'::text),
(371474,41275,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kadın ağlamaya başladığında yetkili sıra boyunca belgeleri ...'::text,'dağıtıyordu'::text,'dağıttı'::text,'dağıttı'::text,'Bir kadın ağlamaya başladığında yetkili sıra boyunca belgeleri dağıtıyordu.'::text),
(371475,41275,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tisztviselő épp ... az okleveleket a sor mentén, amikor egy nő sírni kezdett.'::text,'osztogatta'::text,'kiosztotta'::text,'kiosztotta'::text,'A tisztviselő épp osztogatta az okleveleket a sor mentén, amikor egy nő sírni kezdett.'::text),
(371478,41276,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, dieser Beamte ... seit zwanzig Jahren Urkunden an neue Bürger.'::text,'verteilt'::text,'verteilt'::text,'verteilt'::text,'Rate mal, ich hab gehört, dieser Beamte verteilt seit zwanzig Jahren Urkunden an neue Bürger.'::text),
(371482,41276,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, я чула, що той посадовець ... посвідчення новим громадянам уже двадцять років.'::text,'роздає'::text,'роздає'::text,'роздає'::text,'Вгадай що, я чула, що той посадовець роздає посвідчення новим громадянам уже двадцять років.'::text),
(371481,41276,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, he oído que ese funcionario ... certificados a los nuevos ciudadanos desde hace veinte años.'::text,'reparte'::text,'está repartiendo'::text,'reparte'::text,'Adivina qué, he oído que ese funcionario reparte certificados a los nuevos ciudadanos desde hace veinte años.'::text),
(371480,41276,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu dire que ce fonctionnaire ... des certificats aux nouveaux citoyens depuis vingt ans.'::text,'distribue'::text,'distribue'::text,'distribue'::text,'Devine quoi, j''ai entendu dire que ce fonctionnaire distribue des certificats aux nouveaux citoyens depuis vingt ans.'::text),
(371483,41276,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, o yetkilinin yirmi yıldır yeni vatandaşlara belge ... duydum.'::text,'dağıttığını'::text,'dağıttığını'::text,'dağıttığını'::text,'Bil bakalım, o yetkilinin yirmi yıldır yeni vatandaşlara belge dağıttığını duydum.'::text),
(371484,41276,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy az a tisztviselő húsz éve ... az okleveleket az új állampolgároknak.'::text,'osztja'::text,'osztja'::text,'osztja'::text,'Képzeld, azt hallottam, hogy az a tisztviselő húsz éve osztja az okleveleket az új állampolgároknak.'::text),
(371487,41277,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, sie hat gesagt, sie hat in der Sekunde geweint, als der Beamte ihr die Urkunde ...'::text,'überreichte'::text,'überreichte'::text,'überreicht hat'::text,'Also, sie hat gesagt, sie hat in der Sekunde geweint, als der Beamte ihr die Urkunde überreichte.'::text),
(371491,41277,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, вона сказала, що розплакалася тієї секунди, коли посадовець ... їй посвідчення.'::text,'вручив'::text,'вручав'::text,'вручив'::text,'Отже, вона сказала, що розплакалася тієї секунди, коли посадовець вручив їй посвідчення.'::text),
(371490,41277,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, dijo que se puso a llorar en el segundo en que el funcionario le ... el certificado.'::text,'dio'::text,'estaba dando'::text,'ha dado'::text,'Vale, dijo que se puso a llorar en el segundo en que el funcionario le dio el certificado.'::text),
(371489,41277,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, elle a dit qu''elle a pleuré à la seconde où le fonctionnaire lui ... le certificat.'::text,'a tendu'::text,'tendait'::text,'a tendu'::text,'Bon, elle a dit qu''elle a pleuré à la seconde où le fonctionnaire lui a tendu le certificat.'::text),
(371492,41277,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şöyle ki, yetkili belgeyi ona ... anda ağladığını söyledi.'::text,'verdiği'::text,'veriyor olduğu'::text,'vermiş olduğu'::text,'Şöyle ki, yetkili belgeyi ona verdiği anda ağladığını söyledi.'::text),
(371493,41277,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, abban a pillanatban elsírta magát, amikor a tisztviselő ... neki az oklevelet.'::text,'átadta'::text,'épp átadta'::text,'átadta'::text,'Szóval azt mondta, abban a pillanatban elsírta magát, amikor a tisztviselő átadta neki az oklevelet.'::text),
(371496,41278,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... den ganzen Vormittag Urkunden und bist immer noch der netteste Beamte hier.'::text,'verteilst'::text,'verteiltest'::text,'verteilst'::text,'Ehrlich, du verteilst den ganzen Vormittag Urkunden und bist immer noch der netteste Beamte hier.'::text),
(371500,41278,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти весь ранок ... посвідчення, і ти досі найдобріший посадовець тут.'::text,'роздаєш'::text,'роздав'::text,'роздаєш'::text,'Чесно, ти весь ранок роздаєш посвідчення, і ти досі найдобріший посадовець тут.'::text),
(371499,41278,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... certificados toda la mañana y sigues siendo el funcionario más amable de aquí.'::text,'llevas repartiendo'::text,'repartiste'::text,'estás repartiendo'::text,'Sinceramente, llevas repartiendo certificados toda la mañana y sigues siendo el funcionario más amable de aquí.'::text),
(371498,41278,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... des certificats depuis ce matin, et tu es toujours le fonctionnaire le plus gentil ici.'::text,'distribues'::text,'as distribué'::text,'es en train de distribuer'::text,'Franchement, tu distribues des certificats depuis ce matin, et tu es toujours le fonctionnaire le plus gentil ici.'::text),
(371501,41278,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bütün sabah belge ... ve hâlâ buradaki en nazik yetkilisin.'::text,'dağıtıyorsun'::text,'dağıttın'::text,'dağıtıyorsun'::text,'Açıkçası bütün sabah belge dağıtıyorsun ve hâlâ buradaki en nazik yetkilisin.'::text),
(371502,41278,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egész délelőtt ... az okleveleket, és még mindig te vagy itt a legkedvesebb tisztviselő.'::text,'osztod'::text,'kiosztottad'::text,'osztod'::text,'Őszintén, egész délelőtt osztod az okleveleket, és még mindig te vagy itt a legkedvesebb tisztviselő.'::text),
(371514,41280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Beamte jede Urkunde mit einer Schleife ..., wird niemand weinen, natürlich.'::text,'überreicht'::text,'überreichen wird'::text,'überreichte'::text,'Wenn der Beamte jede Urkunde mit einer Schleife überreicht, wird niemand weinen, natürlich.'::text),
(371518,41280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо посадовець ... кожне посвідчення зі стрічкою, ніхто не плакатиме, очевидно.'::text,'роздаватиме'::text,'роздаватиме'::text,'роздав'::text,'Якщо посадовець роздаватиме кожне посвідчення зі стрічкою, ніхто не плакатиме, очевидно.'::text),
(371517,41280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el funcionario ... cada certificado con un lazo, nadie llorará, obviamente.'::text,'entrega'::text,'entregará'::text,'entregó'::text,'Si el funcionario entrega cada certificado con un lazo, nadie llorará, obviamente.'::text),
(371516,41280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le fonctionnaire ... chaque certificat avec un ruban, personne ne pleurera, évidemment.'::text,'remet'::text,'remettra'::text,'remettait'::text,'Si le fonctionnaire remet chaque certificat avec un ruban, personne ne pleurera, évidemment.'::text),
(371519,41280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetkili her belgeyi kurdeleyle ..., kimse ağlamayacak, belli ki.'::text,'verirse'::text,'verecekse'::text,'verdiyse'::text,'Yetkili her belgeyi kurdeleyle verirse, kimse ağlamayacak, belli ki.'::text),
(371520,41280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tisztviselő minden oklevelet szalaggal ... át, senki sem fog sírni, nyilván.'::text,'ad'::text,'fog adni'::text,'adott'::text,'Ha a tisztviselő minden oklevelet szalaggal ad át, senki sem fog sírni, nyilván.'::text),
(371523,41281,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Beamte eine noch schwerere Kette trüge, ... sich die Zeremonie noch entspannter anfühlen, klar.'::text,'würde'::text,'wird'::text,'würde'::text,'Wenn der Beamte eine noch schwerere Kette trüge, würde sich die Zeremonie noch entspannter anfühlen, klar.'::text),
(371527,41281,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби посадовець носив ще важчий ланцюг, церемонія ... ще розслабленішою, ясна річ.'::text,'здавалася б'::text,'здаватиметься'::text,'здавалася'::text,'Якби посадовець носив ще важчий ланцюг, церемонія здавалася б ще розслабленішою, ясна річ.'::text),
(371526,41281,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el funcionario llevara una cadena aún más pesada, la ceremonia ... todavía más relajada, está claro.'::text,'parecería'::text,'parecerá'::text,'pareció'::text,'Si el funcionario llevara una cadena aún más pesada, la ceremonia parecería todavía más relajada, está claro.'::text),
(371525,41281,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le fonctionnaire portait une chaîne encore plus lourde, la cérémonie ... encore plus détendue, clairement.'::text,'semblerait'::text,'semblera'::text,'semblait'::text,'Si le fonctionnaire portait une chaîne encore plus lourde, la cérémonie semblerait encore plus détendue, clairement.'::text),
(371528,41281,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetkili daha da ağır bir zincir taksaydı tören daha da rahat ..., belli ki.'::text,'hissettirirdi'::text,'hissettirecek'::text,'hissettirdi'::text,'Yetkili daha da ağır bir zincir taksaydı tören daha da rahat hissettirirdi, belli ki.'::text),
(371529,41281,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tisztviselő még nehezebb láncot viselne, a ceremónia még lazábbnak ..., nyilván.'::text,'tűnne'::text,'fog tűnni'::text,'tűnt'::text,'Ha a tisztviselő még nehezebb láncot viselne, a ceremónia még lazábbnak tűnne, nyilván.'::text),
(371532,41282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Beamte, ... ihr die Urkunde gegeben hat, hat ihr lowkey das ganze Jahr gerettet.'::text,'der'::text,'was'::text,'dessen'::text,'Yo, der Beamte, der ihr die Urkunde gegeben hat, hat ihr lowkey das ganze Jahr gerettet.'::text),
(371536,41282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, посадовець, ... вручив їй посвідчення, реально прикрасив їй увесь рік.'::text,'який'::text,'що'::text,'чий'::text,'Йо, посадовець, який вручив їй посвідчення, реально прикрасив їй увесь рік.'::text),
(371535,41282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, el funcionario ... le dio el certificado le alegró el año entero, en serio.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Oye, el funcionario que le dio el certificado le alegró el año entero, en serio.'::text),
(371534,41282,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, le fonctionnaire ... lui a remis le certificat a carrément illuminé son année.'::text,'qui'::text,'lequel'::text,'dont'::text,'Wesh, le fonctionnaire qui lui a remis le certificat a carrément illuminé son année.'::text),
(371537,41282,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ona belgeyi ... veren yetkili resmen yılını güzelleştirdi.'::text,''::text,NULL::text,NULL::text,'Kanka, ona belgeyi veren yetkili resmen yılını güzelleştirdi.'::text),
(371538,41282,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, a tisztviselő, ... átadta neki az oklevelet, lowkey bearanyozta az egész évét.'::text,'aki'::text,'ami'::text,'akinek'::text,'Figyu, a tisztviselő, aki átadta neki az oklevelet, lowkey bearanyozta az egész évét.'::text),
(371550,41284,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte gab jedem Bürger eine Urkunde, ... sie den Eid abgelegt hatten.'::text,'sobald'::text,'trotz'::text,'es sei denn'::text,'Der Beamte gab jedem Bürger eine Urkunde, sobald sie den Eid abgelegt hatten.'::text),
(371554,41284,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Посадовець дав кожному громадянину посвідчення, ... вони склали присягу.'::text,'щойно'::text,'попри те що'::text,'хіба що'::text,'Посадовець дав кожному громадянину посвідчення, щойно вони склали присягу.'::text),
(371553,41284,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El funcionario dio a cada ciudadano un certificado ... habían prestado juramento.'::text,'una vez que'::text,'a pesar de que'::text,'a menos que'::text,'El funcionario dio a cada ciudadano un certificado una vez que habían prestado juramento.'::text),
(371552,41284,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fonctionnaire a remis un certificat à chaque citoyen ... ils avaient prêté serment.'::text,'une fois qu'''::text,'malgré'::text,'à moins qu'''::text,'Le fonctionnaire a remis un certificat à chaque citoyen une fois qu'' ils avaient prêté serment.'::text),
(371555,41284,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetkili, vatandaşlar yemin ... her birine bir belge verdi.'::text,'eder etmez'::text,'etmesine rağmen'::text,'etmedikçe'::text,'Yetkili, vatandaşlar yemin eder etmez her birine bir belge verdi.'::text),
(371556,41284,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tisztviselő minden állampolgárnak átadott egy oklevelet, ... letették az esküt.'::text,'amint'::text,'annak ellenére, hogy'::text,'hacsak nem'::text,'A tisztviselő minden állampolgárnak átadott egy oklevelet, amint letették az esküt.'::text),
(371559,41285,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Zeremonie ... der Beamte jede Urkunde in der Reihe.'::text,'verteilt'::text,'verteilt'::text,'verteilt'::text,'Bis zum Ende der Zeremonie verteilt der Beamte jede Urkunde in der Reihe.'::text),
(371563,41285,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця церемонії посадовець ... кожне посвідчення в ряду.'::text,'роздасть'::text,'роздасть'::text,'роздає'::text,'До кінця церемонії посадовець роздасть кожне посвідчення в ряду.'::text),
(371562,41285,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la ceremonia, el funcionario ... todos los certificados de la fila.'::text,'habrá repartido'::text,'repartirá'::text,'reparte'::text,'Para el final de la ceremonia, el funcionario habrá repartido todos los certificados de la fila.'::text),
(371561,41285,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la cérémonie, le fonctionnaire ... chaque certificat de la rangée.'::text,'aura distribué'::text,'distribuera'::text,'distribue'::text,'D''ici la fin de la cérémonie, le fonctionnaire aura distribué chaque certificat de la rangée.'::text),
(371564,41285,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tören bitene kadar yetkili sıradaki her belgeyi ...'::text,'dağıtmış olacak'::text,'dağıtacak'::text,'dağıtıyor'::text,'Tören bitene kadar yetkili sıradaki her belgeyi dağıtmış olacak.'::text),
(371565,41285,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ceremónia végére a tisztviselő ... a sor minden oklevelét.'::text,'kiosztja'::text,'ki fogja osztani'::text,'osztja'::text,'A ceremónia végére a tisztviselő kiosztja a sor minden oklevelét.'::text),
(340455,37829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... sie gerade den Boden, als sie ihr altes Tagebuch fand.'::text,'entrümpelte'::text,'entrümpelte'::text,'entrümpelte'::text,'Bestie, anscheinend entrümpelte sie gerade den Boden, als sie ihr altes Tagebuch fand.'::text),
(340459,37829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, кажуть, вона ... підлогу, коли знайшла свій старий щоденник.'::text,'розчищала'::text,'розчистила'::text,'розчистила'::text,'Бесті, кажуть, вона розчищала підлогу, коли знайшла свій старий щоденник.'::text),
(340458,37829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, por lo visto ... el suelo cuando encontró su antiguo diario.'::text,'estaba despejando'::text,'despejó'::text,'ha despejado'::text,'Bestie, por lo visto estaba despejando el suelo cuando encontró su antiguo diario.'::text),
(340457,37829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment elle ... le sol quand elle a trouvé son vieux journal intime.'::text,'débarrassait'::text,'a débarrassé'::text,'a débarrassé'::text,'Bestie, apparemment elle débarrassait le sol quand elle a trouvé son vieux journal intime.'::text),
(340460,37829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya eski günlüğünü bulduğunda yeri ...'::text,'toparlıyordu'::text,'topladı'::text,'topladı'::text,'Kanka, güya eski günlüğünü bulduğunda yeri toparlıyordu.'::text),
(340461,37829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, állítólag épp ... a padlót, amikor megtalálta a régi naplóját.'::text,'takarította'::text,'kitakarította'::text,'kitakarította'::text,'Bestie, állítólag épp takarította a padlót, amikor megtalálta a régi naplóját.'::text),
(340464,37830,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn du alle Klamotten vom Boden ..., sieht das Zimmer doppelt so groß aus, echt.'::text,'räumst'::text,'geräumt hast'::text,'räumen wirst'::text,'Yo, wenn du alle Klamotten vom Boden räumst, sieht das Zimmer doppelt so groß aus, echt.'::text),
(340468,37830,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якщо ти ... весь одяг з підлоги, кімната виглядає вдвічі більшою, реально.'::text,'прибираєш'::text,'прибрав'::text,'прибереш'::text,'Йо, якщо ти прибираєш весь одяг з підлоги, кімната виглядає вдвічі більшою, реально.'::text),
(340467,37830,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, si ... toda la ropa del suelo, la habitación parece el doble de grande, en serio.'::text,'quitas'::text,'quitaste'::text,'quitarás'::text,'Oye, si quitas toda la ropa del suelo, la habitación parece el doble de grande, en serio.'::text),
(340466,37830,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si tu ... tous les vêtements du sol, la chambre paraît deux fois plus grande, sérieux.'::text,'enlèves'::text,'as enlevé'::text,'enlèveras'::text,'Yo, si tu enlèves tous les vêtements du sol, la chambre paraît deux fois plus grande, sérieux.'::text),
(340469,37830,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yerdeki bütün kıyafetleri ..., oda iki kat büyük görünüyor, cidden.'::text,'kaldırırsan'::text,'kaldırdıysan'::text,'kaldıracaksan'::text,'Kanka, yerdeki bütün kıyafetleri kaldırırsan, oda iki kat büyük görünüyor, cidden.'::text),
(340470,37830,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ha minden ruhát ... a padlóról, a szoba kétszer akkorának tűnik, komolyan.'::text,'elpakolsz'::text,'elpakoltál'::text,'el fogsz pakolni'::text,'Figyu, ha minden ruhát elpakolsz a padlóról, a szoba kétszer akkorának tűnik, komolyan.'::text),
(340473,37831,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie hat einfach so die ganze Wohnung an einem Tag leergeräumt, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Yo, sie hat einfach so die ganze Wohnung an einem Tag leergeräumt, oder?'::text),
(340477,37831,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона непомітно розчистила всю квартиру за один день, ...?'::text,'еге ж'::text,'еге ж'::text,'еге ж'::text,'Йо, вона непомітно розчистила всю квартиру за один день, еге ж?'::text),
(340476,37831,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, despejó todo el piso en un día como si nada, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Oye, despejó todo el piso en un día como si nada, ¿verdad?'::text),
(340475,37831,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle a vidé tout l''appart en une journée, tranquille, ... ?'::text,'non'::text,'non'::text,'non'::text,'Yo, elle a vidé tout l''appart en une journée, tranquille, non ?'::text),
(340478,37831,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün evi bir günde sessiz sedasız toparladı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Kanka, bütün evi bir günde sessiz sedasız toparladı, değil mi?'::text),
(340479,37831,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, simán kipakolta az egész lakást egy nap alatt, ...?'::text,'nem'::text,'nem'::text,'nem'::text,'Figyu, simán kipakolta az egész lakást egy nap alatt, nem?'::text),
(340491,37833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gab zu, zu viel Zeit mit dem Ausräumen der Wohnung ...'::text,'verbracht zu haben'::text,'zu verbringen'::text,'verbrachte'::text,'Sie gab zu, zu viel Zeit mit dem Ausräumen der Wohnung verbracht zu haben.'::text),
(340495,37833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона визнала, що ... забагато часу на розчищення квартири.'::text,'витратила'::text,'витратити'::text,'витратила'::text,'Вона визнала, що витратила забагато часу на розчищення квартири.'::text),
(340494,37833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió ... demasiado tiempo despejando el piso.'::text,'haber pasado'::text,'pasar'::text,'pasó'::text,'Admitió haber pasado demasiado tiempo despejando el piso.'::text),
(340493,37833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a admis ... trop de temps à débarrasser l''appartement.'::text,'avoir passé'::text,'passer'::text,'a passé'::text,'Elle a admis avoir passé trop de temps à débarrasser l''appartement.'::text),
(340496,37833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evi boşaltmaya çok fazla zaman ... itiraf etti.'::text,'harcadığını'::text,'harcamayı'::text,'harcadı'::text,'Evi boşaltmaya çok fazla zaman harcadığını itiraf etti.'::text),
(340497,37833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy túl sok időt ... a lakás kipakolásával.'::text,'töltött'::text,'tölteni'::text,'töltött'::text,'Beismerte, hogy túl sok időt töltött a lakás kipakolásával.'::text),
(340500,37834,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Boden ist jetzt leer; das Subjekt ... jede Kiste und jedes Kleidungsstück weggeräumt haben, vermutlich von Hand.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Der Boden ist jetzt leer; das Subjekt muss jede Kiste und jedes Kleidungsstück weggeräumt haben, vermutlich von Hand.'::text),
(340504,37834,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підлога тепер порожня; суб''єкт ... кожну коробку й річ одягу, імовірно, вручну.'::text,'мабуть, прибрав'::text,'мав прибрати'::text,'не міг прибрати'::text,'Підлога тепер порожня; суб''єкт мабуть, прибрав кожну коробку й річ одягу, імовірно, вручну.'::text),
(340503,37834,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El suelo está ahora despejado; el sujeto ... cada caja y cada prenda, presumiblemente a mano.'::text,'debió de quitar'::text,'debería haber quitado'::text,'no pudo quitar'::text,'El suelo está ahora despejado; el sujeto debió de quitar cada caja y cada prenda, presumiblemente a mano.'::text),
(340502,37834,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sol est désormais nu ; le sujet ... chaque carton et chaque vêtement, vraisemblablement à la main.'::text,'a dû enlever'::text,'aurait dû enlever'::text,'ne peut pas avoir enlevé'::text,'Le sol est désormais nu ; le sujet a dû enlever chaque carton et chaque vêtement, vraisemblablement à la main.'::text),
(340505,37834,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zemin artık boş; denek her kutuyu ve giysiyi, muhtemelen elle, ...'::text,'kaldırmış olmalı'::text,'kaldırmalıydı'::text,'kaldırmış olamaz'::text,'Zemin artık boş; denek her kutuyu ve giysiyi, muhtemelen elle, kaldırmış olmalı.'::text),
(340506,37834,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A padló most üres; az alany ... minden dobozt és ruhadarabot, feltehetően kézzel.'::text,'biztosan elpakolta'::text,'el kellett volna pakolnia'::text,'nem pakolhatta el'::text,'A padló most üres; az alany biztosan elpakolta minden dobozt és ruhadarabot, feltehetően kézzel.'::text),
(340509,37835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hätte eine Freundin die Kisten ... lassen können, aber sie hat alles selbst gemacht.'::text,'wegräumen'::text,'wegräumen'::text,'weggeräumt'::text,'Sie hätte eine Freundin die Kisten wegräumen lassen können, aber sie hat alles selbst gemacht.'::text),
(340513,37835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона могла б попросити подругу ... коробки, але все зробила сама.'::text,'прибрати'::text,'прибрати'::text,'прибрала'::text,'Вона могла б попросити подругу прибрати коробки, але все зробила сама.'::text),
(340512,37835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Podría haber hecho que una amiga ... las cajas, pero lo hizo todo ella sola.'::text,'quitara'::text,'quitar'::text,'quitó'::text,'Podría haber hecho que una amiga quitara las cajas, pero lo hizo todo ella sola.'::text),
(340511,37835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aurait pu faire ... les cartons par une amie, mais elle a tout fait elle-même.'::text,'débarrasser'::text,'débarrasser'::text,'débarrassé'::text,'Elle aurait pu faire débarrasser les cartons par une amie, mais elle a tout fait elle-même.'::text),
(340514,37835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kutuları bir arkadaşına ..., ama hepsini kendisi yaptı.'::text,'kaldırtabilirdi'::text,'kaldırtabilirdi'::text,'kaldırdı'::text,'Kutuları bir arkadaşına kaldırtabilirdi, ama hepsini kendisi yaptı.'::text),
(340515,37835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megkérhette volna egy barátnőjét, hogy ... a dobozokat, de mindent maga csinált.'::text,'elpakolja'::text,'elpakolja'::text,'elpakolta'::text,'Megkérhette volna egy barátnőjét, hogy elpakolja a dobozokat, de mindent maga csinált.'::text),
(340518,37836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, dass sie die Wohnung früher ..., bevor es so voll wurde.'::text,'ausgeräumt hätte'::text,'ausgeräumt hat'::text,'ausräumen würde'::text,'Sie wünscht sich, dass sie die Wohnung früher ausgeräumt hätte, bevor es so voll wurde.'::text),
(340522,37836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хотіла б, щоб ... квартиру раніше, поки там не стало так тісно.'::text,'розчистила'::text,'розчистила'::text,'розчищала'::text,'Вона хотіла б, щоб розчистила квартиру раніше, поки там не стало так тісно.'::text),
(340521,37836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía ... el piso antes, cuando no estaba tan abarrotado.'::text,'haber despejado'::text,'despejó'::text,'despejaría'::text,'Desearía haber despejado el piso antes, cuando no estaba tan abarrotado.'::text),
(340520,37836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ... l''appartement plus tôt, avant qu''il soit aussi encombré.'::text,'avoir vidé'::text,'vider'::text,'vider'::text,'Elle aimerait avoir vidé l''appartement plus tôt, avant qu''il soit aussi encombré.'::text),
(340523,37836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke evi bu kadar kalabalıklaşmadan önce ... diye düşünüyor.'::text,'boşaltsaydı'::text,'boşalttı'::text,'boşaltsa'::text,'Keşke evi bu kadar kalabalıklaşmadan önce boşaltsaydı diye düşünüyor.'::text),
(340524,37836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak korábban ... a lakást, mielőtt ennyire zsúfolt lett.'::text,'kipakolta volna'::text,'kipakolta'::text,'kipakolná'::text,'Azt kívánja, bárcsak korábban kipakolta volna a lakást, mielőtt ennyire zsúfolt lett.'::text),
(340527,37837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der niedrige Tisch, ... sie zuletzt abgeräumt hat, ist jetzt leer und sauber.'::text,'den'::text,'dessen'::text,'wer'::text,'Der niedrige Tisch, den sie zuletzt abgeräumt hat, ist jetzt leer und sauber.'::text),
(340531,37837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Низький столик, ... вона розчистила останнім, тепер порожній і чистий.'::text,'який'::text,'чий'::text,'хто'::text,'Низький столик, який вона розчистила останнім, тепер порожній і чистий.'::text),
(340530,37837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mesa baja, ... despejó la última, ahora está vacía y limpia.'::text,'que'::text,'cuya'::text,'quien'::text,'La mesa baja, que despejó la última, ahora está vacía y limpia.'::text),
(340529,37837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La table basse, ... elle a débarrassée en dernier, est maintenant vide et propre.'::text,'qu'''::text,'dont'::text,'qui'::text,'La table basse, qu'' elle a débarrassée en dernier, est maintenant vide et propre.'::text),
(340532,37837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En son ... boşalttığı alçak masa artık boş ve temiz.'::text,''::text,NULL::text,NULL::text,'En son boşalttığı alçak masa artık boş ve temiz.'::text),
(340533,37837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alacsony asztal, ... utoljára pakolt le, most üres és tiszta.'::text,'amelyet'::text,'amelynek'::text,'aki'::text,'Az alacsony asztal, amelyet utoljára pakolt le, most üres és tiszta.'::text),
(340545,37839,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie schwört, dass sie bis Sonntag jedes Zimmer in der Wohnung ...'::text,'ausgeräumt haben wird'::text,'ausräumen wird'::text,'ausräumt'::text,'Hör zu, sie schwört, dass sie bis Sonntag jedes Zimmer in der Wohnung ausgeräumt haben wird.'::text),
(340549,37839,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона клянеться, що до неділі ... кожну кімнату в квартирі.'::text,'розчистить'::text,'розчистить'::text,'розчищає'::text,'Слухай, вона клянеться, що до неділі розчистить кожну кімнату в квартирі.'::text),
(340548,37839,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, jura que para el domingo ... todas las habitaciones del piso.'::text,'habrá despejado'::text,'despejará'::text,'despeja'::text,'Escucha, jura que para el domingo habrá despejado todas las habitaciones del piso.'::text),
(340547,37839,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle jure que d''ici dimanche elle ... chaque pièce de l''appartement.'::text,'aura vidé'::text,'videra'::text,'vide'::text,'Écoute, elle jure que d''ici dimanche elle aura vidé chaque pièce de l''appartement.'::text),
(340550,37839,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, pazara kadar evdeki her odayı ... yemin ediyor.'::text,'boşaltmış olacağına'::text,'boşaltacağına'::text,'boşalttığına'::text,'Dinle, pazara kadar evdeki her odayı boşaltmış olacağına yemin ediyor.'::text),
(340551,37839,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, esküszik, hogy vasárnapra a lakás minden szobáját ...'::text,'kipakolja'::text,'ki fogja pakolni'::text,'pakolja'::text,'Figyelj, esküszik, hogy vasárnapra a lakás minden szobáját kipakolja.'::text),
(380433,42271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziel erreicht, also beschließt sie, dass sie jetzt sofort eine 20-minütige Pause ...'::text,'macht'::text,'machen wird'::text,'macht'::text,'Ziel erreicht, also beschließt sie, dass sie jetzt sofort eine 20-minütige Pause macht.'::text),
(380437,42271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль досягнуто, тож вона вирішує, що просто зараз ... 20-хвилинну перерву.'::text,'візьме'::text,'братиме'::text,'бере'::text,'Ціль досягнуто, тож вона вирішує, що просто зараз візьме 20-хвилинну перерву.'::text),
(380436,42271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo cumplido, así que decide que ahora mismo ... un descanso de 20 minutos.'::text,'se tomará'::text,'se estará tomando'::text,'se toma'::text,'Objetivo cumplido, así que decide que ahora mismo se tomará un descanso de 20 minutos.'::text),
(380435,42271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif atteint, alors elle décide qu''elle ... une pause de 20 minutes tout de suite.'::text,'va prendre'::text,'sera en train de prendre'::text,'prend'::text,'Objectif atteint, alors elle décide qu''elle va prendre une pause de 20 minutes tout de suite.'::text),
(380438,42271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hedefe ulaşıldı, o yüzden hemen şimdi 20 dakikalık bir mola ... karar veriyor.'::text,'vereceğine'::text,'veriyor olacağına'::text,'verdiğine'::text,'Hedefe ulaşıldı, o yüzden hemen şimdi 20 dakikalık bir mola vereceğine karar veriyor.'::text),
(380439,42271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cél teljesítve, úgyhogy úgy dönt, most azonnal ... egy 20 perces pihenőt.'::text,'tart'::text,'fog tartani'::text,'tart'::text,'Cél teljesítve, úgyhogy úgy dönt, most azonnal tart egy 20 perces pihenőt.'::text),
(380442,42272,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie aufhört zu arbeiten, ... sie eine Pause, denn eine Pause ist Nicht-Arbeiten.'::text,'hat'::text,'hätte'::text,'hatte'::text,'Wenn sie aufhört zu arbeiten, hat sie eine Pause, denn eine Pause ist Nicht-Arbeiten.'::text),
(380446,42272,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона перестане працювати, у неї ... відпочинок, бо відпочинок — це коли не працюєш.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо вона перестане працювати, у неї буде відпочинок, бо відпочинок — це коли не працюєш.'::text),
(380445,42272,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si deja de trabajar, ... un descanso, porque un descanso es no trabajar.'::text,'tendrá'::text,'tendría'::text,'tuvo'::text,'Si deja de trabajar, tendrá un descanso, porque un descanso es no trabajar.'::text),
(380444,42272,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle arrête de travailler, elle ... une pause, parce qu''une pause, c''est ne pas travailler.'::text,'aura'::text,'aurait'::text,'avait'::text,'Si elle arrête de travailler, elle aura une pause, parce qu''une pause, c''est ne pas travailler.'::text),
(380447,42272,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çalışmayı bırakırsa bir molası ..., çünkü mola çalışmamak demek.'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Çalışmayı bırakırsa bir molası olacak, çünkü mola çalışmamak demek.'::text),
(380448,42272,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha abbahagyja a munkát, ... egy kis pihenője, mert a pihenés az, amikor nem dolgozol.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha abbahagyja a munkát, lesz egy kis pihenője, mert a pihenés az, amikor nem dolgozol.'::text),
(380451,42273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tatsächlich, wenn sie nach dem Putzen keine Pause machte, ... ihre Energie viel schneller.'::text,'sänke'::text,'sinkt'::text,'sank'::text,'Tatsächlich, wenn sie nach dem Putzen keine Pause machte, sänke ihre Energie viel schneller.'::text),
(380455,42273,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Насправді, якби вона не відпочивала після прибирання, її енергія ... набагато швидше.'::text,'падала б'::text,'впаде'::text,'впала'::text,'Насправді, якби вона не відпочивала після прибирання, її енергія падала б набагато швидше.'::text),
(380454,42273,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De hecho, si no descansara nada después de limpiar, su energía ... mucho más rápido.'::text,'bajaría'::text,'bajará'::text,'bajó'::text,'De hecho, si no descansara nada después de limpiar, su energía bajaría mucho más rápido.'::text),
(380453,42273,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En fait, si elle ne prenait aucun repos après le ménage, son énergie ... beaucoup plus vite.'::text,'chuterait'::text,'chutera'::text,'a chuté'::text,'En fait, si elle ne prenait aucun repos après le ménage, son énergie chuterait beaucoup plus vite.'::text),
(380456,42273,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aslında temizlikten sonra hiç dinlenmese enerjisi çok daha hızlı ...'::text,'düşerdi'::text,'düşecek'::text,'düştü'::text,'Aslında temizlikten sonra hiç dinlenmese enerjisi çok daha hızlı düşerdi.'::text),
(380457,42273,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valójában, ha takarítás után egyáltalán nem pihenne, az energiája sokkal gyorsabban ...'::text,'csökkenne'::text,'csökken majd'::text,'csökkent'::text,'Valójában, ha takarítás után egyáltalán nem pihenne, az energiája sokkal gyorsabban csökkenne.'::text),
(380460,42274,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sofakissen ... gerade gezogen, bevor sie sich zum Ausruhen hinsetzte.'::text,'wurden'::text,'werden'::text,'zogen'::text,'Die Sofakissen wurden gerade gezogen, bevor sie sich zum Ausruhen hinsetzte.'::text),
(380464,42274,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подушки на дивані ..., перш ніж вона сіла відпочити.'::text,'були вирівняні'::text,'вирівняні'::text,'вирівняли'::text,'Подушки на дивані були вирівняні, перш ніж вона сіла відпочити.'::text),
(380463,42274,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los cojines del sofá ... antes de que se sentara a descansar.'::text,'fueron enderezados'::text,'son enderezados'::text,'enderezaron'::text,'Los cojines del sofá fueron enderezados antes de que se sentara a descansar.'::text),
(380462,42274,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les coussins du canapé ... avant qu''elle s''assoie pour se reposer.'::text,'ont été redressés'::text,'sont redressés'::text,'ont redressé'::text,'Les coussins du canapé ont été redressés avant qu''elle s''assoie pour se reposer.'::text),
(380465,42274,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinlenmek için oturmadan önce kanepe minderleri ...'::text,'düzeltildi'::text,'düzeltiliyor'::text,'düzeltti'::text,'Dinlenmek için oturmadan önce kanepe minderleri düzeltildi.'::text),
(380466,42274,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kanapépárnák ... egyenesre, mielőtt leült pihenni.'::text,'lettek húzva'::text,'vannak húzva'::text,'húzták'::text,'A kanapépárnák lettek húzva egyenesre, mielőtt leült pihenni.'::text),
(380469,42275,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach einer Stunde Putzen ... sie eine lange Pause auf dem Sofa.'::text,'machte'::text,'wurde gemacht'::text,'machend'::text,'Nach einer Stunde Putzen machte sie eine lange Pause auf dem Sofa.'::text),
(380473,42275,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після години прибирання вона ... довгий відпочинок на дивані.'::text,'влаштувала собі'::text,'була влаштована'::text,'влаштовуючи'::text,'Після години прибирання вона влаштувала собі довгий відпочинок на дивані.'::text),
(380472,42275,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tras una hora limpiando, ... un largo descanso en el sofá.'::text,'se tomó'::text,'fue tomada'::text,'tomando'::text,'Tras una hora limpiando, se tomó un largo descanso en el sofá.'::text),
(380471,42275,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après une heure de ménage, elle ... une longue pause sur le canapé.'::text,'a pris'::text,'a été prise'::text,'prenant'::text,'Après une heure de ménage, elle a pris une longue pause sur le canapé.'::text),
(380474,42275,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saatlik temizlikten sonra kanepede uzun bir mola ...'::text,'verdi'::text,'verildi'::text,'vererek'::text,'Bir saatlik temizlikten sonra kanepede uzun bir mola verdi.'::text),
(380475,42275,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy óra takarítás után hosszan ... a kanapén.'::text,'pihent'::text,'pihentetve lett'::text,'pihenve'::text,'Egy óra takarítás után hosszan pihent a kanapén.'::text),
(380478,42276,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat das ganze Zimmer geputzt, also ... sie reif für eine Pause sein.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Sie hat das ganze Zimmer geputzt, also muss sie reif für eine Pause sein.'::text),
(380482,42276,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона прибрала всю кімнату, тож вона ... бути готова до відпочинку.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Вона прибрала всю кімнату, тож вона мусить бути готова до відпочинку.'::text),
(380481,42276,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha limpiado toda la habitación, así que ... estar lista para un descanso.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Ha limpiado toda la habitación, así que debe de estar lista para un descanso.'::text),
(380480,42276,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a nettoyé toute la pièce, alors elle ... être prête pour une pause.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Elle a nettoyé toute la pièce, alors elle doit être prête pour une pause.'::text),
(380483,42276,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün odayı temizledi, yani dinlenmeye hazır ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Bütün odayı temizledi, yani dinlenmeye hazır olmalı.'::text),
(380484,42276,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kitakarította az egész szobát, úgyhogy ... készen áll a pihenésre.'::text,'biztosan'::text,'kizárt, hogy'::text,'nem szabad'::text,'Kitakarította az egész szobát, úgyhogy biztosan készen áll a pihenésre.'::text),
(380487,42277,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Sofa, auf ... sie sich zum Ausruhen setzt, hat jetzt gerade Kissen.'::text,'das'::text,'wen'::text,'dessen'::text,'Das Sofa, auf das sie sich zum Ausruhen setzt, hat jetzt gerade Kissen.'::text),
(380491,42277,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Диван, на ... вона сідає відпочити, тепер має рівні подушки.'::text,'який'::text,'кого'::text,'чий'::text,'Диван, на який вона сідає відпочити, тепер має рівні подушки.'::text),
(380490,42277,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sofá en el ... se sienta a descansar ahora tiene los cojines rectos.'::text,'que'::text,'quien'::text,'cuyo'::text,'El sofá en el que se sienta a descansar ahora tiene los cojines rectos.'::text),
(380489,42277,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canapé sur ... elle s''assoit pour se reposer a maintenant des coussins bien droits.'::text,'lequel'::text,'qui'::text,'dont'::text,'Le canapé sur lequel elle s''assoit pour se reposer a maintenant des coussins bien droits.'::text),
(380492,42277,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinlenmek için ... oturduğu kanepenin minderleri artık düzgün.'::text,''::text,NULL::text,NULL::text,'Dinlenmek için oturduğu kanepenin minderleri artık düzgün.'::text),
(380493,42277,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kanapénak, ... pihenni ül, most egyenesek a párnái.'::text,'amelyre'::text,'akire'::text,'amelynek'::text,'A kanapénak, amelyre pihenni ül, most egyenesek a párnái.'::text),
(380496,42278,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend hat sie mit dem ... aufgehört, um sich auf dem Sofa auszuruhen.'::text,'Putzen'::text,'Putzen'::text,'Putzen'::text,'Hör zu, anscheinend hat sie mit dem Putzen aufgehört, um sich auf dem Sofa auszuruhen.'::text),
(380500,42278,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона перестала ..., щоб відпочити на дивані.'::text,'прибирати'::text,'прибирати'::text,'прибирати'::text,'Слухай, кажуть, вона перестала прибирати, щоб відпочити на дивані.'::text),
(380499,42278,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, por lo visto dejó de ... para descansar en el sofá.'::text,'limpiar'::text,'limpiar'::text,'limpiar'::text,'Escucha, por lo visto dejó de limpiar para descansar en el sofá.'::text),
(380498,42278,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle a arrêté de ... pour se reposer sur le canapé.'::text,'faire le ménage'::text,'faire le ménage'::text,'faire le ménage'::text,'Écoute, apparemment elle a arrêté de faire le ménage pour se reposer sur le canapé.'::text),
(380501,42278,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya kanepede dinlenmek için ... bırakmış.'::text,'temizlik yapmayı'::text,'temizlik yapmayı'::text,'temizlik yapmayı'::text,'Dinle, güya kanepede dinlenmek için temizlik yapmayı bırakmış.'::text),
(380502,42278,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag abbahagyta a ..., hogy pihenjen egyet a kanapén.'::text,'takarítást'::text,'takarítást'::text,'takarítást'::text,'Figyelj, állítólag abbahagyta a takarítást, hogy pihenjen egyet a kanapén.'::text),
(380505,42279,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, sie ... gerade eine Pause auf dem Sofa, kein Putzen mehr.'::text,'macht'::text,'macht'::text,'macht'::text,'Mädel, ich hab gehört, sie macht gerade eine Pause auf dem Sofa, kein Putzen mehr.'::text),
(380509,42279,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що вона просто зараз ... на тому дивані, ніякого більше прибирання.'::text,'відпочиває'::text,'відпочиває'::text,'відпочила'::text,'Подруго, я чула, що вона просто зараз відпочиває на тому дивані, ніякого більше прибирання.'::text),
(380508,42279,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que ahora mismo ... en ese sofá, se acabó limpiar.'::text,'está descansando'::text,'descansa'::text,'ha descansado'::text,'Tía, he oído que ahora mismo está descansando en ese sofá, se acabó limpiar.'::text),
(380507,42279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu dire qu''elle ... sur ce canapé en ce moment, fini le ménage.'::text,'se repose'::text,'se repose'::text,'s''est reposée'::text,'Meuf, j''ai entendu dire qu''elle se repose sur ce canapé en ce moment, fini le ménage.'::text),
(380510,42279,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, şu an o kanepede ... duydum, temizlik falan yok artık.'::text,'dinlendiğini'::text,'dinlendiğini'::text,'dinlenmiş olduğunu'::text,'Kızım, şu an o kanepede dinlendiğini duydum, temizlik falan yok artık.'::text),
(380511,42279,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy épp most ... azon a kanapén, nincs több takarítás.'::text,'pihen'::text,'pihen'::text,'pihent'::text,'Csajszi, azt hallottam, hogy épp most pihen azon a kanapén, nincs több takarítás.'::text),
(350661,38963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fensterputzer ... diese Ausrüstung seit Stunden, und das Glas ist immer noch ein Albtraum!'::text,'benutzt'::text,'benutzt'::text,'benutzt'::text,'Der Fensterputzer benutzt diese Ausrüstung seit Stunden, und das Glas ist immer noch ein Albtraum!'::text),
(350665,38963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мийник вікон ... це обладнання вже кілька годин, а скло досі кошмар!'::text,'використовує'::text,'використовує'::text,'використовує'::text,'Мийник вікон використовує це обладнання вже кілька годин, а скло досі кошмар!'::text),
(350664,38963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El limpiacristales ... ese equipo desde hace horas y el cristal sigue siendo una pesadilla!'::text,'usa'::text,'está usando'::text,'usa'::text,'¡El limpiacristales usa ese equipo desde hace horas y el cristal sigue siendo una pesadilla!'::text),
(350663,38963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le laveur de vitres ... cet équipement depuis des heures, et la vitre est toujours un cauchemar !'::text,'utilise'::text,'est en train d''utiliser'::text,'utilise'::text,'Le laveur de vitres utilise cet équipement depuis des heures, et la vitre est toujours un cauchemar !'::text),
(350666,38963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam temizleyicisi saatlerdir o ekipmanı ... ve cam hâlâ kâbus gibi!'::text,'kullanıyor'::text,'kullanıyor'::text,'kullanır'::text,'Cam temizleyicisi saatlerdir o ekipmanı kullanıyor ve cam hâlâ kâbus gibi!'::text),
(350667,38963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ablakpucoló órák óta ... azt a felszerelést, és az üveg még mindig rémálom!'::text,'használja'::text,'használja'::text,'használja'::text,'Az ablakpucoló órák óta használja azt a felszerelést, és az üveg még mindig rémálom!'::text),
(350670,38964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hing hoch über der Stadt, da ... seine Ausrüstung zu wackeln. Purer Horror!'::text,'begann'::text,'begann'::text,'begann'::text,'Er hing hoch über der Stadt, da begann seine Ausrüstung zu wackeln. Purer Horror!'::text),
(350674,38964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він висів високо над містом, коли його спорядження ... трястися. Чистий жах!'::text,'почало'::text,'починало'::text,'почало'::text,'Він висів високо над містом, коли його спорядження почало трястися. Чистий жах!'::text),
(350673,38964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estaba colgado muy por encima de la ciudad cuando su equipo ... a temblar. ¡Puro terror!'::text,'empezó'::text,'estaba empezando'::text,'ha empezado'::text,'Estaba colgado muy por encima de la ciudad cuando su equipo empezó a temblar. ¡Puro terror!'::text),
(350672,38964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il était suspendu très haut au-dessus de la ville quand son équipement ... à trembler. La terreur pure !'::text,'a commencé'::text,'commençait'::text,'a commencé'::text,'Il était suspendu très haut au-dessus de la ville quand son équipement a commencé à trembler. La terreur pure !'::text),
(350675,38964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehrin çok yukarısında asılıyken ekipmanı sallanmaya ...; tam bir dehşet!'::text,'başladı'::text,'başlıyordu'::text,'başladı'::text,'Şehrin çok yukarısında asılıyken ekipmanı sallanmaya başladı; tam bir dehşet!'::text),
(350676,38964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Magasan lógott a város felett, amikor a felszerelése ... remegni. Tiszta rettegés!'::text,'kezdett'::text,'kezdett'::text,'kezdett'::text,'Magasan lógott a város felett, amikor a felszerelése kezdett remegni. Tiszta rettegés!'::text),
(350679,38965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat ihre Ausrüstung heute schon dreimal ..., und die Arbeitsplatte ist immer noch eine Katastrophe!'::text,'ausgespült'::text,'ausgespült'::text,'ausgespült'::text,'Sie hat ihre Ausrüstung heute schon dreimal ausgespült, und die Arbeitsplatte ist immer noch eine Katastrophe!'::text),
(350683,38965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сьогодні вже тричі ... своє приладдя, а стільниця досі катастрофа!'::text,'сполоснула'::text,'споліскувала'::text,'споліскує'::text,'Вона сьогодні вже тричі сполоснула своє приладдя, а стільниця досі катастрофа!'::text),
(350682,38965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hoy ya ... su equipo tres veces y la encimera sigue siendo un desastre!'::text,'ha enjuagado'::text,'ha estado enjuagando'::text,'está enjuagando'::text,'¡Hoy ya ha enjuagado su equipo tres veces y la encimera sigue siendo un desastre!'::text),
(350681,38965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son équipement trois fois aujourd''hui, et le plan de travail est toujours une catastrophe !'::text,'a rincé'::text,'rince'::text,'est en train de rincer'::text,'Elle a rincé son équipement trois fois aujourd''hui, et le plan de travail est toujours une catastrophe !'::text),
(350684,38965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün ekipmanını üç kez ... ve tezgâh hâlâ felaket!'::text,'duruladı'::text,'duruluyor'::text,'duruluyor'::text,'Bugün ekipmanını üç kez duruladı ve tezgâh hâlâ felaket!'::text),
(350685,38965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma már háromszor ... a felszerelését, és a munkalap még mindig katasztrófa!'::text,'öblítette ki'::text,'öblítgette'::text,'öblíti'::text,'Ma már háromszor öblítette ki a felszerelését, és a munkalap még mindig katasztrófa!'::text),
(350688,38966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Mieter ankamen, ... der Mann seine ganze Ausrüstung schon hinausgetragen.'::text,'hatte'::text,'hat'::text,'hatte'::text,'Als die Mieter ankamen, hatte der Mann seine ganze Ausrüstung schon hinausgetragen.'::text),
(350692,38966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли прийшли орендарі, чоловік уже ... все своє обладнання.'::text,'виніс'::text,'виніс'::text,'виносить'::text,'Коли прийшли орендарі, чоловік уже виніс все своє обладнання.'::text),
(350691,38966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegaron los inquilinos, el hombre ya ... todo su equipo.'::text,'había sacado'::text,'ha sacado'::text,'saca'::text,'Para cuando llegaron los inquilinos, el hombre ya había sacado todo su equipo.'::text),
(350690,38966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les locataires sont arrivés, l''homme ... déjà tout son équipement.'::text,'avait sorti'::text,'a sorti'::text,'sort'::text,'Quand les locataires sont arrivés, l''homme avait sorti déjà tout son équipement.'::text),
(350693,38966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kiracılar geldiğinde adam bütün ekipmanını çoktan dışarı ...'::text,'taşımıştı'::text,'taşıdı'::text,'taşıyor'::text,'Kiracılar geldiğinde adam bütün ekipmanını çoktan dışarı taşımıştı.'::text),
(350694,38966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a bérlők megérkeztek, a férfi már az összes felszerelését ...'::text,'kivitte'::text,'kivitte'::text,'viszi ki'::text,'Mire a bérlők megérkeztek, a férfi már az összes felszerelését kivitte.'::text),
(350697,38967,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Fensterputzer seinen Abzieher fallen lässt, ... er neue Ausrüstung vom Dach.'::text,'braucht'::text,'bräuchte'::text,'brauchte'::text,'Wenn der Fensterputzer seinen Abzieher fallen lässt, braucht er neue Ausrüstung vom Dach.'::text),
(350701,38967,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо мийник вікон упустить свій скребок, йому ... нове обладнання з даху.'::text,'знадобиться'::text,'знадобилося б'::text,'знадобилося'::text,'Якщо мийник вікон упустить свій скребок, йому знадобиться нове обладнання з даху.'::text),
(350700,38967,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el limpiacristales deja caer su rasqueta, ... equipo nuevo desde el tejado.'::text,'necesitará'::text,'necesitaría'::text,'necesitó'::text,'Si el limpiacristales deja caer su rasqueta, necesitará equipo nuevo desde el tejado.'::text),
(350699,38967,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le laveur de vitres fait tomber sa raclette, il ... d''un nouvel équipement depuis le toit.'::text,'aura besoin'::text,'aurait besoin'::text,'avait besoin'::text,'Si le laveur de vitres fait tomber sa raclette, il aura besoin d''un nouvel équipement depuis le toit.'::text),
(350702,38967,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam temizleyicisi çekçeğini düşürürse çatıdan yeni ekipmana ihtiyacı ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Cam temizleyicisi çekçeğini düşürürse çatıdan yeni ekipmana ihtiyacı olacak.'::text),
(350703,38967,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az ablakpucoló leejti a lehúzót, új felszerelésre ... szüksége a tetőről.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha az ablakpucoló leejti a lehúzót, új felszerelésre lesz szüksége a tetőről.'::text),
(350715,38969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schleudermopp und der Rest der Ausrüstung ... gestern ins Büro geliefert.'::text,'wurden'::text,'werden'::text,'lieferten'::text,'Der Schleudermopp und der Rest der Ausrüstung wurden gestern ins Büro geliefert.'::text),
(350719,38969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Швабра з віджимом і решта обладнання ... в офіс учора.'::text,'були доставлені'::text,'доставлені'::text,'доставили'::text,'Швабра з віджимом і решта обладнання були доставлені в офіс учора.'::text),
(350718,38969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fregona giratoria y el resto del equipo ... a la oficina ayer.'::text,'fueron entregados'::text,'son entregados'::text,'entregaron'::text,'La fregona giratoria y el resto del equipo fueron entregados a la oficina ayer.'::text),
(350717,38969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La serpillière rotative et le reste de l''équipement ... au bureau hier.'::text,'ont été livrés'::text,'sont livrés'::text,'ont livré'::text,'La serpillière rotative et le reste de l''équipement ont été livrés au bureau hier.'::text),
(350720,38969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Döner paspas ve ekipmanın geri kalanı dün ofise ...'::text,'teslim edildi'::text,'teslim ediliyor'::text,'teslim etti'::text,'Döner paspas ve ekipmanın geri kalanı dün ofise teslim edildi.'::text),
(350721,38969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A forgófejes felmosó és a többi felszerelés tegnap ... az irodába.'::text,'lett kiszállítva'::text,'van kiszállítva'::text,'kiszállították'::text,'A forgófejes felmosó és a többi felszerelés tegnap lett kiszállítva az irodába.'::text),
(350724,38970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Morgen ... die Ausrüstung in die Gondel geladen, bevor der Reiniger nach unten fährt.'::text,'wird'::text,'lädt'::text,'ladend'::text,'Jeden Morgen wird die Ausrüstung in die Gondel geladen, bevor der Reiniger nach unten fährt.'::text),
(350728,38970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоранку обладнання ... в люльку, перш ніж мийник спускається вниз.'::text,'завантажується'::text,'завантажує'::text,'завантаження'::text,'Щоранку обладнання завантажується в люльку, перш ніж мийник спускається вниз.'::text),
(350727,38970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada mañana, el equipo ... en la plataforma antes de que el limpiador baje.'::text,'se carga'::text,'carga'::text,'cargando'::text,'Cada mañana, el equipo se carga en la plataforma antes de que el limpiador baje.'::text),
(350726,38970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque matin, l''équipement ... dans la nacelle avant que le laveur descende.'::text,'est chargé'::text,'charge'::text,'chargeant'::text,'Chaque matin, l''équipement est chargé dans la nacelle avant que le laveur descende.'::text),
(350729,38970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her sabah temizlikçi aşağı inmeden önce ekipman platforma ...'::text,'yükleniyor'::text,'yüklüyor'::text,'yükleyerek'::text,'Her sabah temizlikçi aşağı inmeden önce ekipman platforma yükleniyor.'::text),
(350730,38970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden reggel ... a felszerelést a függőkosárba, mielőtt a takarító leereszkedik.'::text,'bepakolják'::text,'bepakol'::text,'bepakolva'::text,'Minden reggel bepakolják a felszerelést a függőkosárba, mielőtt a takarító leereszkedik.'::text),
(350733,38971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Allein der Schleudermopp hat 90 % des Budgets verbraucht, also ... diese Ausrüstung nicht billig sein.'::text,'kann'::text,'muss'::text,'könnte'::text,'Allein der Schleudermopp hat 90 % des Budgets verbraucht, also kann diese Ausrüstung nicht billig sein.'::text),
(350737,38971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише швабра з віджимом з''їла 90 % бюджету, тож це обладнання ... бути дешевим.'::text,'не може'::text,'мусить'::text,'може'::text,'Лише швабра з віджимом з''їла 90 % бюджету, тож це обладнання не може бути дешевим.'::text),
(350736,38971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo la fregona giratoria se llevó el 90 % del presupuesto, así que este equipo ... ser barato.'::text,'no puede'::text,'debe de'::text,'podría'::text,'Solo la fregona giratoria se llevó el 90 % del presupuesto, así que este equipo no puede ser barato.'::text),
(350735,38971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La serpillière rotative à elle seule a coûté 90 % du budget, donc cet équipement ... être bon marché.'::text,'ne peut pas'::text,'doit'::text,'pourrait'::text,'La serpillière rotative à elle seule a coûté 90 % du budget, donc cet équipement ne peut pas être bon marché.'::text),
(350738,38971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sadece döner paspas bütçenin %90''ını yedi, yani bu ekipman ucuz ...'::text,'olamaz'::text,'olmalı'::text,'olabilir'::text,'Sadece döner paspas bütçenin %90''ını yedi, yani bu ekipman ucuz olamaz.'::text),
(350739,38971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyedül a forgófejes felmosó elvitte a büdzsé 90%-át, tehát ez a felszerelés ... olcsó.'::text,'nem lehet'::text,'biztosan'::text,'lehet'::text,'Egyedül a forgófejes felmosó elvitte a büdzsé 90%-át, tehát ez a felszerelés nem lehet olcsó.'::text),
(350742,38972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ausrüstung, ... der Reiniger benutzt, ist zum Putzen. Deshalb putzt er damit.'::text,'die'::text,'wer'::text,'deren'::text,'Die Ausrüstung, die der Reiniger benutzt, ist zum Putzen. Deshalb putzt er damit.'::text),
(350746,38972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обладнання, ... користується прибиральник, — для прибирання. Тому він ним і прибирає.'::text,'яким'::text,'хто'::text,'чиє'::text,'Обладнання, яким користується прибиральник, — для прибирання. Тому він ним і прибирає.'::text),
(350745,38972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo ... usa el limpiador es para limpiar. Por eso limpia con él.'::text,'que'::text,'quien'::text,'cuyo'::text,'El equipo que usa el limpiador es para limpiar. Por eso limpia con él.'::text),
(350744,38972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipement ... le nettoyeur utilise sert à nettoyer. C''est pour ça qu''il nettoie avec.'::text,'que'::text,'qui'::text,'dont'::text,'L''équipement que le nettoyeur utilise sert à nettoyer. C''est pour ça qu''il nettoie avec.'::text),
(350747,38972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Temizlikçinin ... kullandığı ekipman temizlik için. O yüzden onunla temizlik yapıyor.'::text,''::text,NULL::text,NULL::text,'Temizlikçinin kullandığı ekipman temizlik için. O yüzden onunla temizlik yapıyor.'::text),
(350748,38972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A felszerelés, ... a takarító használ, takarításra való. Ezért takarít vele.'::text,'amit'::text,'aki'::text,'aminek'::text,'A felszerelés, amit a takarító használ, takarításra való. Ezért takarít vele.'::text),
(353163,39241,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade das dreckige Waschbecken, als ich reinkam, und ehrlich, dieser Fokus!'::text,'schrubbtest'::text,'schrubbtest'::text,'schrubbtest'::text,'Du schrubbtest gerade das dreckige Waschbecken, als ich reinkam, und ehrlich, dieser Fokus!'::text),
(353167,39241,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... той брудний умивальник, коли я зайшла, і чесно, яка зосередженість!'::text,'відтирав'::text,'відтер'::text,'відтер'::text,'Ти відтирав той брудний умивальник, коли я зайшла, і чесно, яка зосередженість!'::text),
(353166,39241,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ese lavabo asqueroso cuando entré y, sinceramente, ¡qué concentración!'::text,'Estabas frotando'::text,'Frotaste'::text,'Has frotado'::text,'Estabas frotando ese lavabo asqueroso cuando entré y, sinceramente, ¡qué concentración!'::text),
(353165,39241,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... ce lavabo crasseux quand je suis entrée, et franchement, quelle concentration !'::text,'frottais'::text,'as frotté'::text,'as frotté'::text,'Tu frottais ce lavabo crasseux quand je suis entrée, et franchement, quelle concentration !'::text),
(353168,39241,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İçeri girdiğimde o pis lavaboyu ... ve açıkçası, o odaklanma!'::text,'ovuyordun'::text,'ovdun'::text,'ovdun'::text,'İçeri girdiğimde o pis lavaboyu ovuyordun ve açıkçası, o odaklanma!'::text),
(353169,39241,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... azt a mocskos mosdót, amikor beléptem, és őszintén, micsoda fókusz!'::text,'súroltad'::text,'kisúroltad'::text,'kisúroltad'::text,'Épp súroltad azt a mocskos mosdót, amikor beléptem, és őszintén, micsoda fókusz!'::text),
(353172,39242,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zwanzig Minuten Haare von dieser dreckigen Ablage. Eindeutig ein entspannter Abend.'::text,'wischt'::text,'wischt'::text,'wischt'::text,'Er wischt seit zwanzig Minuten Haare von dieser dreckigen Ablage. Eindeutig ein entspannter Abend.'::text),
(353176,39242,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже двадцять хвилин ... волосся з цієї брудної стільниці. Явно розслаблений вечір.'::text,'витирає'::text,'витирає'::text,'витирає'::text,'Він уже двадцять хвилин витирає волосся з цієї брудної стільниці. Явно розслаблений вечір.'::text),
(353175,39242,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pelos de esta encimera asquerosa desde hace veinte minutos. Está claro que es una noche relajante.'::text,'Quita'::text,'Está quitando'::text,'Quita'::text,'Quita pelos de esta encimera asquerosa desde hace veinte minutos. Está claro que es una noche relajante.'::text),
(353174,39242,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des cheveux sur ce comptoir crasseux depuis vingt minutes. Clairement une soirée relaxante.'::text,'essuie'::text,'est en train d''essuyer'::text,'essuie'::text,'Il essuie des cheveux sur ce comptoir crasseux depuis vingt minutes. Clairement une soirée relaxante.'::text),
(353177,39242,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yirmi dakikadır bu pis tezgâhtan saç ...; belli ki rahatlatıcı bir akşam.'::text,'siliyor'::text,'siliyor'::text,'siler'::text,'Yirmi dakikadır bu pis tezgâhtan saç siliyor; belli ki rahatlatıcı bir akşam.'::text),
(353178,39242,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Húsz perce ... a hajat erről a mocskos pultról. Nyilván pihentető este.'::text,'törölgeti'::text,'törölgeti'::text,'törölgeti'::text,'Húsz perce törölgeti a hajat erről a mocskos pultról. Nyilván pihentető este.'::text),
(353190,39244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat das dreckige Waschbecken ..., also ist es jetzt wieder weiß.'::text,'geputzt'::text,'geputzt'::text,'geputzt'::text,'Er hat das dreckige Waschbecken geputzt, also ist es jetzt wieder weiß.'::text),
(353194,39244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... брудний умивальник, тож тепер він знову білий.'::text,'вичистив'::text,'чистив'::text,'чистить'::text,'Він вичистив брудний умивальник, тож тепер він знову білий.'::text),
(353193,39244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el lavabo asqueroso, así que ahora vuelve a estar blanco.'::text,'Ha limpiado'::text,'Ha estado limpiando'::text,'Está limpiando'::text,'Ha limpiado el lavabo asqueroso, así que ahora vuelve a estar blanco.'::text),
(353192,39244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le lavabo crasseux, alors maintenant il est de nouveau blanc.'::text,'a nettoyé'::text,'nettoie'::text,'est en train de nettoyer'::text,'Il a nettoyé le lavabo crasseux, alors maintenant il est de nouveau blanc.'::text),
(353195,39244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pis lavaboyu ..., o yüzden artık yine bembeyaz.'::text,'temizledi'::text,'temizliyor'::text,'temizliyor'::text,'Pis lavaboyu temizledi, o yüzden artık yine bembeyaz.'::text),
(353196,39244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a mocskos mosdót, úgyhogy most megint fehér.'::text,'Kitakarította'::text,'Takarította'::text,'Takarítja'::text,'Kitakarította a mocskos mosdót, úgyhogy most megint fehér.'::text),
(353199,39245,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor er anfing, ... sich jemand die Haare geschnitten und das Bad dreckig hinterlassen.'::text,'hatte'::text,'hat'::text,'hatte'::text,'Bevor er anfing, hatte sich jemand die Haare geschnitten und das Bad dreckig hinterlassen.'::text),
(353203,39245,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж він почав, хтось ... собі волосся й залишив ванну брудною.'::text,'підстриг'::text,'підстриг'::text,'стриже'::text,'Перш ніж він почав, хтось підстриг собі волосся й залишив ванну брудною.'::text),
(353202,39245,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que empezara, alguien se ... el pelo y dejó el baño asqueroso.'::text,'había cortado'::text,'ha cortado'::text,'corta'::text,'Antes de que empezara, alguien se había cortado el pelo y dejó el baño asqueroso.'::text),
(353201,39245,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''il commence, quelqu''un ... les cheveux et avait laissé la salle de bain crasseuse.'::text,'s''était coupé'::text,'s''est coupé'::text,'se coupe'::text,'Avant qu''il commence, quelqu''un s''était coupé les cheveux et avait laissé la salle de bain crasseuse.'::text),
(353204,39245,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O başlamadan önce biri saçını ... ve banyoyu pis bırakmıştı.'::text,'kesmişti'::text,'kesti'::text,'kesiyor'::text,'O başlamadan önce biri saçını kesmişti ve banyoyu pis bırakmıştı.'::text),
(353205,39245,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt nekikezdett, valaki ... a haját, és mocskosan hagyta a fürdőt.'::text,'levágta'::text,'levágta'::text,'vágja'::text,'Mielőtt nekikezdett, valaki levágta a haját, és mocskosan hagyta a fürdőt.'::text),
(353208,39246,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, morgen um diese Zeit ... er schon wieder diesen dreckigen Spiegel, kein Witz.'::text,'putzt'::text,'putzt'::text,'putzt'::text,'Alter, morgen um diese Zeit putzt er schon wieder diesen dreckigen Spiegel, kein Witz.'::text),
(353212,39246,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, завтра о цій порі він знову ... те брудне дзеркало, без жартів.'::text,'витиратиме'::text,'витре'::text,'витирає'::text,'Чувак, завтра о цій порі він знову витиратиме те брудне дзеркало, без жартів.'::text),
(353211,39246,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mañana a esta hora ... otra vez ese espejo asqueroso, en serio.'::text,'estará limpiando'::text,'limpiará'::text,'limpia'::text,'Tío, mañana a esta hora estará limpiando otra vez ese espejo asqueroso, en serio.'::text),
(353210,39246,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, demain à la même heure, il ... encore ce miroir crasseux, sans mentir.'::text,'essuiera'::text,'essuiera'::text,'essuie'::text,'Mec, demain à la même heure, il essuiera encore ce miroir crasseux, sans mentir.'::text),
(353213,39246,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatlerde yine o pis aynayı ..., yemin ederim.'::text,'siliyor olacak'::text,'silecek'::text,'siliyor'::text,'Kanka, yarın bu saatlerde yine o pis aynayı siliyor olacak, yemin ederim.'::text),
(353214,39246,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor megint azt a mocskos tükröt ..., komolyan.'::text,'fogja törölgetni'::text,'törli majd'::text,'törli'::text,'Tesó, holnap ilyenkor megint azt a mocskos tükröt fogja törölgetni, komolyan.'::text),
(353217,39247,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Bericht des Vermieters stand, das Bad ... zu dreckig für die Besichtigung um 15 Uhr.'::text,'sei'::text,'ist'::text,'wird'::text,'Im Bericht des Vermieters stand, das Bad sei zu dreckig für die Besichtigung um 15 Uhr.'::text),
(353221,39247,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У звіті орендодавця йшлося, що ванна ... надто брудною для огляду о 15:00.'::text,'була'::text,'є'::text,'буде'::text,'У звіті орендодавця йшлося, що ванна була надто брудною для огляду о 15:00.'::text),
(353220,39247,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El informe del casero decía que el baño ... demasiado sucio para la visita de las 15:00.'::text,'estaba'::text,'está'::text,'estará'::text,'El informe del casero decía que el baño estaba demasiado sucio para la visita de las 15:00.'::text),
(353219,39247,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le rapport du propriétaire indiquait que la salle de bain ... trop crasseuse pour la visite de 15 h.'::text,'était'::text,'est'::text,'sera'::text,'Le rapport du propriétaire indiquait que la salle de bain était trop crasseuse pour la visite de 15 h.'::text),
(353222,39247,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahibinin raporunda banyonun saat 15.00''teki gösterim için fazla pis ... yazıyordu.'::text,'olduğu'::text,'olduğu'::text,'olacağı'::text,'Ev sahibinin raporunda banyonun saat 15.00''teki gösterim için fazla pis olduğu yazıyordu.'::text),
(353223,39247,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A főbérlő jelentése szerint a fürdőszoba túl mocskos ... a délután 3-as megtekintéshez.'::text,'volt'::text,NULL::text,'lesz'::text,'A főbérlő jelentése szerint a fürdőszoba túl mocskos volt a délután 3-as megtekintéshez.'::text),
(353226,39248,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ablage ... dreckig, aber jetzt ist sie sauber, weil er sie geputzt hat.'::text,'war früher'::text,'war früher'::text,'war es gewohnt'::text,'Die Ablage war früher dreckig, aber jetzt ist sie sauber, weil er sie geputzt hat.'::text),
(353230,39248,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стільниця ... брудною, але тепер вона чиста, бо він її вичистив.'::text,'раніше була'::text,'раніше була'::text,'звикла бути'::text,'Стільниця раніше була брудною, але тепер вона чиста, бо він її вичистив.'::text),
(353229,39248,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La encimera ... estar asquerosa, pero ahora está limpia porque él la limpió.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'La encimera solía estar asquerosa, pero ahora está limpia porque él la limpió.'::text),
(353228,39248,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le comptoir ... crasseux avant, mais maintenant il est propre parce qu''il l''a nettoyé.'::text,'était'::text,'était'::text,'avait l''habitude d''être'::text,'Le comptoir était crasseux avant, mais maintenant il est propre parce qu''il l''a nettoyé.'::text),
(353231,39248,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tezgâh eskiden pis ..., ama şimdi temiz çünkü o temizledi.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Tezgâh eskiden pis olurdu, ama şimdi temiz çünkü o temizledi.'::text),
(353232,39248,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pult régen mocskos ..., de most tiszta, mert kitakarította.'::text,'szokott lenni'::text,'lett volna'::text,'hozzá volt szokva'::text,'A pult régen mocskos szokott lenni, de most tiszta, mert kitakarította.'::text),
(353235,39249,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt beendet das ... der dreckigen Ablage und wendet sich anschließend dem Spiegel zu.'::text,'Abwischen'::text,'Abwischen'::text,'abgewischt'::text,'Das Subjekt beendet das Abwischen der dreckigen Ablage und wendet sich anschließend dem Spiegel zu.'::text),
(353239,39249,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт закінчує ... брудну стільницю і згодом повертається до дзеркала.'::text,'витирати'::text,'витирати'::text,'витер'::text,'Суб''єкт закінчує витирати брудну стільницю і згодом повертається до дзеркала.'::text),
(353238,39249,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto termina de ... la encimera asquerosa y a continuación se vuelve hacia el espejo.'::text,'limpiar'::text,'limpiar'::text,'limpió'::text,'El sujeto termina de limpiar la encimera asquerosa y a continuación se vuelve hacia el espejo.'::text),
(353237,39249,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet finit de ... le comptoir crasseux puis se tourne vers le miroir.'::text,'nettoyer'::text,'nettoyer'::text,'nettoyé'::text,'Le sujet finit de nettoyer le comptoir crasseux puis se tourne vers le miroir.'::text),
(353240,39249,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek pis tezgâhı ... bitirir ve ardından aynaya döner.'::text,'silmeyi'::text,'silmeyi'::text,'sildi'::text,'Denek pis tezgâhı silmeyi bitirir ve ardından aynaya döner.'::text),
(353241,39249,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany befejezi a mocskos pult ..., majd ezt követően a tükör felé fordul.'::text,'letörlését'::text,'letörlését'::text,'letörölte'::text,'Az alany befejezi a mocskos pult letörlését, majd ezt követően a tükör felé fordul.'::text),
(353244,39250,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... dieses dreckige Bad schon ewig, und endlich glänzt es.'::text,'putzt'::text,'putzt'::text,'putzt'::text,'Ehrlich gesagt, du putzt dieses dreckige Bad schon ewig, und endlich glänzt es.'::text),
(353248,39250,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... цю брудну ванну вже цілу вічність, і нарешті вона сяє.'::text,'прибираєш'::text,'прибираєш'::text,'прибираєш'::text,'Не буду брехати, ти прибираєш цю брудну ванну вже цілу вічність, і нарешті вона сяє.'::text),
