(353246,39250,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... cette salle de bain crasseuse depuis une éternité, et elle brille enfin.'::text,'nettoies'::text,'es en train de nettoyer'::text,'nettoies'::text,'Je vais pas mentir, tu nettoies cette salle de bain crasseuse depuis une éternité, et elle brille enfin.'::text),
