(353250,39250,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, már ezer éve ... ezt a mocskos fürdőszobát, és végre ragyog.'::text,'takarítod'::text,'takarítod'::text,'takarítod'::text,'Nem hazudok, már ezer éve takarítod ezt a mocskos fürdőszobát, és végre ragyog.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
